window.TXB=window.TXB||{};TXB["alab/Isa"]={"1:1":"هذه هي رؤيا إشعياء بن آموص، التي أعلنت له بشأن يهوذا وأورشليم في أثناء حكم كل من عزيا ويوثام وآحاز وحزقيا ملوك يهوذا.","1:2":"اسمعي أيتها السماوات وأصغي أيتها الأرض لأن الرب يتكلم: «ربيت أبناء وأنشأتهم ولكنهم تمردوا علي.","1:3":"الثور يعرف قانيه، والحمار معلف صاحبه، أما إسرائيل فلا يعرف، وشعبي لا يدرك.","1:4":"ويل للأمة الخاطئة، الشعب المثقل بالإثم، ذرية مرتكبي الشر، أبناء الفساد. لقد تركوا الرب واستهانوا بقدوس إسرائيل وداروا على أعقابهم.","1:5":"على أي موضع أضربكم بعد؟ لماذا تواظبون على التمرد؟ إن الرأس بجملته سقيم والقلب بكامله مريض.","1:6":"من أخمص القدم إلى قمة الرأس ليس فيه عافية. كله جروح وأحباط وقروح لم تنظف، ولم تضمد، ولم تلين بالزيت.","1:7":"عم الخراب بلادكم والتهمت النار مدنكم. نهب الغرباء حقولكم أمام أعينكم. هي خربة، عاث فيها الغرباء فسادا.","1:8":"فأضحت أورشليم مهجورة كمظلة حارس في كرم أو خيمة في حقل للقثاء أو كمدينة محاصرة.","1:9":"لولا أن الرب القدير حفظ لنا بقية يسيرة، لأصبحنا مثل سدوم وعمورة.","1:10":"اسمعوا كلمة الرب ياحكام سدوم. أصغوا إلى شريعة إلهنا ياأهل عمورة:","1:11":"ماذا تجديني كثرة ذبائحكم، يقول الرب؟ اتخمت من محرقات كباش وشحم المسمنات، ولا أسر بدم عجول وخرفان وتيوس.","1:12":"حين جئتم لتمثلوا أمامي، من طلب منكم أن تدوسوا دوري؟","1:13":"كفوا عن تقديم قرابين باطلة، فالبخور رجس لي، وكذلك رأس الشهر والسبت والدعاء إلى المحفل، فأنا لا أطيق الاعتكاف مع ارتكاب الإثم.","1:14":"لشد ما تبغض نفسي احتفالات رؤوس شهوركم ومواسم أعيادكم! صارت علي عبئا، وسئمت حملها.","1:15":"عندما تبسطون نحوي أيديكم أحجب وجهي عنكم، وإن أكثرتم الصلاة لا أستجيب، لأن أيديكم مملوءة دما.","1:16":"اغتسلوا، تطهروا، أزيلوا شر أعمالكم من أمام عيني. كفوا عن اقتراف الإثم،","1:17":"وتعلموا الإحسان، انشدوا الحق، انصفوا المظلوم، اقضوا لليتيم، ودافعوا عن الأرملة.","1:18":"تعالوا نتحاجج يقول الرب، إن كانت خطاياكم كلطخات قرمزية فإنها تبيض كالثلج، وإن كانت حمراء كصبغ الدودي تصبح في نقاء الصوف!","1:19":"إن شئتم وأطعتم تتمتعون بخيرات الأرض،","1:20":"ولكن إن أبيتم وتمردتم فالسيف يلتهمكم، لأن فم الرب قد تكلم.","1:21":"كيف صارت المدينة الأمينة عاهرة؟ كانت تفيض حقا، ويأوي إليها العدل، فأصبحت وكرا للمجرمين.","1:22":"صارت فضتك مزيفة، وخمرك مغشوشة بماء.","1:23":"أصبح رؤساؤك عصاة وشركاء لصوص، يولعون بالرشوة ويسعون وراء الهبات، لا يدافعون عن اليتيم، ولا ترفع إليهم دعوى الأرملة».","1:24":"لذلك يقول السيد رب الجنود، عزيز إسرائيل: «لأستريحن من مقاومي ولأنتقمن من أعدائي.","1:25":"لأعاقبنك وأنقينك من غشك كما تنقى المعادن بالبورق، وأصفينك من قصديرك،","1:26":"وأعيد قضاتك كما كانوا في الحقب الغابرة، ومشيريك كما كانوا في العهود الأولى. عندئذ تدعين مدينة العدل، المدينة الأمينة.","1:27":"فتفدى صهيون بالحق، وتائبوها بالبر.","1:28":"أما العصاة والخطاة فيتحطمون جميعا، ويبيد الذين تركوا الرب.","1:29":"ويعتريكم خجل لعبادتكم شجرة البلوط التي شغفتم بها، والعار لإيثاركم الحدائق بأوثانها.","1:30":"لأنكم تصبحون كبلوطة ذبلت أوراقها، أو حديقة غاض منها الماء،","1:31":"فيصير القوي كنسالة وأعماله (الشريرة) شرارة لاهبة فيحترقان معا بنار لا يقوى أحد على إخمادها».","2:1":"الإعلان الذي رآه إشعياء بن آموص بشأن يهوذا وأورشليم:","2:2":"ويحدث في آخر الأيام، أن جبل هيكل الرب يصبح أسمى من كل الجبال، ويعلو فوق كل التلال، فتتوافد إليه جميع الأمم.","2:3":"وتقبل شعوب كثيرة وتقول: تعالوا لنذهب إلى جبل الرب، إلى بيت إله يعقوب، فيعلمنا طرقه، ونسلك في سبله، لأن من صهيون تخرج الشريعة، ومن أورشليم تعلن كلمة الرب.","2:4":"فيقضي بين الأمم ويحكم بين الشعوب الكثيرة، فيطبعون سيوفهم محاريث ورماحهم مناجل، ولا ترفع أمة على أمة سيفا، ولا يتدربون على الحرب فيما بعد.","2:5":"يابيت يعقوب، هيا لنسلك في نور الرب.","2:6":"فأنت يارب قد نبذت شعبك، بيت يعقوب، فكثر بينهم العرافون من أبناء المشرق والمتنبئون، كالفلسطينيين، وتعاهدوا مع الغرباء.","2:7":"امتلأت أرضهم فضة وذهبا، وكنوزهم لا نهاية لها، واكتظت بلادهم بالخيل، ومركباتهم لا تحصى.","2:8":"غصت أرضهم بالأصنام، وعبدوا صنعة أيديهم، وسجدوا لعمل أصابعهم.","2:9":"لذلك ينحط الإنسان، ويذل البشر، ولا تصفح عنهم.","2:10":"اختف في مغاور الجبال، واختبيء في حفر الأرض خشية من هيبة الرب ومن جلال مجده.","2:11":"فعيون البشر المتشامخة تخفض، وكبرياؤهم تذل، ويتعظم الرب وحده في ذلك اليوم.","2:12":"فإن للرب القدير يوما فيه يوضع كل متعظم ومتكبر ومتغطرس.","2:13":"ويسمو على أرز لبنان المتعالي الشامخ، وعلى كل بلوط باشان،","2:14":"وعلى كل جبل أشم، وعلى التلال المرتفعة،","2:15":"وعلى كل برج عال، وسور حصين،","2:16":"وعلى كل سفن ترشيش، وعلى كل صنعة جميلة،","2:17":"فيعتري الهوان غطرسة كل إنسان، ويذل تشامخ البشر، ويتعظم الرب وحده في ذلك اليوم،","2:18":"وتباد الأصنام كلها،","2:19":"ويلجأ الناس إلى مغاور الجبال، وإلى حفائر الأرض، متوارين من هيبة الرب ومن مجد جلاله، عندما يهب ليزلزل الأرض.","2:20":"في ذلك اليوم يطرح الناس للجرذان والخفافيش أوثانهم الفضية وأصنامهم الذهبية التي صنعوها ليعبدوها،","2:21":"ويدخلون في كهوف الصخر، وفي شقوق الجروف الجبلية هربا من هيبة الرب ومن مجد جلاله عندما يهب ليزلزل الأرض.","2:22":"كفوا عن الاتكال على الإنسان المعرض للموت؛ فأي قيمة له؟","3:1":"ها هو الرب القدير مزمع أن يقطع عن أورشليم ويهوذا الطعام والماء.","3:2":"ويقضي فيها على كل بطل ومحارب وقاض ونبي وعراف وشيخ","3:3":"وعلى كل قائد وعظيم ومشير وصانع ماهر وساحر بارع.","3:4":"وأجعل الصبيان رؤساء لهم، والأطفال حكاما عليهم،","3:5":"فيجور الشعب بعضهم على بعض، والرجل على صاحبه، والجار على جاره، ويتمرد الصغير على الكبير والحقير على النبيل.","3:6":"عندئذ يقبض الإنسان على أخيه في بيت أبيه قائلا له: «إن عندك ثوبا، فاملك علينا لتنقذنا من هذه الفوضى».","3:7":"فيجيبهم قائلا: «لست طبيبا، ولا أملك طعاما أو ثيابا في بيتي، فلا تجعلوني رئيسا للشعب».","3:8":"قد كبت أورشليم؛ انهارت يهوذا لأنهما أساءتا بالقول والفعل إلى الرب وتمردتا على سلطانه.","3:9":"ملامح وجوههم تشهد عليهم، إذ يجاهرون بخطيئتهم كسدوم ولا يسترونها، فويل لهم لأنهم جلبوا على أنفسهم شرا.","3:10":"ولكن بشروا الصديقين بالخير لأنهم سيتمتعون بثواب أعمالهم","3:11":"أما الشرير فويل له وبئس المصير لأنه يجازى على ما جنته يداه","3:12":"ظالمو شعبي أولاد والحاكمون عليه نساء. آه ياشعبي! إن قادتكم يضلونكم ويقتادونكم في مسالك منحرفة.","3:13":"لقد تربع الرب على كرسي القضاء، قام ليدين الناس.","3:14":"الرب يدخل في المحاكمة ضد شيوخ شعبه وقادتهم. ويقول السيد الرب القدير: «أنتم الذين أتلفتم كرمي، وصار سلب البائس في منازلكم.","3:15":"فماذا تقصدون من سحق شعبي وطحن وجوه البائسين؟»","3:16":"ويقول الرب: «لأن بنات صهيون متغطرسات، يمشين بأعناق مشرئبة متغزلات بعيونهن، متخطرات في سيرهن، مجلجلات بخلاخيل أقدامهن.","3:17":"سيصيبهن الرب بالصلع، ويعري عوراتهن».","3:18":"في ذلك اليوم ينزع الرب زينة الخلاخيل، وعصابات رؤوسهن والأهلة،","3:19":"والأقراط والأساور والبراقع،","3:20":"والعصائب والسلاسل والأحزمة، وآنية الطيب والتعاويذ","3:21":"والخواتم وخزائم الأنف،","3:22":"والثيا ب المزخرفة والعباءات والمعاطف والأكياس","3:23":"والمرايا والأردية الكتانية، والعصائب المزينة وأغطية الرؤوس","3:24":"فتحل العفونة محل الطيب، والحبل عوض الحزام، والصلع بدل الشعر المنسق، وحزام المسح في موضع الثوب الفاخر، والعار عوض الجمال،","3:25":"فيسقط رجالك في الحرب، ويلقى أبطالك حتفهم في ساحة الوغى","3:26":"فتنوح عليهم أبواب المدينة وتنطرح على الأرض مهجورة.","4:1":"في ذلك اليوم تتشبث سبع نساء برجل واحد قائلات:«تزوج منا ودعنا ندعى على اسمك، وأزل عارنا ونحن نتكفل بطعامنا وثيابنا».","4:2":"في ذلك اليوم يكون غصن الرب بهيا مجيدا، وثمر الأرض فخرا ومجدا لمن نجا من إسرائيل،","4:3":"ويدعى كل من يبقى في صهيون ممن مكث في أورشليم قدوسا، كل من كتب للحياة في أورشليم،","4:4":"إذ يغسل الرب قذر بنات صهيون، ويطهر أورشليم من لطخات الدماء بروح العدل وبروح النار المحرقة.","4:5":"ثم يخلق الرب فوق جبل صهيون بكامله، وعلى محفلها، سحابة نهارا، ودخانا ووهج لهيب نار ليلا، فيكون على كل أرض مجيدة غطاء.","4:6":"فتكون مظلة وفيئا تقيها حر النهار، ومعتصما ومخبأ من العاصفة والمطر.","5:1":"سأشدو لحبيبي أغنية عن كرمه: كان لحبيبي كرم على تل خصيب،","5:2":"حرث أرضه ونقاه من الحجارة، وغرس فيه أفضل كرمة، وشيد في وسطه برجا، ونقر في الصخر معصرة. ثم انتظر أن يثمر له عنبا فأنتج له حصرما!","5:3":"والآن ياأهل أورشليم ورجال يهوذا، احكموا بيني وبين كرمي.","5:4":"أي شيء يمكن أن يصنع لكرمي لم أصنعه؟ وعندما انتظرت منه أن يثمر لي عنبا، لماذا أنتج حصرما؟","5:5":"وا لآن أخبركم ما أصنع بكرمي: سأزيل سياجه فيصبح مرعى ماشية، وأهدم سوره فيضحى مداس أقدام،","5:6":"وأجعله خرابا فلا يقلم ولا ينقب، فينبت فيه شوك وحسك. وأوصي السحاب أن لا يمطر عليه أبدا.","5:7":"لأن كرم الرب القدير هو بيت إسرائيل، ورجال يهوذا هم غرس بهجته. ولكن عندما انتظر حقا وجد سفك دماء، وعندما التمس عدلا رأى صراخا.","5:8":"اشتريتم البيوت والحقول حتى لم يبق لأحد غيركم مكان يسكن فيه! صارت الأرض لكم وحدكم!","5:9":"سمعت الرب القدير يقول: «البيوت العظيمة لابد أن تصبح خرابا، والمنازل الفخمة تغدو مهجورة.","5:10":"فعشرة فدادين كروم لا تغل سوى بث واحد (مئتين وعشرين لترا) من النبيذ، وحومر (عشر كيلات) من البذور ينتج كيلة واحدة.","5:11":"ويل لمن ينهضون في الصباح مبكرين يسعون وراء المسكر حتى ساعة متأخرة من الليل إلى أن تلهبهم الخمر.","5:12":"يتلهون في مآدبهم بالعود والرباب والدف والناي والخمر، غير مكترثين لأعمال الرب ولا ناظرين إلى صنع يديه،","5:13":"لذلك يسبى شعبي لأنهم لا يعرفون، ويموت عظماؤهم جوعا، ويهلك العامة ظمأ.","5:14":"لهذا وسعت الهاوية أحشاءها وفغرت شدقها إلى ما لا نهاية، لينحدر فيها شرفاء أورشليم وجماهيرها وعجيجها وكل طرب فيها","5:15":"ويذل الإنسان ويخفض الناس، ويحط كل متشامخ فيها.","5:16":"ولكن الرب القدير يمجد بالعدل، ويبدي الرب القدوس قداسته بالبر.","5:17":"عندئذ ترعى الحملان في مراعيهم، والخرفان والماعز تأكل بين خربهم.","5:18":"ويل لمن يجرون الإثم بحبال الباطل، والخطيئة بمثل أمراس العربة","5:19":"ويقولون: ليسرع وليعجل بعقابه حتى نراه. لينفذ مقدس إسرائيل مأربه فينا فندرك حقيقة ما يفعله بنا.","5:20":"ويل لمن يدعون الشر خيرا، والخير شرا، الجاعلين الظلمة نورا والنور ظلمة والمرارة حلاوة والحلاوة مرارة!","5:21":"ويل للحكماء في أعين أنفسهم، والأذكياء في نظر ذواتهم.","5:22":"ويل للعتاة في شرب الخمر والمتفوقين في مزج المسكر،","5:23":"الذين يبرئون المذنب بفضل الرشوة، وينكرون على البريء حقه.","5:24":"لهذا كما تلتهم النار القش، وكما يفنى الحشيش الجاف في اللهب، كذلك يصيب أصولهم العفن، ويتناثر زهرهم كالتراب، لأنهم نبذوا شريعة الله واستهانوا بكلمة قدوس إسرائيل","5:25":"لذلك احتدم غضب الرب ضد شعبه، فمد يده عليهم وضربهم، فارتعشت الجبال، وأصبحت جثث موتاهم كالقاذورات في الشوارع. ومع ذلك كله لم يرتد غضبه ولم تبرح يده ممدودة بالعقاب.","5:26":"فيرفع راية لأمم بعيدة، ويصفر لمن في أطراف الأرض، فيقبلون مسرعين (إلى أورشليم)،","5:27":"دون أن يكلوا أو يتعثروا أو يعتريهم نعاس أو نوم، أو يحل أحد منهم حزاما عن حقويه، ولا ينقطع لأحد سيور حذاء.","5:28":"سهامهم مسننة، وقسيهم مشدودة. حوافر خيلهم كأنها صوان. عجلات مركباتهم مندفعة كالإعصار.","5:29":"زئيرهم كأنه زئير أسد يزمجر وينقض على فريسته ويحملها وليس من منقذ.","5:30":"يزمجرون عليها في ذلك اليوم كهدير البحر. وإن جاس أحد في البلاد متفرسا لا يرى سوى الظلمة والضيق، حتى (انفراجات) الضوء (أي ومضات الرجاء) قد احتجبت وراء سحبه.","6:1":"وفي سنة وفاة الملك عزيا، شاهدت السيد جالسا على عرش مرتفع سام، وقد امتلأ الهيكل من أهدابه،","6:2":"وأحاط به ملائكة السرافيم، لكل واحد منهم ستة أجنحة، أخفى وجهه بجناحين، وغطى قدميه بجناحين، ويطير بالجناحين الباقيين.","6:3":"ونادى أحدهم الآخر: «قدوس، قدوس، قدوس الرب القدير. مجده ملء كل الأرض».","6:4":"فاهتزت أسس أركان الهيكل من صوت المنادي، وامتلأ الهيكل بالدخان.","6:5":"فقلت: «ويل لي لأني هلكت لأني إنسان نجس الشفتين، وأسكن وسط قوم دنسي الشفاه. فإن عيني قد أبصرتا الملك الرب القدير».","6:6":"فطار أحد السرافيم إلي وبيده جمرة أخذها من على المذبح،","6:7":"ومس بها فمي قائلا: «انظر، ها إن هذه قد مست شفتيك فانتزع إثمك وتم التكفير عن خطيئتك».","6:8":"وسمعت صوت الرب يقول: «من أرسل، ومن يذهب من أجلنا؟» عندئذ قلت: «ها أنا أرسلني».","6:9":"فقال: «امض وقل لهذا الشعب: اسمعوا سمعا ولكن لا تفهموا. انظروا نظرا و لكن لا تدركوا.","6:10":"قس قلب هذا الشعب، وثقل أذنيه وأغمض عينيه لئلا يرى بعينيه ويسمع بأذنيه ويفهم بقلبه، فيرجع عن غيه ويبرأ».","6:11":"ثم قلت: «إلى متى يارب؟» فأجاب: «إلى أن تصبح المدن خربة مهجورة، والبيوت خالية من الرجال، والحقول خرابا مقفرا.","6:12":"وينفي الرب الإنسان بعيدا، وتكثر الأماكن الموحشة في وسط الأرض.","6:13":"وحتى لو بقي بعد ذلك عشر أهلها، فإنها ستحرق ثانية، ولكنها تكون كالبطمة والبلوطة، التي وإن قطعت يبقى ساقها قائما: هكذا يبقى ساقها زرعا مقدسا».","7:1":"وفي أيام آحاز بن يوثام بن عزيا ملك يهوذا، صعد رصين ملك أرام مع فقح بن رمليا ملك إسرائيل على أورشليم لمحاربتها، فعجزا عن قهرها.","7:2":"ولما قيل لملك يهوذا إن الأراميين تحالفوا مع الإسرائيليين، اعترى قلبه وقلوب شعبه الاضطراب، كأشجار الغابة تهزها ريح عاصفة.","7:3":"فقال الرب لإشعياء: «امض لملاقاة آحاز أنت وشآرياشوب ابنك عند طرف قناة البركة العليا في طريق حقل القصار،","7:4":"وقل له: احترس، وتمالك روعك؛ لا تخف ولا يهن قلبك من غضب رصين ملك أرام وابن رمليا المحتدم فإنهما كحطبتين مضطرمتين مدخنتين.","7:5":"فإن أرام وابن رمليا مع أفرايم قد تآمروا ضدك لينزلوا بك شرا قائلين:","7:6":"لنهاجم يهوذا ونمزقها ونتقاسمها بيننا، ونملك عليها ابن طبئيل.","7:7":"ولكن هذا ما يقوله الرب: إن هذا الأمر لن يتم ولن يكون،","7:8":"لأن رأس أرام هي دمشق، ورأس دمشق هو رصين، وفي غضون خمس وستين سنة تتمزق مملكة إسرائيل ولا تكون أمة بعد.","7:9":"إن رأس أفرايم هي السامرة، ورأس السامرة هو ابن رمليا. وإن لم تؤمنوا فلن تأمنوا».","7:10":"ثم عاد الرب يخاطب آحاز ثانية قائلا:","7:11":"«اطلب علامة من الرب إلهك، سواء في عمق الهاوية أو في ارتفاع أعلى السماوات».","7:12":"فأجاب آحاز: «لن أطلب ولن أجرب الرب».","7:13":"عندئذ قال إشعياء: «اسمعوا يابيت داود: أما كفاكم أنكم أضجرتم الناس حتى تضجروا إلهي أيضا؟","7:14":"ولكن السيد نفسه يعطيكم آية: ها العذراء تحبل وتلد ابنا، وتدعو اسمه عمانوئيل.","7:15":"وحين يعرف أن يميز بين الخير والشر يأكل زبدا وعسلا،","7:16":"لأنه قبل أن يعرف الصبي كيف يرفض الشر ويختار الخير، فإن إسرائيل وأرام اللتين تخشيان ملكيهما تصبحان مهجورتين.","7:17":"وسيجلب الرب عليك وعلى شعبك وعلى بيت أبيك أياما لم تمر بكم منذ انفصال أفرايم عن يهوذا، وذلك على يد ملك أشور.","7:18":"في ذلك اليوم يصفر الرب للمصريين فيجيئون عليكم من كل أنهار مصر، وللأشوريين فيجيئون عليكم كأسراب النحل،","7:19":"فتقبل كلها وتنتشر في الأودية المقفرة، وفي شقوق الصخور وشجيرات الشوك المتكاثفة، وفي المراعي قاطبة.","7:20":"في ذلك اليوم يستأجر الرب ملك أشور من عبر نهر الفرات، فيكون الموسى التي يحلق بها الرب شعر رؤوسكم وأرجلكم، وحتى لحاكم أيضا.","7:21":"في ذلك اليوم يربي واحد عجلة بقر وشاتين.","7:22":"ولوفرة ما تدر من حليب يأكل الزبد، لأن الزبد والعسل يأكلهما كل من يستبقى في الأرض.","7:23":"في ذلك اليوم يصير كل موضع كان فيه ألف جفنة بألف شاقل (نحو اثني عشر كيلو جراما) من الفضة، منبتا للشوك والحسك.","7:24":"ولا يقتحم الأرض إلا كل من يحمل سهاما وأقواسا، لأنها أرض مليئة بالشوك والحسك.","7:25":"أما الجبال التي كانت تنقب بالمعول، فلا يصعد إليها أحد خوفا من الشوك والحسك، فتصبح مسرحا للثيران وموطئا للغنم».","8:1":"ثم قال الرب لي: «خذ لنفسك لوحا كبيرا، واكتب عليه بحروف واضحة «مهير شلال حاش بز» (بمعنى مسرع إلى الغنيمة)»","8:2":"فاخترت لنفسي شاهدين أمينين، هما أوريا الكاهن وزكريا بن يبرخيا.","8:3":"ثم عاشرت النبية فحملت وأنجبت ابنا. فقال لي الرب: «ادع اسمه مهير شلال حاش بز،","8:4":"وقبل أن يعرف الصبي كيف ينادي: ياأبي أو ياأمي، تحمل ثروة دمشق وغنائم السامرة أمام ملك أشور».","8:5":"ثم كلمني الرب ثانية قائلا:","8:6":"«من حيث أن هذا الشعب قد رفض مياه شيلوه الجارية الهادئة، وتهافتوا على رصين وفقح بن رمليا،","8:7":"فإن الرب مزمع أن يغرقهم بمياه النهر الفياضة، أي ملك أشور بكل جبروته، فيكون (كنهر الفرات) يطغى جيشانه على أقنيته ويفيض على ضفافه","8:8":"فيكتسح أرض يهوذا، ويطفو مرتفعا إلى الأعناق، وتنتشر جيوشه في عرض أرضك ياعمانوئيل».","8:9":"افعلوا ما شئتم أيها الشعوب وانهزموا. أصغي ياجميع أقاصي الأرض. تأهبوا للمعركة وانهزموا.","8:10":"تشاوروا معا ولكن على غير طائل، ارسموا الخطط فلا تتحقق لأن الله معنا.","8:11":"لأن الرب خاطبني حين وضع يده علي وأنذرني أن لا أسلك في طريق هذا الشعب قائلا:","8:12":"«لا تقل إنها مؤامرة لكل ما يدعي هذا الشعب أنه مؤامرة. لا تخش ما يخشون ولا تخف.","8:13":"قدسوا الرب القدير لأنه هو خوفكم ورهبتكم،","8:14":"فيكون لكم مقدسا. أما لبيتي إسرائيل، فيكون حجر صدمة وصخرة عثرة، وفخا وشركا لساكني أورشليم،","8:15":"فيعثر بها كثيرون ويسقطون ويتحطمون ويقعون في الفخ ويقتنصون».","8:16":"فادخر الشهادة (ياالله)، واختم الشريعة (في قلوب) تلاميذي.","8:17":"سأنتظر الرب الذي يحجب وجهه عن بيت يعقوب وأتوكل عليه.","8:18":"انظروا ها أنا والأبناء الذين رزقني إياهم الرب، آيات ومعجزات في إسرائيل من عند الرب القدير الساكن في جبل صهيون.","8:19":"وعندما يقول الناس لك: اسأل أصحاب التوابع والعرافين المتهامسين المجمجمين قل: أليس على الشعب أن يسأل إلهه؟ أعليهم أن يسألوا الأموات عن الأحياء؟","8:20":"فإلى الشريعة وإلى الشهادة: ومن لا ينطق بمثل هذا القول، فلا فجر له.","8:21":"فإنهم يتيهون في الأرض مكتئبين جائعين، وعندما يعضهم الجوع بنابه يأخذهم الغضب ويلعنون ملكهم وإلههم ويلتفتون إلى العلاء،","8:22":"ثم ينظرون إلى الأرض فلا يجدون سوى الكرب والظلمة والضنك والعذاب، ويطردون إلى دياجير الظلام.","9:1":"ولكن لن يخيم ظلام على التي تعاني من الضيق، فكما أذل الله في الزمن الغابر أرض زبولون ونفتالي، فإنه في الزمن الأخير يكرم طريق البحر وعبر الأردن، جليل الأمم.","9:2":"الشعب السالك في الظلمة أبصر نورا عظيما، والمقيمون في أرض ظلال الموت أضاء عليهم نور.","9:3":"كثرت الأمة وزدتها فرحا، ابتهجوا في حضرتك كما يبتهجون في أوان الحصاد وكما يبتهج الذين يتقاسمون الغنائم.","9:4":"لأنك قد حطمت، كما في يوم مديان، نير ثقله وعصا كتفه وقضيب مسخره.","9:5":"إذ كل سلاح المتسلح في الوغى، وكل رداء ملطخ بالدماء، يطرح وقودا للنار ويحرق.","9:6":"لأنه يولد لنا ولد ويعطى لنا ابن يحمل الرياسة على كتفه، ويدعى اسمه عجيبا، مشيرا، إلها قديرا، أبا أبديا، رئيس السلام.","9:7":"ولا تكون نهاية لنمو رياسته وللسلام اللذين يسودان عرش داود ومملكته، ليثبتها ويعضدها بالحق والبر، من الآن وإلى الأبد. إن غيرة الرب القدير تتمم هذا.","9:8":"لقد أصدر الرب قضاءه على يعقوب فوقع في إسرائيل،","9:9":"فيعلم الشعب كله: أفرايم وسكان السامرة القائلون بزهو وكبرياء قلب:","9:10":"«قد تساقط اللبن ولكننا سنبني بحجارة منحوتة. قد قطع الجميز ولكننا نعتاض عنه بخشب الأرز!»","9:11":"ولكن الرب يثير عليهم خصومهم ويؤلب عليهم أعداءهم،","9:12":"فينقض الأراميون من الشرق، والفلسطينيون من الغرب ليلتهموا إسرائيل بشدق فاغر، ومع كل هذا فإن غضبه لم يرتد، ويده ما برحت ممدودة للعقاب.","9:13":"إن الشعب لم يرجع تائبا إلى من عاقبه، ولا طلب الرب القدير.","9:14":"لذلك سيقطع الرب من إسرائيل في يوم واحد الرأس والذنب، النخل والأسل.","9:15":"إن الشيخ والوجيه هو الرأس، والنبي الذي يلقن الكذب هو الذنب","9:16":"فمرشدو هذا الشعب يضلونه، والمرشدون يبتلعون.","9:17":"لذلك لا يسر الرب بشبانهم، ولا يترَأف على أيتامهم وأراملهم، لأن جميعهم منافقون وفاعلو شر، كل فم ينطق بالحماقة، ومع كل هذا فإن غضبه لم يرتد، وما برحت يده ممدودة للعقاب.","9:18":"لأن الفجور يحرق كالنار فتلتهم الشوك والحسك بل تشعل أجمات الغابة فتتصاعد منها سحب الدخان.","9:19":"إن الأرض تحترق بغضب الرب القدير، والشعب كوقود للنار. لا يرحم واحد أخاه.","9:20":"يلتهمون ذات اليمين ولكن يظلون جياعا، ويفترسون ذات الشمال ولا يشبعون. كل واحد منهم يأكل لحم أخيه.","9:21":"منسى ضد أفرايم، وأفرايم ضد منسى، ولكنهما يتحدان ضد يهوذا. من أجل ذلك كله لم يرتد غضبه، وما برحت يده ممدودة للعقاب!","10:1":"ويل للذين يسنون شرائع ظلم، وللكتبة الذين يسجلون أحكام جور!","10:2":"ليصدوا البائسين عن العدل، ويسلبوا مساكين شعبي حقهم، لتكون الأرامل مغنما لهم، وينهبوا اليتامى.","10:3":"فماذا تصنعون في يوم العقاب عندما تقبل الكارثة من بعيد؟ إلى من تلجأون طلبا للعون، وأين تودعون ثروتكم؟","10:4":"لا يبقى شيء سوى أن تجثوا بين الأسرى، وتسقطوا بين القتلى. من أجل ذلك كله لم يرتد غضبه وما برحت يده ممدودة للعقاب.","10:5":"ويل للأشوريين، قضيب غضبي، الحاملين في أيديهم عصا سخطي.","10:6":"أرسلهم ضد أمة منافقة، وأوصيهم على شعبي الذي غضبت عليه، ليغنموا غنائمهم ويستولوا على أسلابهم، ويطأوهم كما يطأون الوحل.","10:7":"ولكن ملك أشور لا يعرف أنني أنا الذي أرسلته، ويظن أنه بقدرته قد هاجم شعبي، وفي نيته أن يدمر ويجتاح أمما كثيرة.","10:8":"لأنه يقول: أليس كل قوادي ملوكا؟","10:9":"أليس مصير كلنو كمصير كركميش؟ أو ليس مآل حماة كمآل أرفاد؟ أليست السامرة كدمشق؟","10:10":"لقد قضيت على ممالك وثنية أصنامها أعظم من أصنام أورشليم والسامرة!","10:11":"أفلا أقضي على أورشليم وأصنامها كما قضيت على السامرة وأصنامها؟","10:12":"ولكن حالما ينتهي الرب من عمله بجبل صهيون، فإنه سيعاقب ملك أشور على غرور قلبه وتشامخ عينيه،","10:13":"لأنه يقول: بقوة ذراعي قد صنعت هذا، وبحكمتي، لأنني فهيم! قد نقلت تخوم الأمم، ونهبت كنوزهم، وعزلت الجالسين على العروش كما يفعل ذو البطش.","10:14":"وكما تستحوذ يد الإنسان على العش، هكذا استحوذت يدي على ثروات الشعوب. وكما يجمع الإنسان البيض المهجور، هكذا جمعت الأرض بأسرها، فلم يجرؤ أحد أن يحرك جناحا أو يفتح فاها أو ينبس بهمسة.","10:15":"أتزهو الفأس على من يقطع بها، أم يتعظم المنشار على من ينشر به، وكأن القضيب يحرك رافعه، أو كأن العصا ترفع ما ليس خشبا؟!","10:16":"لذلك فإن الرب القدير سيفشي وبأ مهلكا بين محاربيه الشجعان، ويوقد تحت مجده وقيدا كاشتعال النار،","10:17":"فيصبح نور إسرائيل نارا، وقدوسه لهيبا، فتشتعل وتلتهم شوكه وحسكه في يوم واحد،","10:18":"فيدمر الرب مجد غاباته وأرضه الخصيبة، الروح والجسد معا، فتكون كمريض تذوي حياته،","10:19":"ولا يتبقى من أشجار الغابة إلا قلة يحصيها صبي.","10:20":"في ذلك اليوم لا تعود بقية إسرائيل والناجون منهم يتوكلون على من ضربهم، بل يعتمدون على الرب قدوس إسرائيل بالحق.","10:21":"وترجع بقية ذرية يعقوب إلى الرب القدير.","10:22":"مع أن شعبك ياإسرائيل كرمل البحر، فإن بقية فقط ترجع، لأن الله قضى بفنائهم، وقضاؤه عادل.","10:23":"فالرب القدير يجري الفناء والقضاء في وسط كل الأرض.","10:24":"لذلك هكذا يقول الرب القدير: «ياشعبي المقيم في صهيون، لا تخف من أشور عندما يضربك بقضيب، ويرفع عليك عصاه كما فعل المصريون،","10:25":"فإنه عما قليل يكتمل سخطي، وينصب غضبي لإبادتهم».","10:26":"ولا يلبث الرب القدير أن يهز عليه سوطا كما ضرب المديانيين عند صخرة غراب، ويرفع قضيبه فوق البحر مثلما فعل في مصر.","10:27":"في ذلك اليوم يتدحرج حمله عن كتفك، ويتحطم نيره عن عنقك لأن عنقك أصبح غليظا.","10:28":"ها هو جيش أشور مقبل؛ قد وصل إلى عياث، واجتاز بمجرون. وضع مؤونته في مخماش.","10:29":"قطعوا المعبر، وباتوا في جبع. ارتعد أهل الرامة، وهرب سكان جبعة شاول.","10:30":"اصرخي يابنت جليم، واسمعي ياليشة، وأجيبي يامدينة عناثوث.","10:31":"هرب أهل مدمنة. فر سكان جيبيم طلبا للنجاة.","10:32":"اليوم يتوقف في نوب ويهز قبضته على جبل بنت صهيون، أكمة أورشليم.","10:33":"لكن الرب القدير يحطم الأغصان بعنفوان. فكل متطاول يقطع، وكل متشامخ يذل.","10:34":"تستأصل أجمات الغابة بفأس، ويسقط لبنان أمام جبار مهوب.","11:1":"ويفرخ برعم من جذع يسى، وينبت غصن من جذوره،","11:2":"ويستقر عليه روح الرب، روح الحكمة والفطنة، روح المشورة والقوة، روح معرفة الرب ومخافته.","11:3":"وتكون مسرته في تقوى الرب، ولا يقضي بحسب ما تشهد عيناه، ولا يحكم بمقتضى ما تسمع أذناه،","11:4":"إنما يقضي بعدل للمساكين، ويحكم بالإنصاف لبائسي الأرض، ويعاقب الأرض بقضيب فمه، ويميت المنافق بنفخة شفتيه،","11:5":"لأنه سيرتدي البر ويتمنطق بالأمانة.","11:6":"فيسكن الذئب مع الحمل، ويربض النمر إلى جوار الجدي، ويتآلف العجل والأسد وكل حيوان معلوف معا، ويسوقها جميعا صبي صغير.","11:7":"ترعى البقرة والدب معا، ويربض أولادهما متجاورين، ويأكل الأسد التبن كالثور،","11:8":"ويلعب الرضيع في (أمان) عند جحر الصل، ويمد الفطيم يده إلى وكر الأفعى (فلا يصيبه سوء).","11:9":"لا يؤذون ولا يسيئون في كل جبل قدسي، لأن الأرض تمتليء من معرفة الرب كما تغمر المياه البحر.","11:10":"في ذلك اليوم ينتصب أصل يسى راية للأمم، وإليه تسعى جميع الشعوب، ويكون مسكنه مجيدا.","11:11":"فيعود الرب ليمد يده ثانية ليسترد البقية الباقية من شعبه، من أشور ومصر وفتروس وكوش وعيلام وشنعار وحماة، ومن جزائر البحر،","11:12":"وينصب راية للأمم ويجمع منفيي إسرائيل ومشتتي يهوذا من أربعة أطراف الأرض،","11:13":"فيتلاشى حسد أفرايم، وتزول عداوة يهوذا، فلا أفرايم يحسد يهوذا، ولا يهوذا يعادي أفرايم،","11:14":"وينقضان على أكتاف الفلسطينيين غربا ويغزوان أبناء المشرق معا، ويستوليان على بلاد أدوم وموآب، ويخضع لهم بنو عمون.","11:15":"ويجفف الرب تماما لسان بحر مصر، ويهز يده على النهر فتهب ريح عاصفة تقسم ماءه إلى سبع ممرات تعبر فيها الجيوش.","11:16":"ويمد الرب طريقا من أشور ليعود منه من بقي هناك من بني إسرائيل، كما أعاد الرب جميع إسرائيل من مصر.","12:1":"وتقول في ذلك اليوم: «أحمدك يارب، لأنك وإن غضبت علي، فإن غضبك يرتد عني وتعزيني.","12:2":"ها إن الله خلاصي فأطمئن ولا أرتعد، لأن الرب الله هو قوتي وترنيمتي وقد أصبح لي خلاصا».","12:3":"فتستقون ببهجة من ينابيع الخلاص.","12:4":"وتقولون في ذلك اليوم: «احمدوا الرب، نادوا باسمه، عرفوا بأفعاله بين الشعوب، وأذيعوا أن اسمه قد تعالى.","12:5":"اشدوا للرب لأنه قد صنع عظائم. ليعلن ذلك في الأرض كلها","12:6":"اهتفوا وتغنوا ياأهل صهيون، لأن قدوس إسرائيل عظيم بينكم».","13:1":"رؤيا إشعياء بن آموص بشأن بابل:","13:2":"انصبوا راية فوق جبل أجرد. اصرخوا فيهم لوحوا بأيديكم حتى يدخلوا أبواب العظماء.","13:3":"إني أمرت مقدسي واستدعيت جبابرتي المفتخرين بعظمتي لينفذوا عقاب غضبي.","13:4":"ها جلبة على الجبال مثل صوت أقوام غفيرة. صوت صخب ممالك أمم مجتمعة، لأن الرب القدير يستعرض جنود القتال.","13:5":"يقبلون من أرض نائية، من أقصى السماوات هم جنود الرب وأسلحة سخطه لتدمير الأرض كلها.","13:6":"ولولوا، فإن يوم الرب بات وشيكا قادما من عند الرب محملا بالدمار.","13:7":"لذلك ترتخي كل يد، ويذوب قلب كل إنسان.","13:8":"ينتابهم الفزع، وتأخذهم أوجاع ومخاض، يتلوون كوالدة تقاسي من آلآم المخاض. ويحملق بعضهم ببعض مبهوتين بوجوه ملتهبة.","13:9":"ها هو يوم الرب آت مفعما بالقسوة والسخط والغضب العنيف، ليجعل الأرض خرابا ويبيد منها الخطاة.","13:10":"فإن نجوم السماء وكواكبها لا تشرق بنورها، والشمس تظلم عند بزوغها، والقمر لا يشع بضوئه.","13:11":"وأعاقب العالم على شره والمنافقين على آثامهم، وأضع حدا لصلف المتغطرسين وأذل كبرياء العتاة،","13:12":"فيصبح الرجال لقلة عددهم أندر من الذهب النقي وأعز من ذهب أوفير.","13:13":"وأزلزل السماوات فتتزعزع الأرض في موضعها من غضب الرب القدير في يوم احتدام سخطه.","13:14":"وتولي جيوش بابل الأدبار حتى ينهكها التعب، عائدين إلى أرضهم كأنهم غزال مطارد أو غنم لا راعي لها.","13:15":"كل من يؤسر يطعن، ومن يقبض عليه يصرع بالسيف،","13:16":"ويمزق أطفالهم على مرأى منهم، وتنهب بيوتهم، وتغتصب نساؤهم.","13:17":"ها أنا أثير عليهم الماديين الذين لا يكترثون للفضة ولا يسرون بالذهب،","13:18":"تمزق قسيهم الفتيان ولا يرحمون الأولاد أو الرضع.","13:19":"أما بابل، مجد الممالك وبهاء وفخر الكلدانيين، فتصبح كسدوم وعمورة اللتين قلبهما الله .","13:20":"لا يسكن فيها، ولا تعمر من جيل إلى جيل، لا ينصب فيها بدوي خيمته، ولا يربض فيها راع قطعانه.","13:21":"إنما تأوي إليها وحوش القفر وتعج بيوت خرائبها بالبوم، وتلجأ إليها بنات النعام، وتتواثب فيها الماعز البرية،","13:22":"وتتعاوى الضباع بين أبراجها، وبنات آوى بين قصورها الفخمة. إن وقت عقابها بات وشيكا، وأيامها لن تطول!","14:1":"ولكن الرب ينعم برحمته على ذرية يعقوب، ويصطفي شعب إسرائيل ثانية ويحلهم في أرضهم، فينضم الغرباء إليهم ويلحقون ببيت يعقوب.","14:2":"وتمد شعوب الأرض إليهم يد العون ليساعدوا إسرائيل على العودة لدياره. ويصيرون عبيدا لبني إسرائيل، في أرض الرب، ويتسلطون على آسريهم وظالميهم.","14:3":"في ذلك اليوم يريحكم الرب من عنائكم وشقائكم وعبوديتكم القاسية،","14:4":"فتسخرون من ملك بابل قائلين: كيف استكان الظالم، وكيف خمدت غضبته المتعجرفة؟","14:5":"قد حطم الرب عصا المنافق وصولجان المتسلطين،","14:6":"الذين انهالوا على الناس ضربا بسخط لا يتوقف؛ الذين تسلطوا على الأمم بغضب واضطهاد شديد.","14:7":"فاستراحت الأرض كلها وسادها الهدوء، فتغنت شعوبها ترنما.","14:8":"حتى شجر السرو وأرز لبنان عمها الفرح فقالت: «منذ أن انكسرت شوكتك لم يصعد إلينا قاطع حطب»","14:9":"ثارت الهاوية من أسفل لاَستقبالك عند قدومك وحشدت الأخيلة، من كل العظماء، لتحيتك؛ أنهضت كل ملوك الأمم عن عروشهم","14:10":"كلهم يخاطبونك قائلين: لقد صرت ضعيفا مثلنا، أصبحت مماثلا لنا!","14:11":"طرحت كل عظمتك في الهاوية مع رنة عيدانك، وأصبحت الرمم فراشك والدود غطاء لك!","14:12":"كيف هويت من السماء يازهرة بنت الصبح؟ كيف قطعت وطرحت إلى الأرض ياقاهر الأمم؟","14:13":"قد قلت في قلبك: إني أرتقي إلى السماء وأرفع عرشي فوق كواكب الله، وأجلس على جبل الاجتماع في أقصى الشمال","14:14":"أرتقي فوق أعالي السحاب، وأصبح مثل العلي.","14:15":"ولكنك طرحت إلى الهاوية، إلى أعماق الجب.","14:16":"والذين يرونك يحملقون فيك ويتأملون متسائلين: أهذا هو الإنسان الذي زعزع الأرض وهز الممالك؟","14:17":"الذي حول المسكونة إلى مثل القفر، وقلب مدنها، ولم يطلق أسراه ليرجعوا إلى بيوتهم؟","14:18":"لقد رقد كل ملوك الأمم بكرامة، كل في ضريحه،","14:19":"أما أنت فقد طرحت بعيدا عن قبرك كغصن مكسور تغطيك رمم قتلى المعارك الذين انحدروا إلى مقر الموتى، وصرت كجنة داستها حوافر الخيل","14:20":"لا تنضم إليهم في مدفن، لأنك خربت أرضك، وذبحت شعبك، فذرية فاعلي الإثم يبيد ذكرها إلى الأبد.","14:21":"أعدوا مذبحة لأبنائه جزاء إثم آبائهم، لئلا يقوموا ويرثوا الأرض فيملأوا وجه البسيطة مدنا.","14:22":"إني أهب ضدهم، يقول الرب القدير، وأمحو من بابل اسما وبقية ونسلا وذرية،","14:23":"وأجعلها ميراثا للقنافذ، ومستنقعات للمياه، وأكنسها بمكنسة الدمار».","14:24":"لقد أقسم الرب القدير قائلا: «حقا ما عزمت عليه لابد أن يتحقق، وما نويت عليه حتما يتم:","14:25":"أن أحطم أشور في أرضي وأطأه على جبالي، فيلقي عنهم نيره، ويزول عن كاهلهم حمله.","14:26":"هذا هو القضاء الذي حكمت به على الأرض كلها، وهذه هي اليد التي امتدت على كل الأمم.","14:27":"لأن الرب القدير قد قضى، فمن يبطل قضاءه؟ ويده قد امتدت فمن يردها؟»","14:28":"وفي السنة التي توفي فيها الملك آحاز أوحى الرب لإشعياء:","14:29":"«لا تفرحي ياكل فلسطين، لأن القضيب الذي ضربك قد انكسر. فإن من أصل تلك الأفعى يخرج أفعوان، وذريته تكون ثعبانا ساما طيارا","14:30":"أما أبكار البائسين فيرعون، والمساكين يربضون آمنين. لكنني أهلك أصلك بالمجاعة وأقضي على بقيتك.","14:31":"ولول أيها الباب ونوحي أيتها المدينة! ذوبي خوفا يافلسطين قاطبة لأن جيشا مدربا قد زحف نحوك من الشمال","14:32":"فبماذا نجيب رسل الأمة؟ لتقل لهم: قد أسس الرب أورشليم ليلوذ بها منكوبو شعبه».","15:1":"رؤيا بشأن موآب: حقا في ليلة مباغتة تخرب عار موآب، حقا في ليلة مباغتة تدمر قير موآب.","15:2":"ينطلق أهل ديبون إلى المعبد، وحتى إلى المرتفعات للبكاء؛ يولول شعب موآب على مصير نبو وميدبا برؤوس وذقون محلوقة.","15:3":"يتلفعون بالمسوح في شوارعها، ويبكي كل واحد منهم على السطوح وفي الساحات.","15:4":"تتعالى صرخات حشبون وألعالة حتى تتردد أصداؤها في ياهص، لذلك يندب جيش موآب بصوت مرتفع، وقلوبهم ترتعد في صدورهم.","15:5":"قلبي يصرخ متوجعا على موآب وعلى عظمائها الهاربين إلى صوغر. كعجلة ثلاثية يصعدون إلى عقبة اللوحيث مولولين، ويجهرون بصراخ الهزيمة في طريق حورونايم.","15:6":"غاضت مياه نهر نمريم، وجف العشب على ضفتيه، وذوى الكلأ وبادت الخضرة","15:7":"لذلك يحملون ما ادخروه من ثروة ونفائس، وينقلونها إلى عبر وادي الصفصاف،","15:8":"إذ يتجاوب صراخهم على طول تخوم موآب، وتبلغ ولولتهم إلى أجلايم وبئر إيليم.","15:9":"تفيض مياه ديمون دما لأني أزيد من ويلاتها، فتهاجم الأسود الناجين من موآب، وتفترس الهاربين والماكثين فيها.","16:1":"أيها الهاربون من موآب إلى سالع في الصحراء، أرسلوا حملانا إلى ملك يهوذا في أورشليم (طلبا للحماية قائلين):","16:2":"نساء موآب على ضفاف أرنون مثل الطيور التائهة أو الفراخ الشاردة.","16:3":"فانصحنا، أنصفنا، ليكن ظلك علينا في الظهيرة كالليل فتستر منفيينا عن عيون أعدائنا ولا تشي باللاجئين منا.","16:4":"لتمكث معكم فلول الهاربين منا واعصمهم من مدمرهم لأن الباغي يبيد والدمار يكف والظالم يفنى من الأرض.","16:5":"ولا يلبث أن يثبت بالرحمة عرش في بيت داود يجلس عليه بأمانة ملك يقضي بالعدل والإنصاف.","16:6":"قد سمعنا بكبرياء موآب، وبعجرفتها وغطرستها الطاغيتين، وبغرورها وصلفها، ولكن كل افتخارها باطل.","16:7":"لذلك يولول الموآبيون على موآب، ويئنون على قير حارس المدمرة.","16:8":"ذبلت حقول حشبون وكروم سبمة التي أتلف أمراء الأمم أفضلها، التي وصلت يوما إلى يعزير، وامتدت إلى القفر وبلغت فروعها إلى الصحراء.","16:9":"لذلك أبكي كبكاء يعزير على جفنات سبمة وأرويكما بدموعي ياحشبون وياألعالة. لأن جلبة الدمار قد وقعت على حصادك وقطافك.","16:10":"وانتزع الفرح والابتهاج من روضتك، فلم يبق أحد يرنم أو يهتف في كرومك، ولا يوجد من يدوس الخمر في معصرتك، لأني قد أخرست الهتاف.","16:11":"لهذا تئن روحي على موآب كعود، وأحشائي تتلوى على قير حارس.","16:12":"وعندما يحضر الموآبيون إلى المرتفعات المشرفة، يأخذهم الإعياء، وعندما يذهبون إلى مقادسهم ليصلوا، يجنون الباطل.","16:13":"هذا ما تكلم الرب به على موآب منذ زمن.","16:14":"وها هو يتكلم الآن قائلا: «في غضون ثلاث سنوات، كسنوات الأجير، يذل مجد موآب، ويحتقر جميع شعبها، والناجون منهم يكونون قلة ضعيفة».","17:1":"نبوءة بشأن دمشق: «انظروا ها دمشق تنقرض من بين المدن وتصبح كومة أنقاض.","17:2":"تهجر مدن عروعير، وتصبح مراعي للقطعان تربض فيها ولا أحد يخيفها","17:3":"تزول المدينة المحصنة من أفرايم، والملك من دمشق، وتصبح بقية أرام مماثلة لمجد أبناء إسرائيل الزائل، هذا ما يقوله الرب القدير.","17:4":"في ذلك اليوم يخبو مجد يعقوب وتذوب سمانة بدنه،","17:5":"فتصبح جرداء كحقل جمع الحصادون زرعه، أو حصدت ذراعه السنابل، أو كرجل يلتقط السنابل في وادي رفايم.","17:6":"ومع ذلك تبقى فيه خصاصة، كزيتونة نفضت حباتها، فتساقطت إلا حبتين أو ثلاثا ظلت في رأس أعلى غصن، أو أربع أو خمس حبات في الأفنان المثمرة، هذا ما يقوله الرب القدير.","17:7":"في ذلك اليوم يرنو الناس إلى صانعهم ويلتفتون بعيونهم إلى قدوس إسرائيل،","17:8":"ولا يلتفتون إلى المذابح التي صنعتها أيديهم، ولا ينظرون إلى تماثيل السواري والشموس، ولا إلى مذابح البخور صنعة أصابعهم.","17:9":"في ذلك اليوم تصبح مدنهم المنيعة مقفرة كمدن الحثيين والأموريين التي هجروها هربا من الإسرائيليين فأصبحت خرابا.","17:10":"لأنكم قد نسيتم إله خلاصكم، ولم تذكروا صخرة عزكم. لذلك وإن كنتم تزرعون غرسا مبهجا وتغرسون زرعا غريبا،","17:11":"وإن كنتم يوم تغرسونه تنمونه، وفي الصباح عندما تزرعونه تجعلونه يزهر، فإن الحصيد لا يكون منتجا في يوم الضربة المهلكة التي لا برء منها.","17:12":"يالجلبة شعوب كثيرة يضجون كبحر عجاج! يالصخب الأمم! فإنهم يصخبون كعجيج لجج غامرة.","17:13":"أمم تهدر كهدير المياه، ولكن حالما يزجرها الرب تهرب بعيدا، وتتطاير كما تتطاير عصافة الجبال أمام الريح، أو كالهباء أمام العاصفة.","17:14":"في المساء يطغى عليهم رعب، وفي الصباح يتلاشون. هذا هو نصيب ناهبينا وحظ سالبينا.","18:1":"ويل لأرض حفيف الأجنحة في عبر أنهار كوش،","18:2":"التي تبعث رسلا في البحر في قوارب البردي السابحة فوق المياه، امضوا أيها الرسل المسرعون إلى شعب طوال القامة جرد، إلى شعب بث الرعب في القاصي والداني، إلى قوم أقوياء وقاهرين تشطر الأنهار أرضهم.","18:3":"ياجميع أهل الأرض والساكنين فيها، عندما ترتفع راية على الجبال فانظروا، وعندما يدوي نفير بوق فاسمعوا.","18:4":"لأنه هكذا قال الرب لي: سأمكث هادئا ناظرا من مقر سكناي، كحر صاف تحت أشعة الشمس أو كسحاب الطل في حر الحصاد","18:5":"لأنه قبل الحصاد عندما يتم تفتح الزهر، ويتحول الزهر إلى عنب ناضج، فإنه يقطع الفروع بالمناجل، وينزع الأغصان الممتدة ويطرحها،","18:6":"وتترك كلها لجوارح الجبال ووحوش الأرض، فتلتهمها الجوارح في الصيف، وتتغذى بها الوحوش في الشتاء».","18:7":"في ذلك الوقت يقدم الشعب الطويل القامة الأجرد، الذي بث الرعب في القاصي والداني، الأمة القوية القاهرة التي تشطر الأنهار أرضها، هدايا إلى الرب القدير في جبل صهيون، موضع اسم الرب القدير.","19:1":"نبوءة بشأن مصر: ها هو الرب قادم إلى مصر يركب سحابة سريعة، فترتجف أوثان مصر في حضرته، وتذوب قلوب المصريين في داخلهم.","19:2":"وأثير مصريين على مصريين فيتحاربون، ويقوم الواحد على أخيه، والمدينة على المدينة والمملكة على المملكة،","19:3":"فتذوب أرواح المصريين في داخلهم، وأبطل مشورتهم، فيسألون الأوثان والسحرة وأصحاب التوابع والعرافين.","19:4":"وأسلط على المصريين مولى قاس، فيسود ملك عنيف عليهم. هذا ما يقوله الرب القدير.","19:5":"وتنضب مياه النيل وتجف الأحواض وتيبس.","19:6":"تنتن القنوات، وتتناقص تفرعات النيل وتجف، ويتلف القصب والأسل.","19:7":"وتذبل النباتات على ضفاف نهر النيل، والحقول والمزروعات كلها تجف، وكأنها لم تكن مخضرة.","19:8":"فيئن الصيادون وطارحو الشصوص في النيل وينوحون ويتحسر الذين يلقون شباكهم في المياه.","19:9":"ويتولى اليأس قلوب الذين يصنعون الكتان الممشط، ويفقد حائكو الكتان الفاخر كل أمل.","19:10":"ويسحق الرجال، أعمدة الأرض، ويكتئب كل عامل أجير.","19:11":"رؤساء صوعن حمقى، ومشورات أحكم حكماء فرعون غبية. كيف تقولون لفرعون نحن من نسل حكماء، وأبناء ملوك قدامى؟","19:12":"أين حكماؤك يا فرعون ليطلعوك على ما قضى به الرب القدير على مصر؟","19:13":"قد حمق رؤساء صوعن وانخدع أمراء نوف وأضل مصر شرفاء قبائلها","19:14":"جعل الرب فيها روح فوضى، فأضلوا مصر فى كل تصرفاتها، حتى ترنحت كترنح السكران في قيئه.","19:15":"فلم يبق لعظمائها أو أدنيائها ما يفعلونه فيها.","19:16":"في ذلك اليوم يرتعد المصريون كالنساء خوفا من يد الرب القدير التي يهزها فوقهم.","19:17":"وتغدو أرض يهوذا مثار رعب للمصريين فيعتريها الفزع من ذِكرها لأن الرب القدير قد قضى قضاءه على مصر.","19:18":"في ذلك اليوم يكون في ديار مصر خمس مدن تنطق بلغة كنعان، وتحلف بالولاء للرب القدير، وتدعى إحداها مدينة الشمس.","19:19":"في ذلك اليوم يقام مذبح للرب في وسط ديار مصر، ويرتفع نصب للرب عند تخومها،","19:20":"فيكون علامة وشهادة للرب القدير في ديار مصر، لأنهم يستغيثون بالرب من مضايقيهم، فيبعث إليهم مخلصا ومدافعا ينقذهم.","19:21":"فيعلن الرب نفسه للمصريين. وفي ذلك اليوم يعبدونه ويقدمون ذبيحة وقرابين وينذرون للرب نذورا ويوفون بها.","19:22":"ويضرب الرب مصر؛ يضربها ويبرئها، فيرجع أهلها تائبين إلى الرب فيستجيب دعاءهم ويشفيهم.","19:23":"في ذلك اليوم يمتد طريق من مصر إلى أشور، ومن أشور إلى مصر، فيعبد المصريون والأشوريون الرب معا.","19:24":"في ذلك اليوم يكون إسرائيل ثالث ثلاثة مع مصر وأشور، وبركة في وسط الأرض،","19:25":"فيباركهم الرب القدير قائلا: «مبارك شعبي مصر، وصنعة يدي أشور، وميراثي إسرائيل».","20:1":"وفي السنة التي أوفد فيها سرجون ملك أشور ترتان رئيس جيشه إلى أشدود وحاربها وقهرها،","20:2":"تكلم الرب على لسان إشعياء بن آموص قائلا: «اذهب واخلع المسوح عن حقويك، وانزع حذاءك من قدميك». ففعل كذلك ومشى عاريا حافيا.","20:3":"وقال الرب: «كما مشى عبدي إشعياء عاريا حافيا لمدة ثلاث سنوات علامة وآية على المصائب التي سأنزلها بمصر وكوش،","20:4":"هكذا يقود ملك أشور أسرى مصر وكوش صغارا وكبارا، عراة حفاة بأقفية مكشوفة، عارا لمصر.","20:5":"عندئذ يفزع الفلسطينيون الذين اعتمدوا على كوش رجائهم ومصر فخرهم.","20:6":"ويقولون في ذلك اليوم: «انظروا إلى ما آل إليه من كان رجاؤنا، وإلى من لذنا به لينقذنا من ملك أشور، فكيف ننجو نحن؟».","21:1":"نبوءة بشأن بابل: كما تعبر الزوابع في النقب، هكذا يقبل الغازي من الصحراء، من أرض الرعب.","21:2":"لقد أعلنت لي رؤيا رهيبة: رأيت الناهب ينهب، والمدمر يدمر. فاصعدي يا عيلام، وحاصري يا مادي، لأنني سأسكت كل الأنين الذي سببته.","21:3":"لذلك امتلأت حقواى ألما، وانتابني مخاض كمخاض الوالدة. فقدت الوعي من جراء ما سمعت، وذهلت مما رأيت","21:4":"تحير قلبي، وأرعبني الفزع، فتحول ليلي الذي كنت أتوق إليه إلى رعدة.","21:5":"أعدوا مائدة وفرشوا السجاجيد، أكلوا وشربوا، فانهضوا يا أمراء، وادهنوا بالزيت تروسكم.","21:6":"لأنه هكذا قال الرب لي: اذهب وأقم رقيبا ليعلن ما يراه.","21:7":"وعندما يشاهد راكبين فرسانا أزواجا أزواجا، أو راكبين على حمير، وراكبين على جمال، فليصغ إصغاء شديدا.","21:8":"ثم هتف الرقيب: ها أنا أقف على برج المراقبة يوما بعد يوم أيها الرب، وأقوم على المحرس طوال الليل.","21:9":"فها ركب قادم، فرسان أزواج أزواج. فأجاب: سقطت سقطت بابل وتحطمت سائر أصنامها على الأرض.","21:10":"آه يا شعبي المطحون والمشتت، لقد أنبأتكم بكل ما سمعته من الرب القدير إله إسرائيل.","21:11":"نبوءة بشأن أدوم: هتف صارخ من سعير: «يا رقيب، ماذا بقي من الليل؟ أما آن له أن ينتهي؟»","21:12":"فأجاب الرقيب: «أشرق الصبح ولكن الليل أقبل معه، فإن رغبتم في السؤال فاسألوا، ثم تعالوا وارجعوا إلى الله».","21:13":"نبوءة بشأن شبه الجزيرة العربية: ستبيتين في صحاري بلاد العرب يا قوافل الددانيين،","21:14":"فاحملوا يا أهل تيماء الماء للعطشان، واستقبلوا الهاربين بالخبز،","21:15":"لأنهم قد فروا من السيف المسلول، والقوس المتوتر، ومن وطيس المعركة.","21:16":"لأنه هذا ما قاله لي الرب: في غضون سنة مماثلة لسنة الأجير يفنى كل مجد قيدار،","21:17":"وتكون بقية الرماة، الأبطال من أبناء قيدار، قلة. لأن الرب إله إسرائيل قد تكلم.","22:1":"نبوءة بشأن أورشليم: ماذا حدث حتى إنكم جميعا صعدتم إلى سطوح المنازل؟","22:2":"أيتها المدينة الممتلئة جلبة، العجاجة المرحة، إن قتلاك ليسوا قتلى سيف أو صرعى حرب.","22:3":"قد فر رؤساؤك جميعا. أسروا من غير مقاومة. وسبي كل من عثر عليه، مع أنهم هربوا بعيدا.","22:4":"لذلك أقول: «ابتعدوا عني لأبكي بمرارة، لا تتكبدوا جهدا في تعزيتي من أجل دمار ابنة شعبي،","22:5":"لأن للسيد الرب القدير في أورشليم يوما يبث فيه الرعب، والذلة، والفوضى. فيه ينقب أهلها الأسوار ويستجيرون بالجبال.","22:6":"إذ أن عيلام قد حملت السهام واجتمعت بمركبات وفرسان، وقير جردت الدروع،","22:7":"فاكتظت خير أوديتك بالمركبات، واصطف الفرسان عند البوابات،","22:8":"لأن الرب هتك ستر يهوذا. في ذلك اليوم تبحثون عن سلاح بيت الغابة،","22:9":"وتجدون أن صدوع مدينة داود قد كثرت، وتجمعون المياه من البحيرة السفلى،","22:10":"ثم تعدون بيوت أورشليم وتهدمون بعضا منها لتحصنوا السور.","22:11":"وتبنون خزانا بين السورين لتخزين ماء البركة القديمة من غير أن تأبهوا لبانيها، أو تكترثوا لمن صممها منذ زمن بعيد.","22:12":"في ذلك اليوم يدعوكم السيد الرب القدير للبكاء والنوح وحلق الشعر والتنطق بالمسوح.","22:13":"ولكنكم انهمكتم بالفرح والسرور وذبح الثيران وتضحية الغنم وأكل اللحم وشرب الخمر قائلين: «لنأكل ونشرب لأننا غدا نموت».","22:14":"فقال لي القدير: «لن تغفر لكم آثامكم حتى تموتوا».","22:15":"هكذا قال الرب القدير: «توجه إلى شبنا رئيس ديوان القصر وقل له:","22:16":"«مالك هنا، ومن لك حتى نقرت لنفسك ضريحا، أيها الناقر له قبرا في الأعالي، والناحت لنفسه مسكنا في الصخر؟","22:17":"ها الرب مزمع أن يطرحك بعنف أيها الجبار ويمسكك بقوة،","22:18":"ويلوح بك تلويحا، ويقذفك ككرة في أرض واسعة، فتموت هناك، وهناك أيضا تطرح مركبات مجدك يا عار بيت سيدك.","22:19":"وأطردك من منصبك فتعزل من مقامك.","22:20":"في ذلك اليوم أدعو عبدي ألياقيم بن حلقيا،","22:21":"وأخلع عليه حلتك، وأشده بمنطقتك، وأعهد بسلطانك إلى يده، فيصبح أبا لكل سكان أورشليم ولبيت يهوذا،","22:22":"وأعطيه السلطة على جميع شعبي، فما يأمر به يطاع.","22:23":"وأرسخه كوتد في موضع أمين، فيصبح عرش مجد لبيت أبيه.","22:24":"ويضعون عليه كل مجد بيت أبيه بفروعه وأصوله، كل آنية صغيرة من آنية الطسوس إلى آنية القناني.","22:25":"ولكن الرب القدير يقول، في ذلك اليوم يقتلع الوتد المترسخ بإحكام من موضعه الأمين ويستأصل ويطرح على الأرض ويبيد معه كل الذين اتكلوا عليه».","23:1":"نبوءة بشأن صور: ولولي ياسفن ترشيش، لأن صور قد هدمت، فلم يبق بيت ولا مرفأ. تماما كما بلغكم النبأ وأنتم في أرض قبرص.","23:2":"اصمتوا ياأهل الساحل، ياتجار صيدون، عابري البحر الذين ملأتموها،","23:3":"فقد قدمت فوق المياه الكثيرة سفن محملة بقمح شيحور وحصاد النيل، فصارت هي متجرة الأمم.","23:4":"فاخجلي ياصيدا لأن البحر وحصنه قد تكلما قائلين: لم أتمخض ولم ألد، لم أنشيء شبابا ولا ربيت عذارى.","23:5":"عندما يذيع النبأ في مصر، يتوجعون لأخبار صور.","23:6":"اعبروا إلى ترشيش، انتحبوا ياأهل الساحل.","23:7":"أهذه هي مدينتكم المبتهجة التي نشأت منذ القدم، والتي تنقلها قدماها للتغرب في أرض بعيدة؟","23:8":"من قضى بهذا على صور واهبة التيجان، التي تجارها أمراء، ومتكسبوها شرفاء الأرض؟","23:9":"إن الرب القدير هو الذي قضى بذلك، ليحط من كبرياء كل مجد، وليذل كل شرفاء الأرض.","23:10":"امخري عباب البحر ياابنة ترشيش كما يخترق النيل أرض مصر إذ زال مرفأك من الوجود.","23:11":"بسط الرب يده على البحر، وزعزع ممالك، أصدر أمره على كنعان كي تدمر حصونها،","23:12":"وقال: «لن تعودي تعربدين أيتها العذراء التي فقدت شرفها، يا ابنة صيدون هبي واعبري إلى قبرص، ولكنك لن تجدي هناك راحة».","23:13":"تأملي في أرض الكلدانيين وانظري إلى شعبها، فهم وليس الأشوريون الذين سيجعلون صور مرتعا للوحوش، وسينصبون حولها أبراجهم، ويمسحون قصورها عن وجه الأرض، ويحولونها إلى خراب.","23:14":"انتحبي يا سفن ترشيش لأن حصونك قد تهدمت.","23:15":"وفي ذلك اليوم تظل صور منسية طوال سبعين سنة، كحقبة حياة ملك واحد، وفي نهاية السبعين سنة يصيب صور مثل ما جاء في أغنية العاهرة:","23:16":"«خذي عودا وطوفي في المدينة أيتها العاهرة المنسية. أتقني العزف على العود وأكثري الغناء لعلك تذكرين».","23:17":"وفى نهاية السبعين سنة يفتقد الرب صور، فترجع إلى عهدها، وتزني مع كل ممالك الأرض.","23:18":"أما تجارتها وأجرتها فتصبح قدسا للرب. لا تخزن ولا تدخر لأن تجارتها توفر غذاء وفيرا، وثيابا فاخرة للساكنين أمام الرب.","24:1":"ها إن الرب يخرب أرض يهوذا ويقفرها ويقلب وجهها ويشتت سكانها.","24:2":"وما يقع على الشعب يقع على الكاهن أيضا، والسيد كالعبد والسيدة كأمتها والبائع كالمشتري، والمقترض كالمقرض، والدائن كالمديون.","24:3":"ويحل الخراب بالأرض وتنهب نهبا، لأن الرب قد تكلم بهذا القضاء.","24:4":"وتنوح الأرض وتذوي، وتضنى المسكونة وتذبل، ويحزن معها عظماؤها.","24:5":"تدنست الأرض تحت سكانها، لأنهم تعدوا على الشريعة، ونقضوا الفرائض ونكثوا العهد الأبدي،","24:6":"لذلك التهمت اللعنة الأرض، وعوقب أهلها بإثمهم، فاحترق سكان الأرض ولم يبق منهم سوى قلة.","24:7":"قد انتحبت الخمرة، وذبلت الكرمة، وأن جميع ذوي القلوب الطربة.","24:8":"خرس طرب الدفوف، كف ضجيج المبتهجين، وصمت مرح العود.","24:9":"لا يعودون يشربون الخمر مع الغناء، ويكون المسكر مرا لشاربيه.","24:10":"قد تدمرت مدينة الفوضى، وأغلق كل بيت، فلا يقدر أحد على الدخول.","24:11":"ترتفع صرخة في الأزقة طلبا للخمرة المفقودة. زال كل فرح، وتلاشى السرور من الأرض","24:12":"بقي الخراب في المدينة، وتحطمت البوابات فأصبحت ردما.","24:13":"وهكذا يحدث في وسط الأرض بين الأمم، فيكونون كشجرة زيتون نفضت، أو كاللقاط المتبقي بعد قطاف العنب.","24:14":"هؤلاء الباقون يرفعون أصواتهم ويهتفون بفرح، ويشدون من الغرب بجلال الرب.","24:15":"لذلك مجدوا الرب في المشرق، مجدوا اسم الرب إله إسرائيل في جزائر البحر.","24:16":"من أقاصي المعمورة سمعنا تسابيح مجد قائلة: «المجد للبار». ولكني قلت: أنا هالك! أنا هالك ويل لي لأن الخونة يمارسون الخيانة. الخونة يمارسون الخيانة.","24:17":"فالرعب والحفرة والفخ عليكم ياساكني الأرض.","24:18":"وكل من يهرب من صوت الرعب يقع في الحفرة، ومن يتسلق الحفرة ناجيا يعلق بالفخ، لأن الهلاك يهبط عليكم من السماء، وتتزلزل الأرض تحت أقدامكم.","24:19":"فالأرض متصدعة، والمسكونة متشققة ومتزلزلة.","24:20":"ترنحت الأرض كالسكارى، وتمايلت كخيمة الناطور وناءت تحت ثقل إثمها فتهاوت ولم تنهض.","24:21":"في ذلك اليوم يعاقب الرب الملائكة الساقطين في السماوات، والملوك المتغطرسين على الأرض،","24:22":"فيجمعون معا كما يجمع الأسارى فى الجب، ويزجون في سجن مغلق، ويتم عقابهم بعد أيام عديدة.","24:23":"ثم يخجل القمر وتخزى الشمس، لأن الرب القدير يملك على جبل صهيون وفي أورشليم، ويتمجد أمام شيوخ شعبه.","25:1":"يارب أنت إلهي، أعظمك وأحمد اسمك لأنك صنعت عجائب كنت قد قضيت بها منذ القدم، وهي حق وصدق.","25:2":"حولت المدينة إلى كومة ركام، والقرية الحصينة إلى أطلال، ولن يكون قصر الغرباء مدينة بعد، ولن يبنى أبدا.","25:3":"لذلك يمجدك شعب قوي وتخشاك مدن آهلة بأمم فظة","25:4":"لأنك كنت حصنا للبائس، وملاذا منيعا للمسكين في ضيقه، وملجأ له من العاصفة، وظلا تقيه وهج الحر، لأن نفخة العتاة كسيل يرتطم بحائط.","25:5":"تخرس ضجيج الغرباء كما تطفيء الحر في أرض جافة وتسكت غناء العتاة كما تبرد الحر بظل سحابة.","25:6":"في هذا الجبل، في أورشليم، يقيم الرب القدير مأدبة مسمنات لجميع الشعوب، مأدبة خمر صافية معتقة، مأدبة لحوم وأمخاخ.","25:7":"ويمزق في هذا الجبل النقاب المسدول على كل الشعوب، والحجاب الذي يغطي جميع الأمم،","25:8":"ويبتلع الموت إلى الأبد، ويمسح السيد الرب الدموع المنهمرة على الوجوه، ويزيل عار شعبه من كل الأرض. هذا ما تكلم به الرب.","25:9":"ويقولون في ذلك اليوم: «ها هو إلهنا الذي انتظرناه فخلصنا. هذا هو الرب الذي انتظرناه نبتهج ونفرح بخلاصه».","25:10":"لأن يد الرب تستقر على هذا الجبل ويوطأ موآب في مكانه كما يوطأ التبن في الطين.","25:11":"ويبسط يديه في وسط موآب كما يبسط السابح يديه ليسبح، ويخفض الرب من كبريائه ومن مكايد يديه،","25:12":"ويهدم أسواره الحصينة الشامخة، ويخفضها حتى تتساوى مع التراب.","26:1":"في ذلك اليوم يتردد هذا النشيد في أرض يهوذا: «لنا مدينة منيعة، يجعل الرب الخلاص أسوارا ومترسة.","26:2":"افتحوا الأبواب لتدخل الأمة البارة التي حافظت على الأمانة.","26:3":"أنت تحفظ ذا الرأي الثابت سالما لأنه عليك توكل.","26:4":"اتكلوا على الرب إلى الأبد، لأن الرب الله هو صخر الدهور.","26:5":"لقد أذل الساكنين في العلاء، وخفض المدينة المتشامخة. ساواها بالأرض وطرحها إلى التراب،","26:6":"فداستها أقدام البائس والفقير.","26:7":"سبيل الصديق استقامة، لأنك تجعل طريق البار ممهدة.","26:8":"انتظرناك يارب بشوق في طريق أحكامك. تتوق النفس إلى اسمك وتشتهي ذكرك.","26:9":"تتوق إليك نفسي في الليل، وفي الصباح تشتاق إليك روحي. عندما تسود أحكامك في الأرض يتعلم أهلها العدل.","26:10":"إن أبديت رحمتك للمنافق فإنه لا يتعلم العدل، بل يظل يرتكب الشر حتى في أرض الاستقامة، ولا يعبأ بجلال الرب.","26:11":"يارب إن يدك مرتفعة وهم لا يرونها، فدعهم يشاهدون غيرتك على شعبك، ويخزون. لتلتهمهم النار التي ادخرتها لأعدائك.","26:12":"يارب أنت تجعل سلاما لنا لأنك صنعت لنا كل أعمالنا.","26:13":"أيها الرب إلهنا، قد ساد علينا أسياد سواك، ولكننا لا نعترف إلا باسمك وحده.","26:14":"هم أموات لا يحيون وأشباح لا تقوم. عاقبتهم وأهلكتهم وأبدت ذكرهم.","26:15":"قد زدت الأمة يارب ونميتها، فتمجدت، ووسعت تخومها في الأرض.","26:16":"يارب قد طلبوك في المحنة، وسكبوا دعاءهم عند تأديبك لهم،","26:17":"وكنا في حضرتك يارب كالحبلى المشرفة على الولادة، التي تتلوى وتصرخ في مخاضها.","26:18":"حبلنا وتلوينا ولكننا كنا كمن يتمخض عن ريح. لم نخلص الأرض ولم يولد من يقيم فيها فتصير آهلة عامرة.","26:19":"ولكن أمواتك يحيون، وتقوم أجسادهم فيا سكان التراب استيقظوا واشدوا بفرح لأن طلك هو ندى متلأليء، جعلته يهطل على أرض الأشباح.","26:20":"تعالوا يا شعبي وادخلوا إلى مخادعكم، وأوصدوا أبوابكم خلفكم. تواروا قليلا حتى يعبر السخط.","26:21":"وانظروا فإن الرب خارج من مكانه ليعاقب سكان الأرض على آثامهم، فتكشف الأرض عما سفك عليها من دماء ولا تغطي قتلاها فيما بعد.","27:1":"في ذلك اليوم يعاقب الرب بسيفه القاسي العظيم المتين لوياثان الحية الهاربة المتلوية، ويقتل التنين الذي في البحر.","27:2":"في ذلك اليوم غنوا لشعبي الكرمة المشتهاة،","27:3":"فأنا الرب راعيها أرويها في كل لحظة، وأحرسها ليل نهار لئلا يتلفها أحد.","27:4":"لست أضمر غيظا، ومن قاومني بالشوك والحسك فإنني أهجم عليهم جميعا وأحرقهم.","27:5":"أو ليستجيروا بحمايتي وليعقدوا معي سلاما؛ أجل! ليعقدوا معي سلاما.","27:6":"ويتأصل يعقوب في الأيام المقبلة ويزهر إسرائيل، وينبت فروعا تملأ الأرض كلها بالثمار.","27:7":"هل ضربه الرب كما ضرب ضاربيه، أم هلك كما هلك قاتلوه؟","27:8":"عاقبته إذ خاصمته ونفيته بنفخة عاصفة في يوم هبوب ريح شرقية.","27:9":"لهذا يكفر عن إثم يعقوب، ويكون هذا هو كل ثمر محو خطيئته، عندما يجعل جميع حجارة المذبح كحجارة الكلس المسحوقة، ولا يبقى تمثال لعشتاروث أو مذبح قائما.","27:10":"لأن المدينة المنيعة تصبح مقفرة، ويصبح المسكن مهجورا متروكا كالقفر. وهناك يرعى العجل ويربض ويقرض أغصانها.","27:11":"ومتى يبست فروعها تتكسر، فتقبل النساء ويستخدمنها وقودا للنار. لأن هذا شعب جاهل، لذلك لا يرحمه صانعه ولا يرفق به خالقه.","27:12":"في ذلك اليوم ينتقيكم الرب من مجرى الفرات إلى وادي النيل، كما ينتقى القمح، ويجمعكم واحدا فواحدا يا بني إسرائيل.","27:13":"في ذلك اليوم ينفخ في بوق عظيم فيأتي التائهون في أرض أشور، والمنفيون إلى ديار مصر، ليسجدوا للرب في جبل قدسه، في أورشليم.","28:1":"ويل (لمدينة السامرة) تاج فخر سكارى أفرايم، ولزهرة جمالها المجيدة الذابلة التي تتوج رأس وادي خصب المخمورين.","28:2":"لأن للرب متسلطا قويا عاتيا ينقض كعاصفة برد، كنوء مدمر، كزوبعة هائلة من مياه جارفة فيطرحها أرضا بعنف،","28:3":"فتداس السامرة، تاج فخر سكارى أفرايم بالأقدام.","28:4":"وتضحى زهرة جمالها المجيد التي تكلل رأس الوادي الخصيب كباكورة التين قبل موسم الصيف التي يراها الناظر فيقتطفها ويبتلعها.","28:5":"في ذلك اليوم يكون الرب القدير تاج بهاء وإكليل جمال لبقية شعبه","28:6":"ويكون روح عدل لمن يتبوأ كرسي القضاء ومصدر قوة لمن يحاربون رادين الأعداء عن بوابات المدينة.","28:7":"ولكن هؤلاء أيضا أضلتهم الخمر وترنحوا بالسكر، فسلب المسكر عقول أنبيائهم وكهنتهم، فأربكهم ورنحهم، فأخطأوا الرؤيا، وتعثروا في الأحكام.","28:8":"فامتلأت موائدهم كلها بالقيء، ولم يبق مكان لم يتلوث.","28:9":"فتساءلوا: «لمن يلقن إشعياء العلم، ولمن يشرح رسالته؟ هل للمفطومين عن اللبن المبعدين عن الثدي؟","28:10":"لأنه يكرر علينا أوامره كلمة فكلمة، ووصية فوصية؛ شيئا من هنا وشيئا من هناك.","28:11":"سيخاطب الرب هذا الشعب بلسان غريب أعجمي","28:12":"وهو الذي قال لهم: «هذه هي أرض الراحة، فأريحوا المنهك؛ وهنا مكان السكينة. ولكنهم أبوا أن يطيعوه.","28:13":"لذلك سيكرر الرب عليهم أوامره كلمة فكلمة ووصية فوصية؛ شيئا من هنا وشيئا من هناك، ولكنهم (لحمقهم) يتعثرون ويسقطون فيتحطمون ويؤسرون ويستعبدون.","28:14":"لذلك اسمعوا كلمة الرب أيها المستهزئون المتحكمون في شعب أورشليم:","28:15":"لأنكم قلتم: «قد أبرمنا عهدا مع الموت، وعقدنا ميثاقا مع الهاوية، فإن الأشوريين المقتحمين أرضنا لن يسلخونا، لأن السوط الجارف إذا عبر لا يصيبنا لأننا اعتصمنا بالمراوغة ولجأنا إلي النفاق».","28:16":"لهذا يقول الرب: «ها أنا أضع حجر أساس في صهيون، حجر زاوية ثمينا ليكون أساسا راسخا وكل من يؤمن به لا يهرب.","28:17":"وسأجعل العدل خيط قياس والحق مطمارا (لأكشف عن زيف أعمالكم) فيجرف البرد معتصم الكذب وتطفو المياه على المخابيء","28:18":"عندئد يبطل عهدكم مع الموت، ويلغى ميثاقكم مع الهاوية ويدوسكم أعداؤكم عند اقتحامهم بلادكم.","28:19":"ويجتاحونكم مرة تلو مرة، في الليل والنهار وما إن تدركوا مغزى هذا العقاب حتى يطغى عليكم الرعب.","28:20":"لأن السرير أقصر من أن تتمددوا عليه، والغطاء أضيق من أن تلتفوا به».","28:21":"وسيقبل الرب بسخط، كما أقبل في جبل فراصيم وفي وادي جبعون ليجري أفعاله الغريبة ويعاقب أشد عقاب.","28:22":"لذلك لا تتهكموا لئلا يتفاقم عقابكم لأن رب كل الأرض القدير قد أبلغني قضاءه بهلاككم.","28:23":"فاستمعوا إلى صوتي واصغوا إلى قولي وأطيعوا:","28:24":"أيواظب الحارث على حرث أرضه وتتليمها وتمهيدها كل يوم؟","28:25":"أليس إذا سوى أرضها يبذر الشونيز ويذري الكمون وينثر الحنطة في أتلامها والشعير في مواضعه، والقطاني في أطرافها المحروثة؟","28:26":"لأنه قد تلقى المعرفة الصحيحة من إلهه.","28:27":"فيعلم أن الشونيز لا يدرس بالنورج، ولا يطحن الكمون، بل يخبط كلاهما بالقضيب.","28:28":"ويدق الحنطة لأنه لا يمكنه أن يظل يدرسها إلى الأبد، وإن جر عليها بكرة عربته فإن خيله لا تطحنها.","28:29":"إن مصدر هذه المعرفة هو الرب القدير العجيب في مشورته والعظيم في حكمته.","29:1":"ويل لأورشليم المدينة التي استقر فيها داود. ها السنوات تتعاقب وأنتم مازلتم تحتفلون بالأعياد.","29:2":"ولكن سأحاصر أورشليم، فيملأها الأنين والنوح، فتكون في نظري كمذبح ملطخ بالدم.","29:3":"سأنزل عليك وأحيط بك وأحاصرك بأبراج، وأقيم عليك المتاريس.","29:4":"عندئذ تنخفضين، وتتكلمين من الأرض، ومن التراب تصدر عنك تمتمة كلام، فيكون صوتك كصوت خيال صادر من الأرض، ويرتفع كلامك هامسا من التراب.","29:5":"ولكن سرعان ما يصير جمهور أعدائك كالهباء، وجمهور العتاة كالعصافة العابرة. ثم فجأة، وفي لحظة،","29:6":"يفتقدك الرب القدير، فيأتي برعد وزلزال وضجيج عظيم، مع زوبعة وعاصفة ولهيب نار آكلة،","29:7":"وتصبح كل الشعوب التي تحارب أورشليم، وتحاصر حصونها كالحلم أو كرؤيا الليل.","29:8":"وكما يحلم الجائع أنه يأكل ثم يستيقظ من غير أن يشبع جوعه، وكما يحلم الظاميء أنه يشرب ثم يفيق من غير أن يرتوي عطشه، هكذا يكون جمهور الأمم كلها المتألبين على جبل صهيون.","29:9":"ابهتوا وتعجبوا. تعاموا واعموا. اسكروا ولكن من غير خمر. ترنحوا ولكن من غير مسكر،","29:10":"لأن الرب قد سكب عليكم روح سبات عميق، فأغلق عيون أنبيائكم وغطى رؤوس رائييكم.","29:11":"وصارت لكم هذه الرؤيا جميعها ككلمات كتاب مختوم، حين يناولونه لمن يتقن القراءة قائلين: اقرأ هذا، يجيب: لا أستطيع لأنه مختوم.","29:12":"وعندما يناولونه لمن يجهل القراءة قائلين: اقرأ هذا، يجيب: لا أستطيع القراءة.","29:13":"لذلك يقول الرب: لأن هذا الشعب يقترب مني بفمه ويكرمني بشفتيه، بينما قلبه بعيد عنى. وما مخافتهم مني سوى تقليد تلقنوه من الناس.","29:14":"لذلك سأنتقم من هؤلاء المنافقين، فتبيد حكمة حكمائه وتتلاشى فطنة فهمائه.","29:15":"ويل للذين يوغلون في الأعماق ليكتموا عن الرب مشورتهم، فيقومون بأعمالهم في الظلام قائلين: من يرانا؟ ومن يعرفنا.","29:16":"يالتحريفكم! أيحسب الخزاف كالخزف، فيقول الشيء المصنوع لصانعه: أنت لم تصنعني؟ أم أن المجبول يقول لجابله: أنت مجرد من الفهم؟","29:17":"ألا تتحول لبنان في لحظات إلى حقل خصيب، والحقل الخصب إلى غابة؟","29:18":"في ذلك اليوم يسمع الأصم أقوال الكتاب، وتبصر عيون المكفوفين من وراء الظلمة والكآبة.","29:19":"أما الوداعاء فيتجدد فرحهم بالرب، ويبتهج البائسون بقدوس إسرائيل،","29:20":"لأن العاتي قد انقرض، وباد المستهزيء، واستؤصل جميع الساهرين لارتكاب الإثم،","29:21":"الذين بكلمة جعلوا الإنسان يخطيء، ونصبوا فخا لمن يفحمهم في ساحة القضاء، وصدوا البار بادعاءاتهم الجوفاء.","29:22":"لذلك هكذا يقول الرب مفتدي إبراهيم لبيت يعقوب: لن يخجل يعقوب في ما بعد، ولن يعلو وجهه الشحوب،","29:23":"لأنهم عندما يرون أبناءهم يتزايدون بفضلي، فإنهم يقدسون اسمي، ويقدسون قدوس يعقوب، ويرهبون إله إسرائيل،","29:24":"ويكتسب الضالون فهما ويتقبل المتذمرون التعليم.","30:1":"يقول الرب: «ويل للبنين المتمردين الذين ينصاعون لمشورة لم تصدر عني، ويبرمون عهدا ليس من روحي، ليضيفوا خطيئة إلى خطيئة.","30:2":"الذين يتأهبون للانحدار إلى مصر من غير أن يلجأوا إلى مشورتي، ليلوذوا بحمى فرعون ويعتصموا بظل مصر،","30:3":"لذلك يصير لكم حصن فرعون عارا، والاحتماء بظل مصر خزيا،","30:4":"ومع أن سلطانه امتد إلى صوعن وحانيس حتى أقام فيها لنفسه ولاة وممثلين","30:5":"فإنهم يلحقون بكم العار ويجلبون عليكم الخزي لأنهم شعب لا جدوى منه».","30:6":"نبؤة بشأن وحوش النقب: عبر أرض العناء والأهوال حيث تعيش الأسود والأفاعي، تحمل قوافلهم أموالهم على ظهور حميرهم، وكنوزهم على أسنمة جمالهم إلى مصر التي لا رجاء فيها.","30:7":"لأن عون مصر باطل لا طائل منه، لذلك دعوتها «التنين العاصي»","30:8":"والآن، امض ودون ذلك على لوح، وسجله في كتاب ليكون شاهدا أبديا في الأيام الآتية.","30:9":"لأن إسرائيل شعب متمرد، أبناء كذبة، يأبون الاستماع إلى شريعة الرب،","30:10":"ويقولون للأنبياء: «لا تتنبأوا لنا بما هو حق، بل كلمونا بالكلام المداهن وتنبأوا بالمخادعات.","30:11":"اعدلوا عن الطريق، حيدوا عن السبيل، وكفوا عن مجابهتنا بكلام قدوس إسرائيل».","30:12":"لذلك هكذا يقول قدوس إسرائيل: «لأنكم ازدريتم بهذه الكلمة واتكلتم على الجور والانحراف واعتمدتم عليهما،","30:13":"لذلك يصبح هذا الذنب لكم كصدع ناتيء في سور عال مشرف على الانهيار الذي يحدث بغتة وفى لحظة","30:14":"ويكون انهياره ككسر إناء خزاف تم سحقه بقسوة، فلم تبق منه شقفة لالتقاط نار من الموقد أو لغرف ماء من الجب.","30:15":"لأنه هكذا قال السيد الرب قدوس إسرائيل: إن خلاصكم مرهون بالتوبة والركون إلي، وقوتكم في الطمأنينة والثقة، لكنكم أبيتم ذلك،","30:16":"وقلتم: لا بل نهرب على الخيل، أنتم حقا تهربون. وقلتم: سنركب على متون جياد سريعة، لهذا فإن مطارديكم يسرعون في تعقبكم.","30:17":"يهرب ألف منكم أمام زجرة واحد، ويتشتتون جميعا أمام زجرة خمسة، حتى تتركوا كسارية على رأس جبل أو كراية على قمة تل».","30:18":"ومع ذلك فإن الرب ينتطر حتى يبدي نحوكم عطفه، لهذا يقوم ليرحمكم، لأن الرب هو إله عدل، فطوبى لجميع الذين ينتظرونه.","30:19":"ياشعب صهيون المقيم في أورشليم، لن تبكي في ما بعد، لأن الرب يرحمك عند ارتفاع صوت بكائك، وحالما يسمع يستجيب لك.","30:20":"ومع أنه يعطيك خبزا في المحنة، وماء في الضنك فإن معلمك لن يحجب نفسه عنك من بعد، بل ترى عيناك معلمك.","30:21":"وتسمع أذناك كلمة صادرة من خلفك قائلة:","30:22":"«هذه هي الطريق لا تحيدوا عنها يمينا أو يسارا اسلكوا فيها» وتدنسون كل أصنامكم الفضية والذهبية، وتلقون بها بعيدا كخرقة ملوثة بدم حائض وتقولون لها: «اذهبي بلا رجعة».","30:23":"ويسكب الرب مطره على بذورك التي تزرعها في الأرض، فيكون الطعام الذي تغله من الأرض سمينا دسما، فترعى مواشيك في ذلك اليوم في مراع فسيحة،","30:24":"وتأكل ثيرانك وحميرك التي تحرث الأرض علفا مملحا مذرى بالرفش والمذراة.","30:25":"وفي يوم مجزرة أعدائكم، حينما تنهار الأبراج، تتدفق شلالات مياه وجداول من كل جبل وتل،","30:26":"ويصبح نور القمر كنور الشمس، ويتضاعف نور الشمس سبع مرات كنور سبعة أيام، في يوم يجبر الرب فيه كسر شعبه ويشفي رضوض ضرباته.","30:27":"انظروا ها هو الرب مقبل من بعيد بغضب متوهج ودخان متكاثف متصاعد. شفتاه تفيضان سخطا، ولسانه كنار آكلة،","30:28":"ونفخته كسيل جارف يبلغ إلى العنق، ليغربل الأمم بغربال الهلاك، وليضع لجاما في فكوك الشعوب إضلالا لهم.","30:29":"أما أنتم فتشدون كما في ليلة الاحتفال بعيد مقدس، وتبتهج قلوبكم كقلب من يسير على ألحان ناي، آتيا إلى جبل الرب وإلى صخر إسرائيل.","30:30":"ويسمع الرب جلال صوته ويجعل الناس يعاينون امتداد ذراعه على الأرض بلهيب غضب ثائر ونار آكلة، وانفجار أمطار وعواصف وبرد.","30:31":"فيرتاع أشور من زئير صوته، ويضربه بقضيبه.","30:32":"ويوقع الرب كل ضربة عليه بقضيب عقابه على أنغام الدفوف والعيدان، ويحارب أشور بحروب ثائرة.","30:33":"لأن محرقة الموت جاهزة منذ زمن بعيد وحفرتها واسعة، تكومت فيها الأخشاب ليلقى فيها مولك إله الأشوريين، فتضرمها نفخة الرب كسيل من كبريت.","31:1":"ويل للمنحدرين إلى مصر طلبا للعون، المتوكلين على الخيل، الواثقين بكثرة المركبات وببأس الفرسان، من غير أن يلتفتوا إلى قدوس إسرائيل، أو يطلبوا مشورة الرب.","31:2":"ومع ذلك فهو حكيم يجلب الشر، ولا ينقض كلامه بل سيهب ليعاقب بيت الأشرار وناصري فعلة الإثم.","31:3":"ليس المصريون آلهة بل بشرا، وخيولهم مجرد أجساد وليست أرواحا، وعندما يمد الرب يده، يتعثر المعين ويسقط المستعين، ويهلكان كلاهما معا.","31:4":"لأنه هكذا قال الرب لي: «كما يزمجر الأسد أو الشبل على فريسته، من غير أن يخشى من صرخات جماعة الرعاة المتألبين عليه، أو يفزع من جلبتهم، هكذا يقبل الرب القدير ليحارب عن جبل صهيون.","31:5":"ويرف الرب القدير على أورشليم لحمايتها كالطيور المحومة فوق أعشاشها، فيحمي وينقذ ويعفو ويخلص.","31:6":"ارجعوا أيها الإسرائيليون إلى من تمردتم عليه أشد التمرد،","31:7":"لأنه في ذلك اليوم ينبذ كل واحد أصنامه الفضية وأوثانه الذهبية التي صنعها بيده الخاطئة.","31:8":"ويصرع الأشوريون ويلتهمون، ولكن ليس بسيف بشر، ويفرون من أمام السيف، ويساق فتيانهم إلى الأعمال الشاقة،","31:9":"وتفنى صخورهم من الفزع، ويولي قادتهم الأدبار عندما يرون علم إسرائيل». هذا ما يقوله الرب الذي ناره في صهيون، وتنوره في أورشليم.","32:1":"انظروا ها إن ملكا يملك بالبر، ورؤساء يحكمون بالعدل.","32:2":"ويصبح كل إنسان كملاذ من الريح، وكملجاء من العاصفة، أو كجداول ميا ه في صحراء، أو كظل صخرة عظيمة في أرض جدباء.","32:3":"عندئذ تنفتح عيون الناظرين، وتصغي آذان السامعين (لاحتياجات شعبهم)","32:4":"فتفهم وتعلم العقول المتهورة، تنطق بطلاقة الألسنة الثقيلة.","32:5":"ولا يدعى اللئيم بعد كريما، ولا يقال للماكر شريف،","32:6":"لأن اللئيم ينطق باللؤم، وقلبه يتآمر بالإثم ليرتكب شرا وليفتري على الرب، تاركا المتضور جوعا من غير شبع، وحارما الظاميء من الشرب.","32:7":"إن أساليب الماكر شريرة، ومؤامراته خبيثة ليهلك البائسين بالأكاذيب، حتى لو كان المسكين ينطق بالحق.","32:8":"أما الكريم فبالمآثر يفتكر وبالمكارم يشتهر.","32:9":"أيتها النساء المترفات المتكاسلات، انهضن واستمعن إلى صوتي. أيتها البنات المطمئنات اصغين إلى أقوالي.","32:10":"ما تكاد تنقضي أيام على سنة حتى تعتريكن رعدة أيتها الآمنات، لأن القطاف قد تلف، وموعد جني الأثمار قد أخلف.","32:11":"ارتعدن أيتها النساء المطمئنات وارتجفن أيتها الفتيات الآمنات. تجردن من ثيابكن وتعرين ومنطقن أحقاءكن بالمسوح.","32:12":"اضربن على صدوركن حسرة على المروج المبهجة والكروم المثمرة.","32:13":"لأن أرض شعبي تنبت الشوك والحسك، فتنمو حتى في كل بيوت الفرح في المدينة المبتهجة.","32:14":"لأن القصر يصبح مهجورا، والمدن العامرة خالية، والتلال والبروج مغاور إلى الأبد، ومراحا للحمير الوحشية ومرعى للقطعان،","32:15":"حتى تنسكب علينا روح من السماء، فتتحول البرية إلى مرج مخصب، ويحسب المرج غابة.","32:16":"عندئذ يسكن العدل في الصحراء، ويقيم البر في المرج المخصب،","32:17":"فيكون ثمر البر سلاما، وفعل البر سكينة وطمأنينة إلى الأبد،","32:18":"فيسكن شعبي في ديار سلام، وفي مساكن آمنة، وفي أماكن راحة مطمئنة،","32:19":"مع أن البرد يسوي الغابة بالأرض، وتدمر المدينة حتى الحضيض.","32:20":"طوباكم أيها الزارعون عند كل ماء، الذين سرحتم قوائم الثور والحمار لترعى طليقة.","33:1":"ويل لك أيها المدمر الذي لم تدمر بعد، والناهب الذي لم ينهبوك، فعندما تكف عن التدمير تدمر، وحين تمتنع عن النهب ينهبونك.","33:2":"يارب ارحمنا. إياك انتظرنا، كن عضدنا في الصباح، وخلاصنا في أثناء المحنة.","33:3":"من صوت ضجيجك هربت الشعوب، ومن ارتفاعك تبددت الأمم،","33:4":"وكما يلتهم الجراد كل ما هو أخضر، هكذا يجمع سلبكم، ويتواثب الناس عليه كتواثب الجنادب.","33:5":"الرب متعظم لأنه ساكن في العلاء. يملأ صهيون عدلا وحقا.","33:6":"هو ضمان أزمانك ووفرة خلاص وحكمة ومعرفة، وتكون مخافة الرب كنزه.","33:7":"ها رسلكم ينوحون خارجا، وممثلو السلام يبكون بمرارة.","33:8":"أقفرت الطرق وخلت من عابري السبيل، نقض العهد وازدرى شهوده، ولم تعد للإنسان قيمة.","33:9":"ناحت الأرض وذوت. خجل لبنان وذبل، وصار شارون كالبرية، ونفض باشان والكرمل عنهما أوراقهما.","33:10":"فقال الرب: «الآن أقوم، الآن أنهض وأتعظم،","33:11":"فكل ما بذلتموه من جهد أيها الأشوريون لا جدوى منه كالحشيش والتبن وصارت أنفاسكم نارا تلتهمكم.","33:12":"وتصبح الشعوب كوقود الكلس، كأشواك مستأصلة محترقة بالنار.","33:13":"اسمعوا أيها البعيدون ما صنعت، وأنتم أيها القريبون اعرفوا قوتي.","33:14":"قد ارتعب الخطاة في صهيون، واستولت الرعدة على الكافرين، فهتفوا: من منا يقدر أن يسكن مع نار آكلة؟ ومن منا يمكنه أن يقيم في وقائد أبدية؟","33:15":"السالك في البر، والناطق بالحق، والنابذ ربح الظلم، والنافض يديه من قبض الرشوة، الصام أذنيه عن الاستماع إلى مؤامرات سفك الدماء، المغمض عينيه عن التأمل في الشر،","33:16":"هو الذي يسكن في العلاء، وملجأه معاقل الصخور، يؤمن له خبزه. ويكفل له ماؤه.","33:17":"ستشهد عيناك الملك في بهائه، وتبصر أرضا تمتد بعيدا.","33:18":"يتذكر قلبك أزمنة الرعب فتتساءل: أين الكاتب الحاسب؟ أين جابي الجزية؟ أين من يحصي الأبراج؟","33:19":"لن ترى الشعب الشرس فيما بعد، الذي يتكلم لغة أجنبية لا تفهمها.","33:20":"التفت إلى صهيون مدينة أعيادنا، فتكتحل عيناك بمرأى أورشليم، المسكن المطمئن والخيمة الثابتة التي لا تقلع أوتادها إلى الأبد ولا تنقطع حبالها","33:21":"هناك يكون الرب لنا بجلاله مكان أنهار وجداول واسعة لا يبحر فيها قارب ذو مجداف، ولا تمخر فيها سفينة عظيمة،","33:22":"لأن الرب هو قاضينا، الرب هو مشترعنا، هو ملكنا وسيخلصنا","33:23":"لقد استرخت حبال أشرعتك، فلا يمكنها شد قاعدة السارية أو نشر الشراع، حينئذ نقسم الغنائم الوفيرة. حتى العرج ينهبون السلب.","33:24":"لن يقول مقيم في صهيون إنه مريض، وينزع الرب إثم الشعب الساكن فيها.","34:1":"اقتربوا أيها الأمم للاستماع، اصغوا أيها الشعوب. لتسمع الأرض وملؤها، المسكونة وكل ما يخرج منها،","34:2":"لأن الرب ساخط على كل الشعوب، وغضبه منصب على جميع أجنادهم. قضى عليهم بالفناء، وأسلمهم إلى الذبح،","34:3":"فتطرح قتلاهم وينتشر نتن جيفهم في الفضاء، وتفيض الجبال بدمائهم،","34:4":"وتنحل كل كواكب السماء، وتطوى السماوات كدرج، وتتساقط كل نجومها كتساقط أوراق الكرمة أو حبات التين المتغضنة.","34:5":"لأن سيفي قد تشرب بالسخط في السماء، وها هو ينزل ليعاقب أدوم، وينتقم من الشعب الذي قضيت عليه بالفناء.","34:6":"للرب سيف مشبع بالدم، مطلي بالشحم، بدم حملان وتيوس، وبشحم كلى كباش، لأن للرب ذبيحة في بصرة، ومذبحة في أدوم.","34:7":"ويسقط معهم البقر الوحشي، والعجول والثيران القوية، فتتشبع أرضهم بالدماء، ويخصب ترابهم بالشحم،","34:8":"لأن للرب يوم انتقام، سنة ثأر لدعوى صهيون،","34:9":"فتنقلب أنهار أدوم إلى زفت، وترابهم إلى كبريت، وتصبح أرضها قارا مشتعلا.","34:10":"فلا تنطفيء ليلا ونهارا، ويحلق دخانها إلى الفضاء مدى الدهر، وتظل خرابا جيلا بعد جيل، فلا يعبر بها أحد إلى الأبد،","34:11":"ولا يرثها سوى الصقور والقنافذ، ويسكن فيها البوم والغراب، ويمد الرب عليها خيط الدمار ومطمار الهلاك،","34:12":"ولا يجد فيها أشرافها أثرا للملك، وينقرض جميع رؤسائها.","34:13":"ينمو الشوك في قصورها، ويزحف العوسج على حصونها، فتصبح مأوى لبنات آوى، ومسكنا للنعام.","34:14":"وتجتمع فيها الوحوش البرية مع الذئاب، ووعل البر يدعو صاحبه، وهناك تستقر وحوش الليل وتجد لنفسها ملاذ راحة.","34:15":"هناك تعيش البوم وتبيض وتفرخ وترعى صغارها تحت أجنحتها، وهناك أيضا تتلاقى الصقور بعضها ببعض.","34:16":"ابحثوا في سفر الرب واقرأوا: فكلمة واحدة لا يمكن أن تسقط، إذ كل أليف سيجتمع بأليفه، لأن فم الرب قد أمر، وروحه يجمعها معا.","34:17":"فهو قد ألقى عليها القرعة، ويده قد وزعتها بقسطاس، فترثها إلى الأبد وتقيم فيها جيلا بعد جيل.","35:1":"ستفرح الصحراء والقفر الأجرد، وتبتهج البرية وتزهر كالورد.","35:2":"تزدهر ازدهارا، وتبتهج أشد بهجة ويضفى عليها مجد لبنان وجلال الكرمل وشارون ويشهدون مجد الرب وبهاء إلهنا.","35:3":"شددوا الأيدي المسترخية، وثبتوا الركب المرتعشة.","35:4":"قولوا لذوي القلوب الخائرة: «تقووا ولا تفزعوا، فها هو إلهكم قادم، مقبل بالنقمة، حامل جزاءه. سيأتي ويخلصكم».","35:5":"عندئذ تبصر عيون المكفوفين وتنفتح أذان الصم،","35:6":"ويطفر الأعرج كالظبي، ويترنم لسان الأبكم فرحا، إذ تنفجر المياه في البرية، وتتدفق الجداول في الصحراء،","35:7":"ويتحول السراب إلى واحة، والأرض الظمأى إلى جداول. وفي الأوجرة حيث كانت تأوي بنات آوى، ينمو العشب والقصب والبردي.","35:8":"وتكون هناك طريق تدعى طريق القداسة، لا يسلك فيها من هو دنس، إنما تكون من نصيب السالكين في تلك الطريق، ولا يضل فيها حتى الجهال.","35:9":"لا يطرقها أسد، ولا يأتيها حيوان مفترس. إنما يسلك فيها المفديون","35:10":"ويرجع إليها مفديو الرب ويقبلون إلى صهيون مترنمين يكلل رؤوسهم فرح أبدي، وتغمرهم الغبطة والسرور، ويهرب الحزن والأنين.","36:1":"وفي السنة الرابعة عشرة من حكم الملك حزقيا، اجتاح سنحاريب ملك أشور جميع مدن يهوذا المحصنة واستولى عليها.","36:2":"ووجه ملك أشور ربشاقى (أي القائد العام) من لخيش إلى أورشليم إلى الملك حزقيا على رأس جيش جرار، فوقف عند قناة البركة العليا على طريق حقل القصار.","36:3":"فخرج للقائه كل من ألياقيم بن حلقيا مدير شؤون القصر، وشبنة الكاتب ويوآخ بن آساف المسجل.","36:4":"فقال لهم ربشاقى القائد العام: «بلغوا حزقيا: هذا ما يقوله الملك العظيم، ملك أشور: على ماذا تتكل؟","36:5":"أظننت أن مجرد الكلام يشكل خطة وقوة لخوض الحرب؟ على من اعتمدت حتى تمردت علي؟","36:6":"أنت تتكل على عكاز هذه القصبة المرضوضة مصر، التي تثقب كف كل من يتوكأ عليها. هكذا يكون فرعون ملك مصر لكل من يتوكأ عليه.","36:7":"وإذا قلتم لي: إنكم توكلتم على الرب إلهكم، أليس هو الذي هدم حزقيا مرتفعاته ومذابحه، وأمر شعب يهوذا وأهل أورشليم أن يسجدوا فقط أمام المذبح القائم في أورشليم؟","36:8":"والآن ليعقد حزقيا رهانا مع سيدي ملك أشور: فأعطيك ألفي فرس إن استطعت أن تجد لها فرسانا يمتطونها!","36:9":"فكيف يمكنك أن تصد قائدا واحدا من أقل قادة سيدي شأنا في حين أنك تعتمد على مصر لإمدادك بالمركبات والفرسان؟","36:10":"ثم هل من غير مشورة الرب زحفت على هذه الديار لأدمرها؟ لقد قال لي الرب: هاجم هذه الديار وخربها».","36:11":"فقال ألياقيم وشبنة ويوآخ لربشاقى: «خاطب عبيدك بالآرامية لأننا نفهمها، ولا تكلمنا باللغة اليهودية على مسمع الشعب المتجمع على السور».","36:12":"فأجاب ربشاقى: «أتظن أن سيدي قد أرسلني إلى سيدك وإليك فقط لكي أتحدث بهذا الكلام؟ أليس هذا الكلام أيضا موجها إلى الرجال المتجمعين على السور، الذين سيأكلون مثلكم برازهم ويشربون بولهم؟»","36:13":"ثم وقف القائد العام ونادى بأعلى صوته قائلا باليهودية: «اسمعوا كلام الملك العظيم ملك أشور:","36:14":"لا يخدعنكم حزقيا لأنه عاجز عن إنقاذكم،","36:15":"ولا يقنعنكم بالاتكال على الرب قائلا: إن الرب حتما ينقذنا، ولن يستولي ملك أشور على هذه المدينة.","36:16":"لا تصغوا إليه، لأنه هكذا يقول ملك أشور: اعقدوا معي صلحا واستسلموا إلي فيأكل عندئذ كل واحد منكم من كرمه ومن تينته، ويشرب من ماء بئره،","36:17":"إلى أن آتي وأنقلكم إلى أرض كأرضكم، أرض حنطة وخمر وخبز وكروم.","36:18":"فلا يغرنكم حزقيا بقوله: إن الرب ينقذنا. هل أنقذ أحد آلهة الأمم أرض شعبه من يد ملك أشور؟","36:19":"أين آلهة حماة وأرفاد؟ أين آلهة سفروايم؟ هل أنقذت السامرة من يدي؟","36:20":"من من كل آلهة هذه البلاد استطاع أن ينقذ أرضه من يدي؟ فكيف ينقذ الرب أورشليم مني؟»","36:21":"فاعتصموا بالصمت ولم يجيبوا بكلمة، لأن الملك أمر بعدم الرد عليه.","36:22":"ورجع ألياقيم بن حلقيا مدير شؤون القصر وشبنة الكاتب ويوآخ بن آساف المسجل إلى حزقيا بثياب ممزقة وأبلغوه كلام القائد الأشوري.","37:1":"وعندما سمع الملك حزقيا ذلك الكلام مزق ثيابه وارتدى مسحا ودخل إلى بيت الرب،","37:2":"ثم أرسل ألياقيم مدير شؤون القصر وشبنة الكاتب ورؤساء الكهنة مرتدين المسوح إلى النبي إشعياء بن آموص،","37:3":"وقالوا له: يقول حزقيا: «هذا اليوم يوم ضيق وإهانة وكرب، صرنا فيه كامرأة تقاسي المخاض وهي عاجزة عن الولادة.","37:4":"لعل الرب إلهك قد سمع وعيد ربشاقى الذي أوفده سيده ملك أشور ليهين الإله الحي، فيعاقبه الرب إلهك على ما صدر منه من تعيير، فصل من أجل البقية الناجية».","37:5":"فعندما مثل رجال حزقيا أمام إشعياء،","37:6":"قال لهم: «بلغوا سيدكم، هذا ما يقوله الرب: لا تجزع مما سمعته من تجديف رجال ملك أشور علي،","37:7":"فها خبر سيء يرد إليه من بلاده يحمله على العودة إلى أرضه، حيث أقضي عليه بحد السيف في عقر داره».","37:8":"وعندما علم ربشاقى أن ملك أشور قد ارتحل عن لخيش وشرع في محاربة لبنة انسحب هو أيضا وانضم إليه هناك.","37:9":"ثم بلغ ملك أشور أن ترهاقة ملك كوش قد خرج لمحاربته، فبعث مرة أخرى رسله إلى حزقيا قائلا لهم:","37:10":"«هذا ما تبلغونه إلى حزقيا ملك يهوذا: لا يخدعنك إلهك الذي تتكل عليه عندما يقول: لن تسقط أورشليم في قبضة ملك أشور.","37:11":"فها أنت قد علمت بما ألحقه ملوك أشور بكل البلدان من تدمير كامل، فهل يمكن أن تنجو أنت؟","37:12":"هل أنقذت آلهة الأمم الأخرى أهل جوزان وحاران ورصف وأبناء عدن في تلسار الذين أفناهم آبائي؟","37:13":"أين ملك حماة، وملك أرفاد، وملك مدينة سفروايم، وهينع وعوا؟»","37:14":"فتناول حزقيا الكتاب من أيدي الرسل وقرأه، ثم توجه إلى بيت الرب وبسطه أمامه،","37:15":"وصلى قائلا:","37:16":"«أيها الرب القدير، إله إسرائيل المتربع فوق الكروبيم، أنت وحدك إله كل ممالك الأرض، وأنت وحدك صانع السماء والأرض.","37:17":"أرهف يارب أذنيك واصغ. افتح يارب عينيك وانظر، واسمع كل تهديدات سنحاريب التي بعث بها ليعير الله الحي.","37:18":"حقا يارب، إن ملوك أشور قد أبادوا الأمم ودمروا ديارهم","37:19":"وطرحوا آلهتهم إلى النار وأبادوها لأنها لم تكن فعلا آلهة بل خشبا وحجارة صنعة أيدي الناس","37:20":"فخلصنا الآن أيها الرب إلهنا، أنقذنا من يده، فتدرك ممالك الأرض بأسرها أنك أنت وحدك الرب الإله».","37:21":"عندئذ بعث إشعياء بن آموص رسالة إلى حزقيا قائلا: «هذا ما يقوله الرب إله إسرائيل الذي تضرعت إليه لينقذك من سنحاريب ملك أشور","37:22":"وهذا هو رد الرب عليه: ها العذراء ابنة صهيون قد احتقرتك واستهزأت بك، وهزت ابنة أورشليم رأسها سخرية منك.","37:23":"من عيرت وجدفت؟ وعلى من رفعت صوتك وشمخت بعينيك زهوا؟ أعلى قدوس إسرائيل؟","37:24":"لقد عيرت السيد على لسان رسلك، وقلت: بكثرة مركباتي قد صعدت إلى أعالي الجبال، وبلغت أقاصي لبنان قاطعا أطول أرزه وخيار سروه واخترقت أبعد ربوعه وأفضل غاباته.","37:25":"قد حفرت آبارا وشربت مياها، وبباطن قدمي جففت جميع خلجان مصر.","37:26":"ألم تسمع؟ منذ زمن طويل قد قدرت ذلك. منذ الأيام القديمة قررته وها أنا الآن أحققه، إذ أقمتك لتدمير مدن محصنة فتحولها إلى روابي خربة.","37:27":"خارت قوى أهلها فأصبحوا مرتاعين خجلين، صاروا كعشب الحقل، كالنبات الأخضر وكحشيش السطوح الذاوي قبل نموه.","37:28":"ولكني مطلع على حركاتك وسكناتك وهيجانك علي.","37:29":"ولأن ثورتك علي وعجرفتك قد بلغتا مسامعي، فإني سأشكمك بخزامتي في أنفك، وأضع لجامي في فمك، وأعيدك في نفس الطريق الذي أقبلت منه.","37:30":"وهذه علامة لك ياحزقيا: في هذه السنة تأكلون مما ينبت من نفسه، وفي السنة التالية تأكلون مما ينبت عنه وأما في السنة الثالثة فتزرعون فيها وتحصدون وتغرسون كروما وتجنون ثمارها.","37:31":"ويعود الناجون الباقون من بيت يهوذا فتتأصل جذورهم في الأرض ويزدهرون ويتكاثرون.","37:32":"لأن من أورشليم تخرج بقية ومن جبل صهيون يأتي الناجون فغيرة الرب القدير تصنع هذا.","37:33":"لذلك، فهذا ما يقوله الرب عن ملك أشور: «لن يدخل هذه المدينة ولن يطلق عليها سهما أو يتقدم نحوها بترس ولا يقيم عليها مقلاعا.","37:34":"بل يرجع في الطريق الذي جاء منه ولن يدخل هذه المدينة، يقول الرب.","37:35":"لأنني أدافع عنها وأنقذها من أجل نفسي وإكراما لداود عبدي».","37:36":"وحدث في تلك الليلة أن ملاك الرب قتل مئة وخمسة وثمانين ألفا من جيش الأشوريين، وما إن طلع الصباح حتى كانت جثث القتلى تملأ المكان","37:37":"فانسحب سنحاريب ملك أشور وارتد إلى بلاده ومكث في نينوى","37:38":"وفيما هو يتعبد في هيكل إلهه نسروخ اغتاله ابناه أدرملك وشرآصر وفرا إلى أرض أراراط، فخلفه ابنه آسرحدون على العرش.","38:1":"ومرض حزقيا في تلك الأيام حتى أوشك على الموت، فجاء إليه النبي إشعياء بن آموص، وقال له: «هذا ما يقوله الرب: نظم شؤون بيتك لأنك لن تبرأ بل حتما تموت».","38:2":"فأدار حزقيا وجهه نحو الحائط وصلى إلى الرب،","38:3":"قائلا: «آه يارب، اذكر كيف سلكت أمامك بالأمانة وبقلب خالص، وصنعت ما يرضيك». وبكى حزقيا بكاء مرا.","38:4":"فأوحى الرب إلى إشعياء قائلا:","38:5":"«اذهب بلغ حزقيا: هذا ما يقوله الرب إله داود أبيك: قد سمعت صلاتك ورأيت دموعك، وها أنا أضيف إلى عمرك خمس عشرة سنة،","38:6":"وأنقذك أنت وهذه المدينة من ملك أشور، وأدافع عنها.","38:7":"وهذه لك علامة من عند الرب أنه لابد أن يحقق ما وعد به:","38:8":"سأرجع ظل الشمس إلى الوراء عشر درجات على مقياس درجات آحاز». وهكذا تراجعت الشمس عشر درجات إلى الوراء بعد أن كانت قد تخطتها.","38:9":"وحين شفي حزقيا كتب هذه القصيدة:","38:10":"قلت ها أنا في ريعان أيامي أنحدر إلى عالم الموتى وتفنى بقية سنوات عمري","38:11":"وقلت لن أرى الرب بعد في أرض الأحياء، ولن أبصر أحدا من الناس في هذه الدنيا الفانية.","38:12":"قد خلع عني مسكني، وانتقل كخيمة الراعي. طوى حياتي كحائك: قطعني من النول. أنت تفنيني ليل نهار.","38:13":"انتظرت بصبر حتى الصباح، ولكنه كأسد هشم كل عظامي. أنت تفنيني ليل نهار .","38:14":"أصيح كسنونة، وأنوح كهديل الحمامة. كلت عيناي من النظر إلى السماء، يارب إني متضايق فكن لي مأمنا.","38:15":"ولكن ماذا أقول؟ فقد خاطبني هو. هو نفسه قضى بذلك علي. طار النوم مني لفرط مرارة روحي.","38:16":"يارب، بمثل هذه يحيا الناس، وفي هذه حياة روحي، فرد لي عافيتي وأحيني.","38:17":"حقا إن ما قاسيته من مرارة كان من أجل خيري، فقد حفظتني بحبك من حفرة الهلاك، وألقيت جميع خطاياي خلف ظهرك.","38:18":"لأنه ليس في وسع الهاوية أن تحمدك، والموت لا يسبحك، ولا يقدر الذين ذهبوا إلى الهاوية أن يرجوا أمانتك.","38:19":"الأحياء وحدهم يسبحونك كما أفعل اليوم، ويحدث الآباء أبناءهم عن أمانتك","38:20":"الرب ينقذني. فلنشد بآلات وترية كل أيام حياتنا في هيكل الرب».","38:21":"ثم قال إشعياء: «ضمدوا القرحة بقرص تين فيبرأ».","38:22":"وكان حزقيا قد سأل: «ما هي العلامة التي تؤكد لي أنني سأذهب للصلاة في بيت الرب؟»","39:1":"في أثناء هذه الفترة، بعث مرودخ بلادان بن بلادان ملك بابل رسائل وهدايا إلى حزقيا بعد أن سمع بمرضه وشفائه منه،","39:2":"فرحب بهم حزقيا ترحيبا حارا، وأطلعهم على ما في خزائنه من فضة وذهب وأطياب وعطور، وعلى مخازن أسلحته. لم يبق شيء في قصره وفي حوزته لم يرهم إياه.","39:3":"فجاء النبي إشعياء إلى الملك حزقيا وسأله: «ماذا قال هؤلاء القوم، ومن أين قدموا إليك؟» فأجابه: «قد أقبلوا إلي من بلد بعيد، من بابل». فعاد يسأله: «ماذا شاهدوا في قصرك؟»","39:4":"فأجاب حزقيا: «شاهدوا كل ما في قصري. لم يبق شيء في مخازني لم أطلعهم عليه».","39:5":"عندئذ قال إشعياء لحزقيا: «اسمع قول الرب القدير:","39:6":"ها أيام تأتي ينقل فيها إلى بابل كل ما في قصرك مما ادخره أسلافك ولا يبقى منها شيء.","39:7":"ويسبى بعض أبنائك الخارجين من صلبك ليكونوا خصيانا في قصر ملك بابل».","39:8":"فقال حزقيا لإشعياء: «صالح هو قول الرب الذي أعلنته». ثم حدث نفسه: «ليكن فقط سلام وأمن في عهدي».","40:1":"يقول إلهكم: «واسوا، واسوا شعبي!","40:2":"طيبوا خاطر أورشليم وبلغوها أن أيام محنتها قد انتهت، وإثمها قد غفر، وتلقت من يد الرب ضعفين عن جميع ما ارتكبته من خطايا».","40:3":"صوت يصرخ ويقول: «أعدوا في البرية طريق الرب، وأقيموا طريقا مستقيما لإلهنا.","40:4":"كل واد يرتفع، وكل تل ينخفض. وتمهد كل أرض معوجة وتعبد كل بقعة وعرة","40:5":"ويتجلى مجد الله، فيشاهده كل ذي جسد، لأن فم الرب قد تكلم».","40:6":"وعندئذ قال صوت: «ناد برسالة». فأجبت: «أية رسالة؟» فقال: «كل ذي جسد عشب، وكل بهائه كزهر الصحراء.","40:7":"يذبل العشب ويذوي الزهر لأن نفخة الرب تهب عليه. حقا إن الشعب عشب.","40:8":"يذبل العشب ويذوي الزهر، أما كلمة إلهنا فتثبت إلى الأبد».","40:9":"اصعدي إلى جبل شامخ ياحاملة البشارة إلى صهيون. ارفعي صوتك بقوة يامبشرة أورشليم. اهتفي ولا تجزعي. قولي لمدن يهوذا: ها إلهكم قادم","40:10":"بقدرته وقوته، وذراعه تحكم له، وها أجرته معه ومكافأته أمامه.","40:11":"يرعى قطيعه كراع، ويجمع الحملان بذراعه، وفي أحضانه يحملها ويقود المرضعات برفق.","40:12":"من كال المياه بكفه وقاس السماوات بالشبر وكال تراب الأرض بالكيل ووزن الجبال بقبان، والتلال بميزان؟","40:13":"من أرشد روح الرب أو كان له مشيرا فعلمه؟","40:14":"هل طلب الرب مشورة من أحد؟ من علمه طريق العدل ولقنه المعرفة وأراه سبيل الفهم؟","40:15":"إن الشعوب كنقطة من دلو، وكغبار الميزان. يرفع الجزائر وكأنها ذرة هباء.","40:16":"لبنان بأسره لا يكفي أن يكون للوقود، وحيوانه لا يكفي لذبيحة محرقة.","40:17":"جميع الأمم لا تحسب لديه شيئا، وهي في عينيه عدم وخواء.","40:18":"بمن تشبهون الله وبمن تقارنونه؟","40:19":"إن كان تمثالا فالتمثال يصوغه الصانع ويغشيه الصائغ بالذهب، ويسبك له سلاسل من الفضة.","40:20":"أما الفقير فإنه يختار قطعة خشب لا تنخر، ويلتمس صانعا حاذقا ينحت له منها صنما ثابتا.","40:21":"ألم تعلموا؟ ألم تسمعوا؟ ألم يبلغكم منذ البدء؟ ألم تفهموا من إرساء أسس الأرض؟","40:22":"إنه هو الجالس على كرة الأرض وسكانها كالجراد. هو الباسط السماوات كسرادق، وينشرها كخيمة للسكنى،","40:23":"يجعل العظماء كالعدم، والحكام كلا شيء.","40:24":"فما كادوا يغرسون ويزرعون ويتأصلون في الأرض حتى نفخ عليهم، فذووا وعصفت بهم زوبعة كالتبن.","40:25":"فبمن إذا تقارنونني فأكون نظيره؟ يقول القدوس.","40:26":"ارفعوا عيونكم إلى العلاء وانظروا. من خلق هذه؟ ومن يبرز كواكبها بمجموعات ويدعوها بأسماء؟ إن واحدة منها لا تفقد لأنه يحافظ عليها بعظمة قدرته، ولأنه شديد القوة.","40:27":"فكيف تجرؤ ياإسرائيل أن تقول إن الرب لا يرى محنتي وطريقي خافية عليه؟","40:28":"ألم تعلموا؟ ألم تسمعوا؟ إن الرب هو إله سرمدي وخالق أقاصي الأرض. لا يهن ولا يخور، وفهمه لا يستقصى.","40:29":"يهب المنهوك قوة ويمنح الضعيف قدرة عظيمة.","40:30":"إن الشبيبة ينالها الإعياء والإرهاق، والفتيان يتعثرون أشد تعثر،","40:31":"أما الراجون الرب فإنهم يجددون قوتهم، ويحلقون بأجنحة النسور. يركضون ولا يعيون. يمشون ولا يتعبون.","41:1":"اصمتي واسمعي لي أيتها الجزائر. لتجدد الأمم قوتها وليتقدموا ليعرضوا حججهم. لنجتمع معا للمثول أمام القضاء.","41:2":"من أقام من المشرق قائدا مظفرا، يواكب النصر كل خطوة من خطواته، وأسلم الأمم إليه وأخضع له الملوك، وجعلهم كالتراب بسيفه، وكالعصافة المذراة بقوسه؟","41:3":"يتعقبهم ويجوز آمنا في دروب لم يطأها بقدميه.","41:4":"من فعل هذا وأنجزه داعيا الأجيال منذ البدء؟ أنا الرب. أنا الأول والآخر.","41:5":"شاهدت الجزائر فعلي وخافت، وارتجفت أقاصي الأرض فتجمعوا معا.","41:6":"شرع كل واحد يشجع جاره قائلا له: تشدد.","41:7":"فشجع الصانع الصائغ، والصاقل بالمطرقة الضارب على السندان قائلا عن الإلحام: هذا عمل جيد. ثم يثبت الصنم بمسامير كي لا يتقلقل.","41:8":"أما أنت ياإسرائيل عبدي. يايعقوب الذي اصطفيته، ياذرية إبراهيم خليلي،","41:9":"يامن أخذتك من أقاصي الأرض، ودعوتك من أبعد أطرافها قائلا لك: أنت عبدي. لقد اصطفيتك ولم أنبذك.","41:10":"لا تخف لأني معك. لا تتلفت حولك جزعا، لأني إلهك، أشددك وأعينك وأعضدك بيمين بري","41:11":"يعتري الخزي والعار كل من يغتاظ منك، ويتلاشى مقاوموك كالعدم.","41:12":"تبحث عن خصومك فلا تجد أحدا منهم، ويصبح محاربوك كلا شيء،","41:13":"لأني أنا الرب إلهك الذي يمسك بيمينك قائلا لك: لا تخف. سأعينك.","41:14":"لا تخف يايعقوب الضعيف كالحشرة، وياإسرائيل العليل كالشرذمة، لأني سأعينك، يقول الرب فاديك قدوس إسرائيل.","41:15":"وها أنا أجعلك نورجا محددا جديدا مسننا، فتدرس الجبال وتجعل التلال كالعصافة،","41:16":"فتذريها، وتحملها الريح بعيدا، وتبددها الزوبعة. أما أنت فتبتهج بالرب وتمجد قدوس إسرائيل.","41:17":"وعندما يلتمس البائسون والمساكين ماء ولا يجدونه، وتتشقق ألسنتهم من العطش، أنا الرب أستجيب لهم، أنا إله إسرائيل لا أتخلى عنهم.","41:18":"فأفجر أنهارا على الهضاب وينابيع في وسط الأودية، وأحول البرية إلى واحة ماء والأرض القاحلة إلى جداول.","41:19":"وأنبت في الصحراء الأرز والسنط والآس وشجر الزيتون، وأنمي في البرية أشجار السرو والسنديان والشربين جميعا،","41:20":"حتى يرى الناس ويدركوا ويتأملوا ويفهموا معا أن يد الرب هي التي صنعت هذا، وأن قدوس إسرائيل هو الذي أبدعه.","41:21":"اعرضوا دعواكم يقول الرب، وقدموا حججكم يقول ملك إسرائيل.","41:22":"أحضروا أصنامكم لينبئونا عما يأتي به المستقبل، وعن الأمور الغابرة.","41:23":"أطلعونا على أحداث الغيب فنعلم أنكم آلهة حقا. إيتوا بمعجزة خيرا كانت أم شرا، تثير دهشتنا أو رعبنا.","41:24":"ولكن أنتم لا شيء، وفعلكم عدم، ولا يصطفيكم سوى الرجس.","41:25":"قد آثرت رجلا من الشمال، ها هو مقبل من مشرق الشمس يدعو باسمي، يطأ الولاة كما يطأ فوق الوحل، ويدوس عليهم كما يدوس الخزاف فوق الطين.","41:26":"من أنبأ بهذا الحدث منذ البدء حتى نعلم به؟ وقبل أوان حدوثه حتى نقول: هو صادق. لم يوجد منبيء أو معلن، ولم يسمع أحد كلمة منكم.","41:27":"أنا أول قائل لصهيون: انظروا هاهم، وأول من أقام في أورشليم بشيرا،","41:28":"ولكن عندما تطلعت إلى الأصنام لم أجد أحدا، ولم يكن هناك بينهم مشير أسأله فيجيب.","41:29":"انظروا، إنهم جميعا وهم باطل، وأعمالهم وأصنامهم المسبوكة ريح وخواء.","42:1":"هوذا عبدي الذي أعضده، مختاري الذي ابتهجت به نفسي. وضعت روحي عليه ليسوس الأمم بالعدل.","42:2":"لا يصيح ولا يصرخ ولا يرفع صوته في الطريق.","42:3":"لا يكسر قصبة مرضوضة، وفتيلة مدخنة لا يطفيء. إنما بأمانة يجري عدلا.","42:4":"لا يكل ولا تثبط له همة حتى يرسخ العدل في الأرض، وتنتظر الجزائر شريعته.","42:5":"هذا ما يقوله الله ، الرب خالق السماوات وباسطها، وناشر الأرض وما يستخر ج منها. الواهب أهلها نسمة، والمنعم بالروح على السائرين عليها:","42:6":"«أنا هو الرب قد دعوتك بالبر. أمسكت بيدك وحافظت عليك وجعلتك عهدا للشعب ونورا للأمم","42:7":"لتفتح عيون العمي، وتطلق سراح المأسورين في السجن، وتحرر الجالسين في ظلمة الحبس.","42:8":"أنا هو الرب وهذا اسمي. لا أعطي مجدي لآخر، ولا حمدي للمنحوتات.","42:9":"ها هي النبوات السالفة تتحقق، وأخرى جديدة أعلن عنها وأنبيء بها قبل أن تحدث».","42:10":"غنوا للرب أغنية جديدة، سبحوه من أقاصي الأرض أيها المسافرون في عباب البحر وكل ما فيه وياسكان الجزائر.","42:11":"لتهتف الصحراء ومدنها، وديار قيدار المأهولة. ليتغن بفرح أهل سالع وليهتفوا من قمم الجبال.","42:12":"وليمجدوا الرب ويذيعوا حمده في الجزائر.","42:13":"يبرز الرب كجبار، يستثير حميته كما يستثيرها المحارب، ويطلق صرخة حرب داوية، يظهر جبروته أمام أعدائه.","42:14":"لكم اعتصمت بالصمت، ولزمت السكينة ولجمت نفسي. أما الآن فأنا أصيح وأزفر كامرأة تقاسي من المخاض.","42:15":"أخرب الجبال والتلال، وأيبس كل عشبها، وأحول الأنهار إلى قفر وأجفف البحيرات،","42:16":"وأقود العمي في سبيل لم يعرفوها من قبل، وأهديهم في مسالك يجهلونها، وأحيل الظلام أمامهم إلى نور، والأماكن الوعرة إلى أرض ممهدة. هذه الأمور أصنعها ولن أتخلى عنهم.","42:17":"أما المتوكلون على الأصنام، القائلون للأوثان: «أنتم آلهتنا» فإنهم يدبرون مجللين بالخزي.","42:18":"اسمعوا أيها الصم، انظروا أيها العمي لتبصروا.","42:19":"من هو أعمى سوى عبدي؟ ومن هو أصم كرسولي الذي أرسلته؟ من هو أعمى مثل من يكن لي الولاء؟ ومن هو كفيف كعبد الرب؟","42:20":"تشهد أمورا كثيرة ولا تلاحظها، وأذناك مفتوحتان ولكن لا تسمع شيئا.","42:21":"قد سر الرب من أجل بره أن يعظم شريعته ويمجدها،","42:22":"لكن شعبه منهوب ومسلوب. قد وقعوا جميعهم في الحفرة واقتنصوا وزج بهم في أقبية السجون. صاروا فريسة وليس من منقذ، وأصبحوا غنيمة وليس من يقول: «ردها».","42:23":"من منكم يسمع هذا وينصت ويصغي للزمن المقبل؟","42:24":"من أسلم يعقوب للنهب، وإسرائيل للسالبين؟ أليس هو الله الذي أخطأنا في حقه؟ لأنهم أبوا أن يسلكوا في طرقه وأن يطيعوا شريعته.","42:25":"لذلك صب عليهم جام غضبه في وطيس الحرب فاكتنفتهم بضرامها ولكنهم لم يفهموا، وأحرقتهم بنيرانها ولم يتعظوا.","43:1":"أما الآن، فهذا ما يقوله الرب خالقك يايعقوب وجابلك ياإسرائيل: «لا تجزع لأني افتديتك، دعوتك باسمك. أنت لي.","43:2":"إذا اجتزت في وسط المياه أكون معك، وإن خضت الأنهار لا تغمرك. إن عبرت في النار لا تلذعك. واللهيب لا يحرقك.","43:3":"لأني أنا هو الرب إلهك، قدوس إسرائيل مخلصك، قد جعلت مصر فدية عنك وكوش وسبا عوضا عنك.","43:4":"إذ أصبحت كريما في عيني، وعزيزا ومحبوبا، فقد بادلت أناسا بك، وقايضت أمما عوضا عن حياتك.","43:5":"لا تجزع لأني معك. سألم شتات ذريتك من المشرق، وأجمعك من المغرب.","43:6":"أقول للشمال: أطلقهم من عقالك، وللجنوب لا تحجزهم. اجمع أبنائي من بعيد وبناتي من أقاصي الأرض،","43:7":"كل من يدعى باسمي ممن خلقته لمجدي وجبلته وصنعته».","43:8":"أخرج الشعب الأعمى وإن كانت له عيون، والأصم وإن كانت له آذان.","43:9":"لتجتمع الأمم بأسرها، ولتحتشد الشعوب. من منهم ينبيء بهذا، ويخبرنا بالأمور السالفة؟ ليقدموا شهودهم إثباتا لصدقهم، أو ليسمعوا ويقولوا: هذا صدق.","43:10":"أنتم شهودي يقول الرب، وعبدي الذي اصطفيته، لتعلموا وتؤمنوا بي، وتدركوا أني أنا أنا هو الله ، لم يوجد إله قبلي ولا يكون إله بعدي.","43:11":"أنا هو الرب، ولا مخلص غيري.","43:12":"إني أنبأت وخلصت وأعلنت أنا، وليس إله غريب بينكم. أنتم شهودي أني أنا الله، يقول الرب.","43:13":"منذ البدء أنا هو الله وليس منقذ من يدي. أفعل ومن يبطل عملي؟","43:14":"هذا ما يقوله الرب فاديكم قدوس إسرائيل، ها أنا من أجلكم أرسلت إلى بابل لأحطم المغاليق، فيصبح البابليون في سفنهم التي يباهون بها مطرودين هاربين.","43:15":"أنا هو الرب قدوسكم خالق إسرائيل وملككم.","43:16":"هذا ما يقوله الرب الصانع في البحر طريقا، وممرا في اللجج العميقة،","43:17":"الذي يستدرج المركبات والخيول والجيش والمقاتلين، فيسقطون صرعى جميعا ولا يقومون، ويخمدون كذبالة وينطفئون.","43:18":"ولكنكم لا تتذكرون الأمور السالفة ولا تعتبرون بالأحداث الغابرة","43:19":"انظروا، ها أنا أنجز أمرا جديدا ينشأ الآن، ألا تعرفونه؟ أشق في البرية طريقا، وفي الصحراء أنهارا،","43:20":"فيكرمني وحش الصحراء: الذئاب والنعام لأني فجرت في القفر ماء، وفي الصحراء أنهارا لأسقي شعبي الذي اخترته،","43:21":"وجبلته لنفسي ليذيع حمدي.","43:22":"ولكنك لم تلتمسني يايعقوب، بل سئمت مني ياإسرائيل.","43:23":"لم تأتني بشاة لذبيحة محرقة، ولم تكرمني بقرابينك، مع أني لم أثقل عليك بتقدمة، ولا أرهقتك بطلب اللبان.","43:24":"لم تشتر لي بخورا ذكى الرائحة، ولم تشبعني بشحم ذبائحك. إنما أعييتني بثقل آثامك وأرهقتني بذنوبك.","43:25":"أنا، أنا هو الماحي ذنوبك من أجل ذاتي، وخطاياك لن أذكرها.","43:26":"هيا إلى المحاكمة، واعرض علي دعواك، لتتبرر","43:27":"قد أخطأ أبوك الأول، ووسطاؤك عصوا علي،","43:28":"لذلك أدنس عظماء مقادسي وأقضي على إسرائيل بالهلاك وأتركه عرضة للخزي والعار.","44:1":"أما الآن فاسمع يايعقوب عبدي، وياإسرائيل الذي اصطفيته.","44:2":"أنا خالقكم من الرحم ومعينكم، لا تخف يا عبدي يعقوب ولا تجزعي يا أورشليم التي اخترتها.","44:3":"لأني سأسكب ماء على الأرض الظمأى، وأجري السيول على التربة اليابسة، وأفيض بروحي على ذريتك، وبركاتي على نسلك.","44:4":"فينبتون بين العشب مزهرين كالصفصاف عند مجاري المياه.","44:5":"ويقولون بملء أفواههم: «أنا عبد الرب. أنا ابن يعقوب». ويكتب على يده اسم الله، وباسم إسرائيل يلقب.","44:6":"هذا ما يقوله الرب القدير ملك إسرائيل وفاديه: «أنا هو الأول والآخر، ولا إله غيري.","44:7":"من مثلي؟ فليخبر بذلك، ويعلنه ويعرض أمامي أحداث الأيام الغابرة منذ أن أنشأت شعبي القديم، وما سيجيء به الغد، وليكشف عن حوادث الزمن المقبل.","44:8":"لا تجزعوا ولا تفزعوا، ألم أخبركم بهذا وأنبئكم به منذ زمن بعيد؟ أنتم شهودي. هل هناك إله غيري؟ هل هناك صخرة أخرى لا علم لي بوجودها؟","44:9":"كل صانعي التماثيل لا جدوى منهم، ومشتهياتهم لا طائل منها. وهم شهود عليها أنها لا تبصر ولا تعلم لكي يخزوا.","44:10":"من يصور صنما أو يسبك تمثالا لا ترتجى منه فائدة؟","44:11":"هذا وأمثاله يلحق بهم العار لأن الصناع ليسوا سوى بشر. فليجتمعوا إذا ويمثلوا أمامي، فينتابهم رعب ويخزوا معا.","44:12":"يصنع الحداد فأسا بعد أن يقلبها في جمرات الكور ويطرقها، ويشكلها بذراعه القوية. لا يعبأ بالجوع ولا بنضوب قوته، ولا بالعطش والإعياء.","44:13":"ثم يأتي نجار فيتناول قطعة خشب ويمد عليها الخيط ويعلمها وينعمها ويحفر عليها بالبركار صورة إنسان ساحر الجمال لينصبه صنما في منزل.","44:14":"يقطع شجرة أرز أو يختار سنديانا أو بلوطا. يتركها تنمو بين أشجار الغابة. أو يزرع شجرة صنوبر فينميها المطر.","44:15":"ثم تصبح وقودا لنيران الناس: يأخذ بعضا منها ليدفيء نفسه، أو يوقده ليخبز خبزه، أو ينحت منه إلها يعبده، يصنع منه تمثالا يخر أمامه ساجدا.","44:16":"يوقد نصفه في النار وعلى نصفه الآخر يأكل لحما، يشوي شواء ويشبع، ويدفيء نفسه قائلا: آه، أنا مستدفيء، وأرى نارا.","44:17":"ويصنع ما تبقى منه إلها، صنما يخر أمامه ساجدا مبتهلا إليه قائلا: أنقذني. أنت إلهي.","44:18":"إنهم لا يفقهون ولا يدركون، إذ غشي على عيونهم فلا يبصرون، وأغلق على قلوبهم فلا يفهمون.","44:19":"ليس من متأمل أو ذي معرفة أو إدراك يقول: قد أحرقت نصف الشجرة بالنار وخبزت خبزي على جمراتها، شويت لحما عليها وأكلته. أفأصنع من بقيتها رجسا وأسجد أمام قطعة خشب؟","44:20":"لكأنه يأكل الرماد! يجري وراء سراب ويعجز عن إنقاذ نفسه أو الاعتراف أن الصنم الذي يمسكه بيده هو محض ضلال!","44:21":"اذكر هذه الأمور يايعقوب، لأنك أنت عبدي ياإسرائيل، قد جبلتك فأنت عبدي، وأنا لا أنساك ياإسرائيل.","44:22":"قد محوت كغيمة عابرة ذنوبك، وكسحابة خطاياك. ارجع تائبا إلي لأني قد فديتك.","44:23":"ترنمي أيتها السماوات لأن الرب قد أنجز فعله. اهتفي ياأعماق الأرض، وتفجري غناء ياجبال وياغابات وكل ما فيها من شجر، لأن الرب قد افتدى يعقوب وتمجد في إسرائيل.","44:24":"هذا ما يقوله الرب فاديك وجابلك من الرحم: «أنا هو الرب صانع كل الأشياء، الذي نشر السماوات وحده، وبسط الأرض بنفسه. من كان معي حينذاك؟","44:25":"يكشف نفاق المخادعين، ويفضح حمق العرافين، ويبطل مشورة الحكماء تسفيها لعلمهم.","44:26":"أنا هو متمم كلام عبده، ومحقق مشورة رسله، القائل عن أورشليم: لابد أن تعود عامرة وعن مدن يهوذا: لابد أن تبنى، وأنا أعيد تشييد خربها.","44:27":"القائل للجة: جفي وأنا أنشف أنهارك.","44:28":"القائل عن كورش: هو راعي الذي يلبي كل رغباتي والقائل عن أورشليم: لابد أن تبنى وعن الهيكل: لابد أن يؤسس (من جديد)».","45:1":"هذا ما يقوله الرب لكورش مختاره، الذي أخذت بيمينه حتى أخضع أمامه أمما وأكسر شوكة ملوك، لأفتح أمامه كوات ولا توصد في وجهه مصاريع.","45:2":"ها أنا أتقدمك لأسوي الجبال بالأرض وأحطم أبواب النحاس، وأكسر مغاليق الحديد،","45:3":"وأهبك كنوز الأقبية المظلمة وذخائر المخابيء، لتعرف أني أنا هو الرب إله إسرائيل الذي دعاك باسمك.","45:4":"لأجل عبدي يعقوب، وإسرائيل مختاري دعوتك باسمك، لقبتك من غير أن تعرفني.","45:5":"أنا هو الرب ولا إله غيري. ليس هناك آخر، شددتك مع أنك لم تعرفني.","45:6":"حتى يدرك الناس من مشرق الشمس ومن مغربها أني أنا هو الرب وليس هناك آخر.","45:7":"أنا مبدع النور وخالق الظلمة، أنا صانع الخير وخالق الضر، أنا هو الرب فاعل كل هذه.","45:8":"اهطلي أيتها السماوات من فوق، وأمطري ياغمام برا، لتنفتح الأرض حتى يثمر الخلاص، وينبت البر. أنا خلقته.","45:9":"ويل لمن يخاصم صانعه وهو ليس سوى قطعة خزف من خزف الأرض. أيقول الطين لجابله: ماذا تصنع؟ أو إن ما عملته تنقصه يدان؟","45:10":"ويل لمن يقول لوالد: ماذا أنجبت؟ أو لأم: بماذا تتمخضين؟","45:11":"هذا ما يقوله الرب قدوس إسرائيل وصانعه: أتسألونني في سياق الأحداث الآتية عن أبنائي، أم توصونني بعمل يدي؟","45:12":"لقد صنعت الأرض وخلقت الإنسان عليها، ويداي هما اللتان بسطتا السماوات، وأنا أمرت كواكبها.","45:13":"أنا أقمت كورش ليجري العدل، وأنا أمهد طرقه كلها، فيبني مدينتي ويطلق سراح أسراي، لا بثمن ولا لقاء مكافأة، يقول الرب القدير.","45:14":"يقول الرب: يأتي إليكم المصريون والكوشيون والسبئيون بكل ما يملكونه من ثروات، ويضعونها عند أقدامكم، ويصيرون رعاياكم، يمشون خلفكم مصفدين بالأغلال، ويخرون ساجدين أمامكم قائلين: حقا إن الرب معكم ولا إله سوى إلهكم. هو وحده الإله لا غيره.","45:15":"حقا أنت هو إله يحجب نفسه، إله إسرائيل المخلص.","45:16":"لقد خزوا وخجلوا جميعهم، ومضى صانعو الأصنام وهم يجرون أذيال العار.","45:17":"أما إسرائيل فقد خلصه الرب بخلاص أبدي، ولن يلحقكم عار أو خزي مدى الدهور،","45:18":"لأن هكذا يقول الرب خالق السماوات، «إنه الله مكون الأرض وصانعها، ومرسي قواعدها: لم يخلقها لتكون خواء، بل لتصبح آهلة بسكانها. أنا هو الرب وليس هناك آخر.","45:19":"لم أتكلم خفية بكلامي في أرض الظلمة، ولم أطلب من ذرية يعقوب أن يلتمسوني باطلا. أنا الرب الناطق بالحق، أعلن ما هو صدق.","45:20":"اجتمعوا وتعالوا. اقتربوا معا أيها الناجون من الأمم، فإن الجهال وحدهم هم الذين يحملون الأصنام الخشبية ويواظبون على الصلاة لإله لا يخلص.","45:21":"أعلنوا، واعرضوا دعواكم. ليتشاوروا معا. من أنبأ بهذا منذ القدم، ومن أخبر به من زمن بعيد؟ ألست أنا الرب ولا إله غيري؟ بار ومخلص، وليس هناك آخر.","45:22":"التفتوا إلي واخلصوا ياجميع أقاصي الأرض، لأني أنا الله وليس هناك آخر.","45:23":"لقد أقسمت بذاتي، وخرجت من فمي، بكل صدق، كلمة لا تنقض: إنه ستجثو لي كل ركبة ويقسم بي كل لسان.","45:24":"ويقولون عني: إنما بالرب وحده البر والقوة، وكل من يغتاظ منه يأتي إلى الرب ويخزى.","45:25":"أما ذرية إسرائيل فبالرب يتبررون وبه يزهون.","46:1":"قد خر وانحنى بيل ونبو إلها بابل وحملوا تماثيلهما على الحمير المرهقة التي ناءت بأثقالها.","46:2":"سقطت جميعها وعجزت عن حماية نفسها بل أخذت هي نفسها إلى السبي مع المأسورين.","46:3":"اصغوا إلي يابيت يعقوب، ويابقية ذرية إسرائيل الذين حملتهم منذ أن حبل بهم، وتكفلت بهم منذ مولدهم،","46:4":"وبقيت أنا أنا حتى زمن شيخوختكم، وحملتكم في مشيبكم. أنا صنعتكم، لذلك أنا أحملكم، وأخلصكم.","46:5":"بمن تشبهونني وتعادلونني وتقارنونني حتى نكون متماثلين؟","46:6":"هل بالذين يفرغون الذهب من الكيس ويزنون الفضة بالميزان، ويستأجرون صائغا ليسبكها إلها، ويخرون لها ساجدين؟","46:7":"يرفعونها على أكتافهم وينقلونها لينصبوها في موضعها حيث تستقر هناك لا تبرح من مكانها، وإن استغاث بها أحد لا تستجيب ولا تنجيه من محنته؟","46:8":"اذكروا هذا واتعظوا. انقشوه في أذهانكم ياعصاة!","46:9":"تذكروا الأمور الغابرة القديمة لأني أنا الله وليس آخر.","46:10":"وقد أنبأت بالنهاية منذ البدء، وأخبرت من القدم بأمور لم تكن قد حدثت بعد، قائلا: مقاصدي لابد أن تتم، ومشيئتي لابد أن تتحقق.","46:11":"أدعو من المشرق الطائر الجارح، ومن الأرض البعيدة رجل مشورتي. قد نطقت بقضائي ولابد أن أجريه، وما رسمته من خطة لابد أن أنفذه.","46:12":"أصغوا إلي ياغلاظ القلوب أيها البعيدون عن البر،","46:13":"لقد جعلت أوان بري قريبا. لم يعد بعيدا، وخلاصي لا يبطيء. سأجعل خلاصا في صهيون، وفي إسرائيل مجدي.","47:1":"انزلي واجلسي على التراب أيتها العذراء ابنة بابل. اجلسي على الأرض لا على العرش ياابنة الكلدانيين، لأنك لن تدعي من بعد الناعمة المترفهة.","47:2":"خذي حجري الرحى واطحني الدقيق. اكشفي نقابك، وشمري عن الذيل، واكشفي عن الساق، واعبري الأنهار،","47:3":"فيظل عريك مكشوفا وعارك ظاهرا، فإني أنتقم ولا أعفو عن أحد.","47:4":"إن فادينا، الرب القدير اسمه، هو قدوس إسرائيل.","47:5":"اجلسي صامتة وأوغلي في الظلام ياابنة الكلدانيين، لأنك لن تدعي بعد سيدة الممالك.","47:6":"قد سخطت على شعبي ونجست ميراثي. أسلمتهم إلى يديك، فلم تبدي نحوهم رحمة بل أرهقت الشيخ بنيرك الثقيل جدا.","47:7":"وقلت: سأظل السيدة إلى الأبد. لذلك لم تفكري بهذه الأمور في نفسك ولا تأملت بما تؤول إليه.","47:8":"فالآن اسمعي هذا أيتها المترفهة المتنعمة المطمئنة، القائلة في قلبها: أنا وحدي وليس هناك غيري، لن أعرف الترمل ولن أثكل","47:9":"لذلك ستبتلين بكلا الأمرين معا في لحظة، في يوم واحد، إذ تثكلين وتترملين حتى النهاية على الرغم من كثرة سحرك وقوة رقاك.","47:10":"قد تولتك طمأنينة في شرك، وقلت: لا يراني أحد ولكن حكمتك ومعرفتك أضلاك، فقلت في نفسك: أنا وحدي، وليس هناك غيري.","47:11":"سيدهمك شر لا تدرين كيف تدفعينه عنك، وتباغتك داهية تعجزين عن التكفير عنها، ويفاجئك خراب لا تتوقعينه.","47:12":"تشبثي برقاك وكثرة سحرك التي تعبت فيها منذ صباك، فقد يحالفك النجاح أو تثيرين الرعب.","47:13":"لقد ضعفت من كثرة طلب المشورة، فادعي المنجمين والفلكيين ليكشفوا لك طوالع المستقبل وينقذوك مما يأتي عليك.","47:14":"غير أنهم أنفسهم أصبحوا كالهشيم الذي تلتهمه النار عاجزين عن إنقاذ أنفسهم وإنقاذك من شدة اللهب المحرق، فلا هو جمر للاستدفاء ولا هي نار للجلوس حولها.","47:15":"هكذا يجري على الذين تعبت فيهم وتاجروا معك منذ صباك، قد شرد كل منهم في طريقه وليس من ينقذك.","48:1":"اسمعوا هذا يابيت يعقوب المدعوين باسم إسرائيل الخارجين من صلب يهوذا، الحالفين باسم الرب، المستشهدين بإله إسرائيل باطلا وكذبا","48:2":"الذين يدعون أنفسهم أهل المدينة المقدسة، ويعتمدون على إله إسرائيل، الرب القدير:","48:3":"قد أنبأت بالأمور الغابرة منذ القدم، نطقت بها وأذعتها، ثم فجأة صنعتها وأتممتها","48:4":"لأني عالم بعنادك، وأن رقبتك ذات عضل من حديد وجبهتك من نحاس.","48:5":"لهذا أنبأت بها منذ القدم وأعلنتها لك من قبل أن تتحقق، لئلا تقول: إن وثني قد صنعها، وتمثالي المنحوت وإلهي المسبوك قد قضى بها.","48:6":"قد سمعت، فتأمل فيها كلها، ألا تقر بها؟ منذ الآن وصاعدا سأطلعك على أمور جديدة، على أسرار لم تعرفها من قبل.","48:7":"قد خلقت الآن وليس منذ زمن بعيد، لم تسمع بها قط قبل هذا اليوم، لئلا تقول: كنت أعرفها.","48:8":"أنت لم تسمع قط ولم تعرف أبدا، فمنذ القدم لم تنفتح أذناك، لأني عرفت أنك تتصرف بغدر، ومنذ مولدك دعيت متمردا","48:9":"ولكن من أجل اسمي أبطيء غضبي، وأكبحه عنك من أجل حمدي حتى لا أستأصلك.","48:10":"نقيتك وليس كالفضة وامتحنتك في كور الألم.","48:11":"قد فعلت هذا من أجل ذاتي، نعم من أجل ذاتي إذ كيف يدنس اسمي؟ أنا لا أعطي مجدي لآخر.","48:12":"اسمع لي يايعقوب، وياإسرائيل الذي دعوته. أنا هو الأول والآخر.","48:13":"قد أرست يدي قواعد الأرض، وبسطت يميني السماوات، أدعوهن فيمثلن معا.","48:14":"اجتمعوا كلكم وأنصتوا: من من بين الأصنام أنبأ بهذه؟ إن الرب أحب كورش، وهو ينفذ قضاءه على بابل ويكون ذراعه على الكلدانيين.","48:15":"لقد دعوت أنا بذاتي (كورش) وعهدت إليه بما أريد، وسأكلل أعماله بالنجاح","48:16":"اقتربوا مني واسمعوا: منذ البدء لم أتكلم خفية، ولدى حدوثها كنت حاضرا هناك. والآن، قد أرسلني السيد الرب وروحه بهذه الرسالة:","48:17":"هذا ما يقوله الرب فاديك قدوس إسرائيل: أنا هو الرب إلهك الذي يعلمك ما فيه نفع لك، ويهديك في النهج الذي عليك أن تسلكه.","48:18":"ليتك أطعت وصاياي لكان سلامك كالنهر، وبرك كأمواج البحر،","48:19":"ولكانت ذريتك كالرمل، ونسل أحشائك كعدد حباته، فلا يستأصل أو ينقرض اسمه من أمامي.","48:20":"اكسروا أغلال الأسر. ارحلوا عن بابل. ارفعوا أصواتكم بالغناء حتى يذيع في أرجاء الدنيا أن الرب قد فدى عبده يعقوب.","48:21":"لم يعطشوا عندما اجتاز بهم عبر الصحراء. فجر لهم المياه من الصخر. شقه فتدفقت منه المياه.","48:22":"أما الأشرار فلا سلام لهم يقول الرب.","49:1":"أنصتي إلي أيتها الجزائر، واصغوا ياشعوب البلاد البعيدة: قد دعاني الرب وأنا مازلت جنينا، وذكر اسمي وأنا ما برحت في رحم أمي.","49:2":"جعل فمي كسيف قاطع، وواراني في ظل يديه؛ صنع مني سهما مسنونا وأخفاني في جعبته،","49:3":"وقال لي: «أنت عبدي إسرائيل الذي به أتمجد","49:4":"ولكنني أجبت: لقد تعبت باطلا. وأفنيت قوتي سدى وعبثا. غير أن حقي محفوظ عند الرب، ومكافأتي عند إلهي.","49:5":"والآن قال لي الرب الذي كونني في رحم أمي لأكون له خادما، حتى أرد ذرية يعقوب إليه، فيجتمع بنو إسرائيل حوله، فأتمجد في عيني الرب ويكون إلهي قوتي:","49:6":"لكم هو يسير أن تكون لي عبدا لتستنهض أسباط يعقوب، وترد من نجيت من إسرائيل، لذلك سأجعلك نورا للأمم لتكون خلاصي إلى أقصى الأرض.","49:7":"وهذا ما يقوله الرب فادي إسرائيل وقدوسه لمن صار محتقرا ومرذولا لدى الأمم وعبدا للمتسلطين: يراك الملوك وينهضون، ويسجد لك الرؤساء من أجل الرب الأمين، قدوس إسرائيل الذي اصطفاك.","49:8":"وهذا ما يقوله الرب: «استجبتك في وقت رضى، وفي يوم خلاصي أعنتك فأحفظك وأعطيك عهدا للشعب لتسترد الأرض وتورث الأملاك التي داهمها الدمار،","49:9":"لتقول للأسرى: اخرجوا، وللذين في الظلمة اظهروا، فيرعون في الطرقات وتصبح الروابي الجرداء مراعي لهم.","49:10":"لا يجوعون ولا يعطشون، ولا يعييهم لهيب الصحراء ولا لفح الشمس، لأن راحمهم يهديهم ويقودهم إلى ينابيع المياه.","49:11":"وأجعل كل جبالي سبيلا، وطرقي ترتفع.","49:12":"انظروا، ها هم يقبلون من ديار بعيدة، هؤلاء من الشمال والغرب، وهؤلاء من أرض سينيم.","49:13":"فاهتفي فرحا أيتها السماوات، وابتهجي أيتها الأرض، وأشيدي بالترنيم أيتها الجبال، لأن الرب عزى شعبه ورأف ببائسيه.","49:14":"«لكن أهل صهيون قالوا: لقد أهملنا الرب ونسينا.","49:15":"هل تنسى المرأة رضيعها ولا ترحم ابن أحشائها؟ حتى هؤلاء ينسين، أما أنا فلا أنساكم.","49:16":"انظروا ها أنا قد نقشتك ياصهيون على كفي، وأسوارك لا تبرح من أمامي.","49:17":"أسرع إليك أولادك بناؤوك، وفارقك هادموك ومخربوك.","49:18":"ارفعي عينيك وتلفتي حولك وانظري، فقد اجتمع أبناؤك وتوافدوا إليك. حي أنا يقول الرب، فإنك ستتزينين بهم كالحلي وتتقلدينهم كعروس","49:19":"وتعج أرضك الخربة وديارك المتهدمة، ومناطقك المدمرة بالسكان حتى تضيق بهم، ويبتعد عنك مبتلعوك.","49:20":"ويقول أيضا في مسامعك بنوك المولودون في أثناء ثكلك: إن المكان أضيق من أن يسعنا، فأفسحي لنا حتى نسكن.","49:21":"فتسألين نفسك: من أنجب لي هؤلاء وأنا ثكلى وعاقر، منفية ومنبوذة؟ من ربى لي هؤلاء؟ فقد تركت وحدي، أما هؤلاء فمن أين جاءوا؟","49:22":"وهذا ما يقوله السيد الرب: ها أنا أرفع يدي إلى الأمم وأنصب رايتي إلى الشعوب، فيحملون أبناءك في أحضانهم وبناتك على أكتافهم.","49:23":"يكون لك الملوك آباء مربين، وملكاتهم مرضعات، ينحنون أمامك بوجوه مطرقة إلى الأرض، ويلحسون تراب قدميك. عندئذ تدركين أنني أنا الرب، وكل من يتكل علي لا يخزى».","49:24":"هل تسلب الغنيمة من المحارب الجبار؟ أو يفلت الأسرى من قبضة الغالب؟","49:25":"نعم سبي الجبار يسلب منه، وتسترد الغنيمة من الغالب، لأنني أخاصم مخاصميك وأنقذ أبناءك،","49:26":"وأجعل مضطهديك يلتهمون لحوم أجسادهم، ويسكرون بدمهم كمن يشرب خمرا. عندئذ يدرك كل ذي جسد أنني أنا الرب مخلصك وفاديك إله يعقوب القدير.","50:1":"هذا ما يقوله الرب: أين كتاب طلاق أمكم الذي طلقتها به؟ لمن من دائني بعتكم؟ إنما من أجل ذنوبكم قد تم بيعكم، ومن جراء خطاياكم قد طلقت أمكم.","50:2":"فمالي إذا حين أتيت لم أجد أحدا؟ ناديت ولا من مجيب؟ هل قصرت يدي عن الفداء؟ أم لم تعد لي طاقة على الإنقاذ؟ ها أنا بزجرتي أجفف البحر وأحول الأنهار إلى صحراء ينتن سمكها لخلوها من الماء، فيموت من العطش.","50:3":"أغلف السماوات بالظلمة وأجعل المسح غطاء لها.","50:4":"السيد الرب وهبني منطق العلماء لأعرف كيف أغيث المتعب بكلمة، ينبهني في كل صباح، ويرهف أذني حتى أسمع بانتباه المتعلمين.","50:5":"قد فتح السيد الرب أذني فلم أعاند أو أتراجع إلى الوراء","50:6":"بذلت ظهري للضاربين، وخدي للناتفين، ولم أحجب وجهي عن الإهانة والبصق.","50:7":"لأن السيد الرب يغيثني فلا أخزى، لذلك جعلت وجهي كالصوان، لأني عالم أنني لن أخزى.","50:8":"إن منصفي قريب، فمن إذا يخاصمني؟ فلنمثل معا. من هو خصمي؟ فليتقدم مني.","50:9":"انظروا، ها السيد الرب يغيثني فمن يستذنبني؟ ها هم جميعا كثوب يبلون ويأكلهم العث.","50:10":"من منكم يتقي الرب ويطيع صوت خادمه؟ من الذي يسلك في الظلمة من غير نور؟ فليتكل على اسم الرب ويعتمد على إلهه.","50:11":"انظروا، ياجميع موقدي النار، الذين يضيئون لأنفسهم مشاعل، سيروا في نور نيرانكم، وعلى وهج مشاعلكم التي أوقدتموها، وهذا ما تنالونه من يدي؛ تضطجعون وأنتم تتضورون من الألم.","51:1":"اسمعوا لي ياملتمسي البر، الساعين وراء الرب: تلفتوا إلى الصخر الذي منه نحتم، وإلى المحجر الذي منه اقتلعتم.","51:2":"انظروا إلى إبراهيم أبيكم وإلى سارة التي أنجبتكم، فقد دعوته حين كان فردا واحدا وباركته وأكثرته.","51:3":"الرب يعزي صهيون ويعزي خرائبها، ويحول قفرها إلى عدن وصحر اءها إلى جنة رائعة، فتفيض بالفر ح والغبطة والشكر وهتاف ترنيم.","51:4":"اسمعوا لي ياشعبي، واصغي إلي ياأمتي، فإن الشريعة تصدر مني، وعدلي يصبح نورا للشعوب.","51:5":"بري بات قريبا، وتجلى خلاصي، وذر اعاي تقضيان للشعوب، وإياي ترتقب الجزائر، وتنتظر برجاء ذراعي.","51:6":"ارفعوا عيونكم إلى السماوات وتفرسوا في الأرض من تحت، فإن السماوات كدخان تضمحل، والأرض كثوب تبلى، ويبيد سكانها كالذباب. أما خلاصي فيبقى إلى الأبد، وبري يثبت مدى الدهر.","51:7":"استمعوا إلي ياعارفي البر، أيها الشعب الذي شريعتي في قلوبكم. لا تخشوا تعيير الناس ولا ترتعبوا من شتائمهم،","51:8":"لأن العث يأكلهم كثوب، ويقرضهم السوس كالصوف، أما بري فيبقى إلى الأبد، وخلاصي يثبت مدى الدهر.","51:9":"استيقظي، استيقظي، تسربلي بالقوة ياذراع الرب، استيقظي كالعهد بك في الأيام القديمة، وفي الأجيال الغابرة. ألست أنت التي مزقت رهب إربا إربا، وطعنت التنين؟","51:10":"ألست أنت التي جففت البحر، ومياه اللجج العميقة، وجعلت أعماق البحر طريقا يعبر فوقه المفديون؟","51:11":"سيرجع الذين افتداهم الرب ويأتون إلى صهيون بترنم، يكلل رؤوسهم فرح أبدي، فتطغى عليهم بهجة وغبطة، أما الحزن والتنهد فيهربان بعيدا.","51:12":"أنا، أنا هو معزيكم، فمن أنت حتى تخشي إنسانا فانيا أو بشرا يبيدون كالعشب؟","51:13":"ونسيت الرب صانعك، باسط السماوات ومرسي قواعد الأرض فتظل في رعب دائم من غضب المضايق حين يوطد العزم على التدمير؟ أين هو غضب المضايق؟","51:14":"عما قريب يطلق سراح المنحني فلا يموت في أعماق الجب ولا يفتقر إلى الخبز.","51:15":"لأني أنا هو الرب إلهك الذي يهيج البحر فتصطخب أمواجه، الرب القدير اسمه.","51:16":"قد وضعت كلامي في فمك، وواريتك في ظل يدي، لأقر السماوات في موضعها وأرسي قواعد الأرض، وأقول لصهيون: أنت شعبي.","51:17":"استيقظي، استيقظي، انهضي ياأورشليم، يامن تجرعت من يد الرب كأس غضبه، يامن شربت ثمالة كأس الترنح.","51:18":"لم يكن بين أبنائها الذين أنجبتهم من يهديها، ولا من يأخذ بيدها من كل البنين الذين ربتهم.","51:19":"لقد ابتليت بهاتين المحنتين، فمن يرثي لك: التدمير والخراب، والمجاعة والسيف، فمن يعزيك؟","51:20":"قد أعيا أبناؤك وانطرحوا عند رأس كل شارع كوعل وقع في شبكة. امتلأوا من غضب الرب ومن زجر إلهك.","51:21":"لذلك اسمعي هذا أيتها المنكوبة، والسكرى ولكن من غير خمر.","51:22":"هذا ما يقوله سيدك الرب، إلهك الذي يدافع عن دعوى شعبه: ها أنا قد أخذت من يدك كأس الترنح، ولن تجرعي من كأس غضبي بعد.","51:23":"وأضعها في يد معذبيك الذين قالوا لك: انحني حتى ندوس عليك عابرين. فجعلت ظهرك لهم أرضا، وطريقا لهم يمرون عليه.","52:1":"استيقظي، استيقظي تسربلي بقوتك ياصهيون، ارتدي ثياب بهائك ياأورشليم، المدينة المقدسة، إذ لن يدخلك بعد اليوم أغلف ولا نجس.","52:2":"انفضي عنك الغبار، وانهضي واجلسي وفكي عن عنقك الأغلال ياأورشليم، أيتها المسبية ابنة صهيون،","52:3":"لأن هذا ما يقوله الرب: قد تم بيعكم مجانا، ومجانا من غير فضة تفدون.","52:4":"قد نزل شعبي أولا إلى مصر ليتغرب هناك، ثم جار عليه الأشوريون من غير سبب.","52:5":"والآن ماذا لدي هناك؟ يقول الرب، فقد استعبد شعبي مجانا، صاح عليه المتسلطون ساخرين، وظلوا يجدفون على اسمي كل يوم.","52:6":"لذلك يعرف شعبي اسمي، وفي ذلك اليوم يدركون أني أنا هو المتكلم، وأني أنا هنا.","52:7":"ما أجمل على الجبال وقع قدمي المبشر الذي يذيع سلاما وينشر بشائر الخير، القائل لصهيون: قد ملك إلهك!","52:8":"ها رقباؤك قد رفعوا صوتهم معا وشدوا بفرح، لأنهم يشهدون عيانا رجوع الرب إلى صهيون.","52:9":"اهتفي مترنمة ياأرض أورشليم الخربة، لأن الرب قد عزى شعبه وافتدى أورشليم.","52:10":"شمر الرب عن ذراع قدسه أمام عيون كل الأمم، فترى أقاصي الأرض خلاص إلهنا.","52:11":"انصرفوا، انصرفوا واخرجوا من هناك ولا تمسوا نجسا. اخرجوا من وسط بابل، وطهروا أنفسكم ياحاملي آنية الرب.","52:12":"لأنكم لن تخرجوا من بابل في عجلة، ولن تغادروها هاربين، لأن الرب سيسير أمامكم، وإله إسرائيل يحرس مؤخرة قافلتكم.","52:13":"ها هو عبدي يفلح، ويتعظم ويتعالى ويتسامى جدا.","52:14":"وكما دهش منه كثيرون، إذ تشوه منظره أكثر من أي رجل، وصورته أكثر من بني البشر،","52:15":"فإنه هكذا يذهل أمما عديدة فيكم ملوك أفواههم أمامه، إذ شهدوا ما لم يخبروا به، وأدركوا مالم يسمعوه.","53:1":"من آمن بكلامنا، ولمن ظهرت يد الرب؟","53:2":"نما كبرعم أمامه، وكجذر في أرض يابسة، لا صورة له ولا جمال يسترعيان نظرنا، ولا منظر فنشتهيه.","53:3":"محتقر ومنبوذ من الناس، رجل آلام ومختبر الحزن، مخذول كمن حجب الناس عنه وجوههم فلم نأبه له.","53:4":"لكنه حمل أحزاننا وتحمل أوجاعنا، ونحن حسبنا أن الرب قد عاقبه وأذله،","53:5":"إلا أنه كان مجروحا من أجل آثامنا ومسحوقا من أجل معاصينا، حل به تأديب سلامنا، وبجراحه برئنا.","53:6":"كلنا كغنم شردنا ملنا كل واحد إلى سبيله، فأثقل الرب كاهله بإثم جميعنا.","53:7":"ظلم وأذل، ولكنه لم يفتح فاه، بل كشاة سيق إلى الذبح، وكنعجة صامتة أمام جازيها لم يفتح فاه.","53:8":"بالضيق والقضاء قبض عليه، وفي جيله من كان يظن أنه استؤصل من أرض الأحياء، وضرب من أجل إثم شعبي؟","53:9":"جعلوا قبره مع الأشرار، ومع ثري عند موته. مع أنه لم يرتكب جورا، ولم يكن في فمه غش.","53:10":"ومع ذلك فقد سر الله أن يسحقه بالحزن. وحين يقدم نفسه ذبيحة إثم فإنه يرى نسله وتطول أيامه، وتفلح مسرة الرب على يده.","53:11":"ويرى ثمار تعب نفسه ويشبع، وعبدي البار يبرر بمعرفته كثيرين ويحمل آثامهم.","53:12":"لذلك أهبه نصيبا بين العظماء، فيقسم غنيمة مع الأعزاء، لأنه سكب للموت نفسه، وأحصي مع أثمة. وهو حمل خطيئة كثيرين، وشفع في المذنبين.","54:1":"ترنمي أيتها العاقر التي لم تنجب، أشيدي بالترنم والهتاف يامن لم تقاسي من المخاض، لأن أبناء المستوحشة أكثر من أبناء ذات الزوج، يقول الرب.","54:2":"وسعي فسحة خيمتك وابسطي ستائر مساكنك، لا تضيقي. أطيلي حبال خيمتك ورسخي أوتادك،","54:3":"لأنك ستمتدين يمينا وشمالا، ويرث نسلك أمما ويعمرون المدن الخربة،","54:4":"لا تجزعي لأنك لن تخزي، ولا تخجلي لأنه لن يلحق بك عار، فأنت ستنسين خزي صباك، ولن تذكري من بعد عار ترملك.","54:5":"لأن صانعك هو بعلك، والرب القدير اسمه، وفاديك هو قدوس إسرائيل الذي يدعى إله كل الأرض.","54:6":"قد دعاك الرب كزوجة مهجورة مكروبة الروح، كزوجة عهد الصبا المنبوذة، يقول الرب.","54:7":"لقد هجرتك لحظة، ولكني بمراحم كثيرة أجمعك.","54:8":"في لحظة غضب جامح حجبت وجهي عنك، ولكني بحب أبدي أرحمك، يقول الرب فاديك.","54:9":"لأن هذا الأمر نظير أيام نوح، حين أقسمت أن لا تعود مياه طوفان تفيض على الأرض، كذلك أقسمت أن لا أغضب عليك أو أزجرك.","54:10":"إن الجبال تزول والتلال تتزحزح، أما رحمتي الثابتة فلا تفارقك، وعهد سلامي لا يتزعزع، يقول الرب راحمك.","54:11":"أيتها المنكوبة وغير المتعزية، التي اقتلعتها العاصفة، ها أنا أبني بالأثمد حجارتك، وأرسي أساساتك بالياقوت الأزرق،","54:12":"وأصنع شرفك من ياقوت، وأبوابك من حجارة بهرمان، وكل أسوارك من حجارة كريمة","54:13":"يكون جميع أبنائك تلاميذ الرب، ويعمهم سلام عظيم.","54:14":"بالبر يتم ترسيخك، وتكونين بعيدة عن كل ضيق فلن تخافي، ونائية عن الرعب لأنه لن يقترب منك.","54:15":"فإذا حشد عدو جيوشه لقتالكم، فلن يكون ذلك بأمر مني، لهذا أقضي على كل من يعاديكم وأحميكم","54:16":"ها أنا قد خلقت الحداد الذي ينفخ الفحم في النار، ويخرج أداة يعمل بها، وأنا الذي خلقت المهلك المدمر.","54:17":"لا يحالف التوفيق أي سلاح صنع لمهاجمتك، وكل لسان يتهمك أمام القضاء تفحمينه، لأن هذا هو ميراث عبيد الرب، وبرهم الذي أنعمت به عليهم»، يقول الرب.","55:1":"تعالوا أيها العطاش جميعا إلى المياه، وهلموا أيها المعدمون من الفضة، ابتاعوا وكلوا، ابتاعوا خمرا ولبنا مجانا من غير فضة.","55:2":"لماذا تنفقون الفضة على ما ليس بخبز، وتتعبون لغير شبع؟ أحسنوا الاستماع إلي، وكلوا الشهي ولتتمتع أنفسكم بالدسم.","55:3":"أرهفوا السمع وتعالوا إلي؛ أصغوا فتحيا نفوسكم، وأعاهدكم عهدا أبديا، هي مراحم داود الثابتة الأمينة","55:4":"ها أنا قد جعلته شاهدا للشعوب زعيما وقائدا للأمم.","55:5":"انظر، إنك تدعو أمما لا تعرفها، وتسعى إليك أمم لم تعرفك، بفضل الرب إلهك، ومن أجل قدوس إسرائيل، لأنه قد مجدك.","55:6":"اطلبوا الرب مادام موجودا، ادعوه وهو قريب.","55:7":"ليترك الشرير طريقه والأثيم أفكاره، وليتب إلى الرب فيرحمه، وليرجع إلى إلهنا لأنه يكثر الغفران.","55:8":"لأن أفكاري ليست مماثلة لأفكاركم، ولا طرقكم مثل طرقي، يقول الرب.","55:9":"فكما ارتفعت السماوات عن الأرض، كذلك ارتفعت طرقي عن طرقكم، وأفكاري عن أفكاركم.","55:10":"وكما تهطل الأمطار وينهمر الثلج من السماء، ولا ترجع إلى هناك، بل تروي الحقول والأشجار، وتجعل البذور تنبت وتنمو وتثمر زرعا للفلاح وخبزا للجياع،","55:11":"هكذا تكون كلمتي التي تصدر عني مثمرة دائما، وتحقق ما أرغب فيه وتفلح بما أعهد به إليها.","55:12":"لأنكم ستتركون بابل بفرح وسلام فتترنم الجبال والتلال أمامكم بهجة وتصفق أشجار الحقل بأيديها غبطة،","55:13":"وحيث كان الشوك والقراص، تنمو أشجار السرو والآس: فيكون ذلك تخليدا لاسم الرب وعلامة أبدية لا تمحى.","56:1":"هذا ما يقوله الرب: أجروا الحق، واصنعوا العدل، لأن خلاصي بات وشيكا وبري حان أن يستعلن.","56:2":"طوبى لمن يمارس هذه ويعمل بها ويكرم سبوتي؛ وطوبى لمن يصون يده عن ارتكاب الشر.","56:3":"لا يقل ابن الغريب المنضم إلى الرب: إن الرب يفصلني عن شعبه. ولا يقولن الخصي: أنا شجرة يابسة.","56:4":"لأن هذا ما يقوله الرب للخصيان الذين يحافظون على سبوتي، ويختارون ما يسرني ويتشبثون بعهدي:","56:5":"أهبهم داخل بيتي وأسواري نصيبا واسما أفضل من البنين والبنات. أعطيهم اسما مخلدا لا ينقرض.","56:6":"وأما أبناء الغرباء المنضمون إلى الرب ليخدموه ويحبوا اسمه ليكونوا له عبيدا، فكل من يحافظ على السبت منهم ولا ينقضه، ويتشبث بعهدي،","56:7":"فهؤلاء آتي بهم إلى جبلي المقدس وأفيض عليهم الفرح في بيت صلاتي، وتكون محرقاتهم وقرابينهم مقبولة على مذبحي، لأن بيتي سيدعى بيت الصلاة لجميع الأمم.","56:8":"وهذا ما يقوله السيد الرب الذي يلم شتات إسرائيل: سأجمع إليه آخرين بعد، فضلا عن الذين جمعتهم.","56:9":"تعالي ياجميع وحوش الصحراء للالتهام، وياجميع وحوش الغاب أيضا.","56:10":"فإن رقباءهم عمي، وكلهم جهال، وكلاب بكم عاجزون عن النباح، حالمون راقدون مولعون بالنوم.","56:11":"هم كلاب نهمة لا تعرف الشبع، ورعاة أيضا مجردون من الفهم، كل مال إلى طريقه طمعا في الربح،","56:12":"قائلين: تعالوا نأتي بالخمر، ونشرب مسكرا حتى الثمالة، فالغد يكون مماثلا لهذا اليوم، بل أعظم منه.","57:1":"هلك الصديق فلم يتأمل أحد في نفسه ويعتبر، ومات الأتقياء ولم يدرك أحد أن الصديق قد أخذ تفاديا للكارثة.","57:2":"والسالكون بالاستقامة ينعمون بالسلام، وفي مضاجعهم يستريحون.","57:3":"أما أنتم ياأبناء الساحرة، يانسل الفاسق والعاهرة، فادنوا من هنا.","57:4":"بمن تسخرون؟ وعلى من تفغرون أشداقكم واسعة وتدلعون ألسنتكم؟ ألستم أنتم أبناء الخطاة والمنافقين؟","57:5":"أيها المتوهجون شهوة بين أشجار البلوط، وتحت كل شجرة خضراء، يامن تذبحون أولادكم في الأودية تحت شقوق الصخور.","57:6":"إن نصيبكم هو أصنامكم من حصى الوادي الملساء. هي قرعتكم، ولها سكبتم سكيب تقدماتكم، وأصعدتم قرابينكم، فهل أرضى عن هذه الأمور؟","57:7":"نصبتم مضاجع زناكم على جبل شامخ مرتفع، وإلى هناك صعدتم لتقربوا ذبائحكم،","57:8":"وخلف الباب وقوائمه أقمتم أصنامكم، وإذ هجرتموني كشفتم عن مضاجعكم وعلوتموها ووسعتموها، وأبرمتم مع أصنامكم عهد زنى لأنكم أحببتم مضاجعهم، وتأملتم في عريهم.","57:9":"ارتحلتم إلى ملوك محملين بالدهن، وبكثرة الأطياب، وأرسلتم سفراءكم إلى أرض بعيدة، وانحدرتم حتى إلى الهاوية.","57:10":"أصابكم الإعياء من طول المسير، ولم تقولوا: «يئسنا» بل تجددت قواكم ولم تخوروا.","57:11":"ممن خفتم وارتعبتم حتى كذبتم ولم تذكروني أو تفكروا في؟ هل اعتصمت بالسكينة زمنا طويلا حتى لم تعودوا تخافونني؟","57:12":"سأتحدث عن بركم وأعمالكم، ولكنها لن تجديكم نفعا.","57:13":"عندما تستغيثون، فلتنقذكم مجموعات أصنامكم! إن الريح تحملها جميعا، ونفخة تطرحها بعيدا. أما من يلوذ بي فإنه يرث الأرض ويملك جبل قدسي.","57:14":"ويقال آنئذ: مهدوا! مهدوا السبيل، أزيلوا كل معثرة من طريق شعبي.","57:15":"لأنه هكذا يقول العلي السامي، المقيم في الأبد، الذي يدعى اسمه القدوس: إنني أسكن في العلى وفي الموضع المقدس، وأقيم مع المنسحق، وذوي الروح المتواضعة، لأحيي أرواح المتواضعين، وأنعش قلوب المنسحقين.","57:16":"لأنني لا أخاصم إلى الأبد، ولا أظل على الدوام غاضبا، لئلا تبيد أمامي روح الإنسان التي خلقتها.","57:17":"قد غضبت على إسرائيل من جراء جشعه، وعاقبته وحجبت عنه وجهي سخطا، ولكنه أوغل في عصيانه وراء غواية قلبه.","57:18":"لقد رأيت طرقه المكتوبة، إنما سأقومه وأقوده وأرد له ولنائحيه الطمأنينة","57:19":"وأستبدل نواحه بالحمد، يقول الرب؛ فيكون سلام للقريب والبعيد لأنني سأشفيه.","57:20":"أما الأشرار فهم كالبحر الهائج الذي لا يهدأ، تقذف مياهه القذر والطين","57:21":"إذ ليس سلام للأشرار، قال إلهي.","58:1":"ناد بأعلى صوتك، لا تصمت. اهتف بصوتك كنفير بوق، وأخبر شعبي بإثمهم، وذرية يعقوب بخطاياهم.","58:2":"ومع ذلك، فإنهم يلتمسونني يوميا، ويسرون بمعرفة طرقي وكأنهم أمة تصنع برا، وكأنهم لم يهملوا أحكام إلههم، يطلبون مني أحكام بر، ويغتبطون بالتقرب من الله.","58:3":"ويسألون: ما بالنا صمنا وأنت لم تلاحظ، وتذللنا ولم تحفل بذلك؟. إنكم في يوم صومكم تلتمسون مسرة أنفسكم وتسخرون جميع عمالكم.","58:4":"وها أنتم تصومون لكي تتخاصموا وتتشاجروا فقط، وتتضاربوا بكلمات أثيمة. إن مثل صومكم اليوم لا يجعل أصواتكم مسموعة في العلاء.","58:5":"أيكون الصوم الذي أختاره في إذلال المرء نفسه يوما، أو في إحناء رأسه كالقصبة، أو افتراش المسح والرماد؟ أتدعو هذا صوما مقبولا لدى الرب؟","58:6":"أليس الصوم الذي أختاره يكون في فك قيود الشر، وحل عقد النير، وإطلاق سراح المتضايقين، وتحطيم كل نير؟","58:7":"ألا يكون في مشاطرة خبزك مع الجائع، وإيواء الفقير المتشرد في بيتك. وكسوة العريان الذي تلتقيه، وعدم التغاضي عن قريبك البائس؟","58:8":"عندئذ يشع نورك كالصباح، وتزهر عافيتك سريعا، ويتقدمك برك، ويحرس مجد الرب مؤخرة ساقتك.","58:9":"عندئذ تدعو فيستجيب الرب. تستغيث فيقول ها أنا. إن أزلت من وسط بيتك النير، والإيماء بالأصبع احتقارا، والنطق بالشر،","58:10":"إن بذلت نفسك للجائع، وأشبعت حاجة الذليل، فإن نورك يشرق في الظلمة، وليلك الدامس يصبح كالظهر،","58:11":"ويهديك الرب دائما ويسد حاجتك حتى في زمن القحط والأرض المجدبة، فيقوي عظامك فتصبح كروضة مروية، وكجدول ماء لا ينقطع،","58:12":"ويبني أولادك الخرائب القديمة ويقيمون أساساتها، ويسمون بعد ذلك الشعب الذي بنى أسواره ورمم أحياء مدنه.","58:13":"إن كففت قدمك عن نقض يوم السبت، وعن السعي وراء مرامك في يومي المقدس، ودعوت يوم السبت يوم مسرة للرب، وجعلته يوما مكرما لله. إن أكرمته ولم تسلك حسب أهوائك أو تلتمس قضاء مصالحك، أو تنفقه في لغو الكلام،","58:14":"عندئذ تبتهج بالرب، وأجعلك تمتطي مرتفعات الأرض، وأنعم عليك بمير اث يعقوب أبيك، لأن فم الرب قد تكلم.","59:1":"انظروا، إن ذراع الرب ليست قاصرة حتى تعجز عن أن تخلص، ولا أذنه ثقيلة حتى لا تسمع.","59:2":"إنما خطاياكم أضحت تفصل بينكم وبين إلهكم، وآثامكم حجبت وجهه عنكم، فلم يسمع،","59:3":"لأن أيديكم تلوثت بالدم وأصابعكم بالإثم، ونطقت شفاهكم بالكذب، ولهجت ألسنتكم بالشر.","59:4":"ليس بينكم من يطالب بالعدل، أو يحكم بالحق. يتكلون على الباطل ويتفوهون بالزور، يحبلون بالغش، ويلدون بالإثم.","59:5":"يفقسون بيض أفعى، وينسجون خيوط العنكبوت. من يأكل من بيضهم يموت، ومن البيضة المكسورة تخرج حية.","59:6":"لا تصلح خيوطهم لنسيج الثياب، ولا يكتسون بأعمالهم، لأن أعمالهم هي أعمال إثم، وأفعال الظلم قد ارتكبتها أيديهم.","59:7":"تسرع أرجلهم لاقتراف الشر، ويهرولون لسفك دم البريء، أفكارهم أفكار أثيمة، وفي طرقهم دمار وخراب","59:8":"لم يعرفوا سبيل السلام، ولا عدل في مسالكهم. عوجوا طرقهم، والسالك فيها لا يعرف سلاما.","59:9":"الحق ابتعد عنا، ولم يدركنا العدل. نرتقب نورا، فيحدق بنا الظلام، وننشد ضوءا فنسلك في العتمة.","59:10":"نتحسس الحائط كالأعمى، ونتلمس كالمكفوف، نتعثر في الظهيرة كما لو كنا نسير في عتمة الليل ونكون كالأموات بين المتدفقين بالحياة","59:11":"كلنا نزمجر كالدببة، وننوح كالحمام. نبحث عن العدل فلا نجده، وعن الخلاص وإذا به قد ابتعد عنا،","59:12":"لأن معاصينا كثرت أمامك، وآثامنا تشهد علينا. فمعاصينا معنا، وذنوبنا نعرفها.","59:13":"تمردنا وتنكرنا للرب. ارتددنا عن اتباع طرق إلهنا، تفوهنا بالظلم والعصيان افتراء، وبكلام زور من القلب.","59:14":"قد ارتد عنا الإنصاف، ووقف العدل بعيدا، إذ سقط الحق صريعا في الشوارع، والبر لم يستطع الدخول.","59:15":"أضحى الحق مفقودا، والحائد عن الشر ضحية. رأى الرب ذلك فأسخطه فقدان الإنصاف.","59:16":"وإذ لم يجد إنسانا ينتصر للحق، وأدهشه أن لا يرى شفيعا، أحرزت له ذراعه انتصارا، وعضده بره.","59:17":"فتدرع بالبر وارتدى على رأسه خوذة الخلاص، واكتسى بثياب الانتقام، والتف بعباءة الغضب.","59:18":"فهو يجازيهم بمقتضى أعمالهم. يجازي أعداءه، ويعاقب خصومه، وينزل القصاص بالجزائر،","59:19":"فيتقون من المغرب اسم الرب، ومن المشرق يخشون مجد الرب، لأنه سيأتي العدو كنهر متدفق فتدفعه ريح الرب.","59:20":"ويقبل الفادي إلى صهيون، وإلى التائبين عن معاصيهم من ذرية يعقوب، يقول الرب.","59:21":"أما أنا يقول الرب، فهذا عهدي معهم: إن روحي الحال عليك وكلامي الذي لقنتك إياه، لا يزول من فمك أو من فم أبنائك أو أحفادك، من الآن وإلى الأبد.","60:1":"قومي استضيئي، فإن نورك قد جاء، ومجد الرب أشرق عليك.","60:2":"ها إن الظلمة تغمر الأرض، والليل الدامس يكتنف الشعوب، ولكن الرب يشرق عليك، ويتجلى مجده حولك،","60:3":"فتقبل الأمم إلى نورك، وتتوافد الملوك إلى إشراق ضيائك.","60:4":"تأملي حولك وانظري، فها هم جميعا قد اجتمعوا، وأتوا إليك. يجيء أبناؤك من مكان بعيد، وتحمل بناتك على الأذرع.","60:5":"عندئذ تنظرين وتتهللين، وتطغى الإثارة على قلبك، وتمتلئين فرحا لأن ثروات البحر تتحول إليك وغنى الأمم يتدفق عليك.","60:6":"تكتظ أرضك بكثرة الإبل. من أرض مديان وعيفة تغشاك بكران، تتقاطر إليك من شبا محملة بالذهب واللبان وتذيع تسبيح الرب.","60:7":"جميع قطعان قيدار تجتمع إليك، وكباش نبايوت تخدمك، تقدم قرابين مقبولة على مذبحي، وأمجد بيتي البهي.","60:8":"من هؤلاء الطائرون كالسحاب وكالحمام إلى أعشاشها؟","60:9":"فالجزائر تنتظرني، وفي الطليعة سفن ترشيش حاملة أبناءك لتأتي بهم من أرض بعيدة، ومعهم فضتهم وذهبهم، تكريما لاسم الرب إلهك ولقدوس إسرائيل لأنه قد مجدك.","60:10":"يعمر الغرباء أسوارك، ويخدمك ملوكهم، لأني في غضبي عاقبتك، وفي رضاي رحمتك.","60:11":"تنفتح أبوابك دائما ولا توصد ليل نهار، ليحمل إليك الناس ثروة الأمم، وفي موكب يساق إليك ملوكهم،","60:12":"لأن الأمة والمملكة التي لا تخضع لك تهلك، وهذه الشعوب تتعرض للخراب الساحق.","60:13":"يأتي إليك مجد لبنان بسروه وسنديانه وشربينه لتزيين موضع مقدسي، فأجعل موطيء قدمي مجيدا.","60:14":"ويقبل إليك أبناء مضايقيك خاضعين، وكل الذين احتقروك ينحنون عند قدميك، ويدعونك مدينة الرب، صهيون قدوس إسرائيل.","60:15":"وبعد أن كنت مهجورة ممقوتة لا يعبر بك أحد، سأجعلك بهية إلى الأبد، وفرح كل الأجيال،","60:16":"وتشربين لبن الأمم، وترضعين ثدي الملوك، وتدركين أني أنا الرب مخلصك وفاديك عزيز يعقوب.","60:17":"وعوضا عن النحاس أجلب لك الذهب، وبدل الحديد آتي لك بالفضة، وعوض الخشب نحاسا، وبدل الحجارة حديدا، وأجعل ولاتك مصدر سلام، ومسخريك يعاملونك بالعدل.","60:18":"ولا يسمع بظلم في أرضك، ولا بدمار أو خراب داخل تخومك، وتدعين أسوارك خلاصا، وبواباتك تسابيح.","60:19":"ولا تعود الشمس نورا لك في النهار ولا يشرق ضوء القمر عليك لأن الرب يكون نورك الأبدي، وإلهك يكون مجدك.","60:20":"ولا تغرب شمسك من بعد، ولا يتضاءل قمرك، لأن الرب يكون نورك الأبدي، وتنقضي أيام مناحتك.","60:21":"ويكون شعبك جميعا أبرارا ويرثون الأرض إلى الأبد، فهم غصن غرسي وعمل يدي لأتمجد.","60:22":"ويضحى أقلهم ألفا، وأصغرهم أمة قوية، أنا الرب أسرع في تحقيق ذلك في حينه.","61:1":"روح السيد الرب علي، لأن الرب مسحني لأبشر المساكين، أرسلني لأضمد جراح المنكسري القلوب، لأنادي للمسبيين بالعتق وللمأسورين بالحرية،","61:2":"لأعلن سنة الرب المقبولة، ويوم انتقام لإلهنا، لأعزي جميع النائحين.","61:3":"لأمنح نائحي صهيون تاج جمال بدل الرماد، ودهن السرور بدل النوح، ورداء تسبيح بدل الروح اليائسة، فيدعون أشجار البر وغرس الرب لكي يتمجد.","61:4":"فيعمرون الخرائب القديمة، ويبنون الدمار الغابر، ويرممون المدن المتهدمة، والخرب التي انقضت عليها أجيال.","61:5":"ويقوم الغرباء على رعاية قطعانكم، وأبناء الأجانب يكونون لكم حراثا وكرامين.","61:6":"أما أنتم فتدعون كهنة الرب، ويسميكم الناس خدام إلهنا، فتأكلون ثروة الأمم وتتعظمون بغناهم.","61:7":"وعوضا عن عاركم تنالون ضعفين من الميراث، وعوضا عن الهوان تبتهجون بنصيبكم، لهذا تملكون في أرضكم نصيبين، ويكون فرحكم أبديا.","61:8":"لأني أنا الرب أحب العدل وأمقت الاختلاس والظلم، وأكافئهم بأمانة، وأقطع معهم عهدا أبديا.","61:9":"وتشتهر ذريتهم بين الأمم، ونسلهم وسط الشعوب، وكل من يراهم يعرفهم، ويقر أنهم شعب باركه الرب.","61:10":"إنني أبتهج حقا بالرب وتفرح نفسي بإلهي، لأنه كساني ثياب الخلاص وسربلني برداء البر، مثل عريس يزين رأسه بتاج، وكعروس تتجمل بحليها.","61:11":"لأنه كما تنبت الأرض مزروعاتها، والحديقة تخرج نباتاتها التي زرعت فيها، هكذا السيد الرب يجعل البر والتسبيح ينبتان أمام جميع الأمم.","62:1":"إكراما لصهيون لا أصمت، ومن أجل أورشليم لا أستكين حتى يتجلى كضياء برها وخلاصها كمشعل متوهج،","62:2":"فترى الأمم برك وكل الملوك مجدك، وتدعين باسم جديد يطلقه عليك فم الرب.","62:3":"وتكونين تاج جمال في يد الرب، وإكليلا ملكيا في كف إلهك.","62:4":"ولا تعودين تدعين بالمهجورة، ولا يقال لأرضك من بعد خربة، بل تدعين «حفصيبة» (أي مسرتي بها)، وأرضك تدعى ذات بعل، لأن الرب يسر بك، وأرضك تصبح ذات بعل.","62:5":"فكما يتزوج الشاب عذراء هكذا يتزوجك أبناؤك، وكما يفرح العريس بعروسه هكذا يبتهج الرب بك.","62:6":"على أسوارك ياأورشليم أقمت حراسا يبتهلون نهارا وليلا. ياذاكري الرب لا تكفوا.","62:7":"ولا تدعوه يستكين حتى يعيد تأسيس أورشليم ويجعلها مفخرة الأرض.","62:8":"قد أقسم الرب بيمينه وبذراعه القديرة قائلا: لن أعطي حنطتك من بعد طعاما لأعدائك، ولن يشرب الغرباء خمرك التي تعبت فيها،","62:9":"بل يأكلها الذين تكبدوا مشقة زرعها، ويحمدون الله . والذين جنوا الكرم يشربون الخمر في ساحات مقدسي.","62:10":"اعبروا بالأبواب، وأعدوا طريقا للشعب. عبدوا السبيل، ونقوه من الحجارة، ارفعوا راية للشعب.","62:11":"الرب قد أذاع في كل أقاصي الأرض: قولوا لابنة صهيون قد أقبل مخلصك. ها أجرته معه وجزاؤه يتقدمه.","62:12":"ويدعونه شعبا مقدسا، مفديي الرب. وأنت تدعين «المبتغاة» والمدينة غير المهجورة.","63:1":"من هذا المقبل من أدوم، بثياب حمراء من بصرة؛ هذا المتسربل بالبهاء. السائر بخيلاء قوته؟ إنه أنا الرب الناطق بالبر، العظيم للخلاص.","63:2":"ما بال ردائك أحمر وثيابك كمن داس عنب المعصرة؟","63:3":"لقد دست المعصرة وحدي، ولم يكن معي أحد من الشعوب. قد دستهم في سخطي ووطئتهم في غيظي، فتناثر دمهم على ردائي ولطخت ثيابي.","63:4":"لأن يوم الانتقام كان كامنا في قلبي، وسنة مفديي قد أتت.","63:5":"تلفت فلم أعثر على معين، وعجبت إذ لم يكن من ناصر، فانتصرت بقوة ذراعي، وتأيدت بنجدة سخطي،","63:6":"فدست الشعوب في غيظي، وأسكرتهم في غضبي، وسكبت دماءهم فوق الأرض.","63:7":"ألهج برأفات الرب وتسابيحه وإحساناته التي أغدقها على بيت إسرائيل بفضل خيره ورحمته.","63:8":"لأنه قال: إنهم حقا شعبي وأبناء أوفياء، لن يعودوا للباطل. فخلصهم.","63:9":"فتضايق في كل ضيقاتهم، وملاك حضرته أنقذهم، وبفضل محبته وحنانه افتداهم ورفعهم وحملهم طوال الأيام الغابرة.","63:10":"لكنهم تمردوا وأحزنوا روحه فاستحال إلى عدو لهم وحاربهم بنفسه.","63:11":"ثم تذكروا الأيام القديمة، أيام موسى عبده وتساءلوا: أين من أصعدنا من البحر مع راعي قطيعه؟ أين من أقام روحه القدوس في وسطنا؟","63:12":"من جعل ذراع قوته المجيدة تسير إلى يمين موسى؟ من شق مياه البحر أمامنا ليكتسب اسما أبديا؟","63:13":"من اقتادنا في اللجج؟ فسرنا كفرس في البرية من غير أن نعثر؟","63:14":"كقطيع منحدر إلى واد، أنعم عليهم روح الرب بالراحة، هكذا هديت شعبك لتصنع لنفسك اسما مجيدا.","63:15":"تطلع من السماء وانظر من مسكنك المقدس والمجيد. أين غيرتك واقتدارك؟ قد امتنع عني لهيب أشواقك وإحساناتك.","63:16":"فأنت هو أبونا، مع أن إبراهيم لا يعرفنا، وإسرائيل لا يعترف بنا، فأنت أيها الرب، هو أبونا، واسمك فادينا منذ القديم.","63:17":"لماذا يارب تركتنا نضل عن طرقك وقسيت قلوبنا حتى لم نعد نتقيك؟ ارجع إلينا من أجل عبيدك، أسباط ميراثك.","63:18":"قد داس أعداؤنا هيكلك الذي امتلكه شعبك المقدس زمنا يسيرا،","63:19":"وأصبحنا نظير الذين لم تتسلط عليهم قط ولم يدع عليهم باسمك.","64:1":"ليتك تشق السماوات وتنزل فتتزلزل الجبال من حضرتك!","64:2":"فتكون كالنار التي تضرم الهشيم، وتجعل المياه تغلي لكي تعرف أعداءك اسمك، فترتعب الأمم من حضرتك.","64:3":"عندما أجريت أعمالا مخيفة لم نتوقعها، نزلت فتزلزلت الجبال من حضرتك.","64:4":"منذ الأزل لم يسمع أحد ولم تصغ أذن ولم تر عين إلها سواك يجري ما تصنعه للذين ينتظرونك.","64:5":"أنت تلاقي من يفرح بعمل البر ومن يسلك دائما في طرقك. لكم سخطت علينا لأننا واظبنا على ارتكاب الآثام زمانا طويلا، فكيف لمثلنا أن يخلص؟","64:6":"كلنا أصبحنا كنجس، وأضحت جميع أعمال برنا كثوب قذر، فذبلنا كأوراق الشجر وعبثت بنا آثامنا كالريح.","64:7":"ليس هناك من ينادي باسمك، ويحرص على التمسك بك لأنك حجبت وجهك عنا ولاشيتنا بسبب معاصينا.","64:8":"ومع ذلك فأنت أيها الرب أبونا، نحن الطين وأنت الخزاف، وكلنا عمل يديك.","64:9":"لا توغل في غضبك علينا يارب، ولا تذكر الإثم إلى الأبد. إنما انظر إلينا، فكلنا شعبك.","64:10":"قد استحالت مدينتك المقدسة إلى قفر، وأصبحت صهيون برية وأورشليم موحشة،","64:11":"واحترق بالنار هيكلنا المقدس البهي، الذي شدا آباؤنا فيه بتسبيحك، وصار كل ما هو أثير لدينا خرابا.","64:12":"هل بعد هذا كله تسكت يارب، وتعتصم بالصمت وتنزل بنا أشد البلاء؟","65:1":"«قد أعلنت ذاتي لمن لم يسألوا عني، ووجدني من لم يطلبني، وقلت: هأنذا لأمة لم تدع باسمي.","65:2":"بسطت يدي اليوم كله إلى شعب متمرد يسلك في طريق غير صالح، تابعين أهواءهم،","65:3":"شعب يثابر على إغاظتي في وجهي، إذ يقرب ذبائح لأصنامه في الحدائق ويحرق بخورا فوق مذابح الآجر.","65:4":"يجلس بين المقابر ويبيت الليل في أماكن سرية، ويأكل لحم الخنزير، وفي أوانيه مرق لحوم نجسة.","65:5":"ويقول أحدهم للآخر: لا تقترب مني لئلا تدنسني، لأني أقدس منك. (فيثيرون غيظي) كدخان في أنفي ونار تتقد طول النهار.","65:6":"انظروا قد كتب أمامي: لن أصمت بل أجازي، وألقي في أحضانهم","65:7":"خطاياهم وخطايا آبائهم معا يقول الرب. لأنهم أحرقوا بخورا على الجبال، وأهانوني على الآكام، فإِني أكيل أعمالهم الأولى وأطرحها في أحضانهم عقابا لهم.","65:8":"ولكن هذا ما يقوله الرب: كما أن (الكرام) لا يطرح العنقود الفاسد إذ يقال له إن في عنبه بعض الخمر الطيب، كذلك لن أطر ح من أمامي كل إسرائيل لئلا أقضي على خدامي جميعا.","65:9":"بل أخرج من صلب يعقوب ذرية، ومن يهوذا وارثا لجبالي، فيملكها مختاري، ويقيم فيها عبيدي،","65:10":"وتصبح أرض شارون مرعى للقطعان، ووادي عخور مربض بقر لشعبي الذي طلبني.","65:11":"أما أنتم الذين نبذتم الرب ونسيتم جبلي المقدس، وهيأتم مذبحا لإله «الحظ» وملأتم الكؤوس خمرا ممزوجة لإله «القدر»،","65:12":"فأجعل مصيركم الهلاك بالسيف، وتسجدون جميعا لذابحيكم لأنني دعوت فلم تجيبوا، تكلمت فلم تسمعوا، وارتكبتم الشر على مرأى مني واخترتم ما أبغضه.","65:13":"لذلك هكذا يقول السيد الرب: ها عبيدي يأكلون وأنتم تجوعون، ويشربون وأنتم تظمأون، ويفرحون وأنتم تخزون،","65:14":"ويترنمون في غبطة القلب وأنتم تعولون من أسى القلب، وتولولون من انكسار الروح،","65:15":"وتخلفون اسمكم لعنة على شفاه مختاري، ويميتكم الرب ويطلق على عبيده اسما آخر.","65:16":"فيكون كل من يبارك نفسه في الأرض إنما يبارك نفسه بالإله الحق، ومن يقسم في الأرض إنما يقسم بالإله الحق، لأن الضيقات الأولى قد نسيت واحتجبت عن عيني.","65:17":"لأنني ها أنا أخلق سماوات جديدة وأرضا جديدة، تمحو ذكر الأولى فلا تعود تخطر على بال","65:18":"إنما افرحوا وابتهجوا إلى الأبد بما أنا خالقه، فها أنا أخلق أورشليم بهجة، وشعبها فرحا.","65:19":"وأبتهج بأورشليم وأغتبط بشعبي، ولا يعود يسمع فيها صوت بكاء أو نحيب،","65:20":"ولا يكون فيها بعد طفل لا يعيش سوى أيام قلائل، أو شيخ لا يستوفي أيامه. ومن يموت ابن مئة سنة يعتبر فتى، ومن لا يبلغها يكون ملعونا.","65:21":"يغرس الناس كرومهم ويأكلون ثمارها، ويبنون بيوتهم ويقيمون فيها،","65:22":"لا يبنون ليأتي آخر فيسكن فيها، ولا يغرسون كروما ليجنيها آخر، لأن أيام شعبي تكون مديدة كأيام الشجر، ويتمتع مختاري بعمل أيديهم.","65:23":"فهم لن يتعبوا باطلا ولا تنجب نساؤهم أولادا للرعب، لأنهم يكونون ذرية مباركي الرب، ويتبارك أولادهم معهم.","65:24":"وقبل أن يدعوا أستجيب، وفيما هم يتكلمون أنصت إليهم.","65:25":"ويرعى الذئب والحمل معا، ويأكل الأسد التبن كالبقر، وتأكل الحية التراب. لا يؤذون ولا يهلكون في كل جبل قدسي، يقول الرب.","66:1":"هذا ما يقوله الرب: السماء عرشي والأرض موطيء قدمي، فأي بيت تشيدون لي؟ وأين مقر راحتي؟","66:2":"جميع هذه صنعتها يدي فوجدت كلها، لكنني أسر بالرجل المتواضع المنسحق الروح الذي يرتعد من كلمتي.","66:3":"إن من ينحر ثورا كمن يقتل إنسانا، ومن يقرب حملا كمن يكسر عنق كلب، ومن يصعد تقدمة حنطة كمن يقدم دم خنزير، ومن يحرق بخورا كمن يبارك وثنا، لأن هؤلاء آثروا طرقهم، واستطابت نفوسهم أرجاسهم.","66:4":"لهذا أنا أيضا أختار بلاياهم لهم وأوقع بهم المخاوف، لأني عندما دعوت لم يستجيبوا، وحين تكلمت لم يصغوا، إنما ارتكبوا الشر في عيني واختاروا ما لا أسر به.","66:5":"اسمعوا قول الرب أيها المرتعدون من كلامه: يسخر منكم إخوتكم الذين يكرهونكم وينبذونكم لأنكم تخافون اسمي قائلين: ليتمجد الرب حتى نشهد فرحكم. ولكنهم لا يعرفون أنهم هم الذين يخزون.","66:6":"اسمعوا صوت جلبة في المدينة، صوتا من الهيكل، صوت الرب يجازي أعداءه.","66:7":"شعبي مثل امرأة ولدت قبل أن تتمخض، وقبل أن تقاسي من الطلق أنجبت ذكرا.","66:8":"من سمع مثل هذا، ومن رأى نظيره؟ أتولد بلاد في يوم واحد؟ أم تخلق أمة دفعة واحدة؟ فما إن تمخضت صهيون حتى أنجبت أبناءها.","66:9":"يقول الرب: هل أمخض ولا أولد؟ هل أغلق الرحم وأنا المولد؟","66:10":"تهللوا مع أورشليم وافرحوا لها ياكل محبيها، ابتهجوا معها بفرح ياجميع النائحين عليها.","66:11":"لكي ترضعوا وتشبعوا من ثدي تعزياتها، ولكي تحلبوا بوفرة وتتلذذوا من درة مجدها.","66:12":"لأنه هكذا يقول الرب: ها أنا أسبغ عليها الخير كنهر، وأجري إليها ثروة الأمم كسيل متدفق، فترضعون، وتحملون في الحضن، وعلى ركبتيها تدللون.","66:13":"وأعزيكم كمن تعزيه أمه، وفي أورشليم تعزون.","66:14":"وتشهدون فتسر قلوبكم وتزدهر عظامكم كالعشب، فتصبح يد الرب معروفة عند عبيده، وينصب غضبه على أعدائه.","66:15":"لأنه ها هو الرب مقبل بنار، ومركباته كالعاصفة، ليسكب غضبه بسخط، وزجره بلهيب نار.","66:16":"لأن الرب يعاقب أهل الأرض بناره وسيفه، ويكثر قتلى الرب.","66:17":"والذين يتطهرون ويتقدسون ويقصدون إلى الحدائق حيث يعبدون وثنا قائما وراء أشجارها، يأكلون لحم الخنزير والفئران، وكل اللحوم المحرمة، مصيرهم الهلاك.","66:18":"ولأني عالم بأعمالهم وأفكارهم فأنا مزمع أن آتي لأجمع كل الأمم والألسنة، فيتوافدون ويرون مجدي","66:19":"وأجعل بينهم آية وأبعث بعض الناجين منهم إلى الأمم: إلى ترشيش، وفول، ولود، المهرة في رمي السهام، وإلى توبال وياوان وإلى الجزائر البعيدة ممن لم يسمعوا بشهرتي أو يروا مجدي، فيذيعون مجدي بين الأمم.","66:20":"ويحضرون جميع إخوتكم من سائر الأمم، تقدمة للرب، على متون الجياد، وفي المركبات والهوادج، وعلى ظهور البغال وأسنمة الجمال، إلى أورشليم جبل قدسي، كما يحضر الإسرائيليون تقدمة الحنطة في آنية طاهرة إلى بيت الرب","66:21":"ومنهم أصطفي كهنة ولاويين يقول الرب.","66:22":"لأنه كما تدوم أمامي السماوات الجديدة والأرض الجديدة التي أنا أصنعها هكذا تدوم ذريتكم وذكركم.","66:23":"ويأتي من رأس شهر إلى رأس شهر، ومن سبت إلى سبت كل بني البشر ليعبدوني،","66:24":"ثم يمضون لمشاهدة جثث الرجال الذين تمردوا علي، لأن دودهم لا يموت ونارهم لا تخمد. ويكونون مثار اشمئزاز جميع الناس."};
